COLLDATA("asabahur","ur",[[1751,"§۱۷۵۲ ۔ حصین بن یزید(1)\nبن جزی بن قطن کلبی، ابو جاہ کنیت تھی، طبری نے ان کا ذکر تو کیا ہے لیکن ان کی کوئی حدیث نقل نہیں کی۔ جبکہ ابن قانع نے جبیر اسود دیشی مولی حصین بن یزید کے طریق سے نقل کیا ہے۔ ان کی عمر ایک سو پینتیس(۱۳۵) سال ہوگئی تھی۔ بحوالہ ابو جاہ حصین بن یزید کلبی روایت کرتے ہیں، فرمایا: \"میں نے جب بھی رسول اللہ صلی اللہ علیہ وسلم کو دیکھا مسکراتے دیکھا، آپ صلی اللہ علیہ وسلم کبھی کھل کھلا کر نہیں ہنسے۔\"(2)","",{"fn":"(1) اسد الغابۃ (۱۱۹۶)\n(2) جامع المسانید (۵۳/۳۰)"}],[1752,"§۱۷۵۳ ۔ حصین بن یزید(1)\nبن شہران بن ثقان بن سلمہ بن وہب بن عبداللہ بن ربیعہ بن حارث بن کعب حارثی ذو غصہ۔ مؤتلف میں دار قطنی لکھتے ہیں: نبی صلی اللہ علیہ وسلم کے پاس آئے(2)، ایسا ہی ابن کلبی نے لکھا ہے۔ ان کا لقب اس وجہ سے پڑا کہ ان کے گلے میں پرندے کے پوٹے کی طرح ایک گہر سا تھا۔ یہ بھی کہا جاتا ہے کہ انہوں نے بنی حارث بن کعب کی سو سال سرداری کی۔ ان کے بیٹے قیس بن حصین کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابۃ (۱۱۹۷) استیعاب (۵۳۹)\n(2) السیرۃ النبویۃ (۱۸۴/۴)"}],[1753,"§۱۷۵۴ ۔ (ز) حصین بن یعفر عبسی(1)\nبنی عبس(2) کے ان نو(۹) وفود میں سے ایک جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ ابو عبیدہ، باوردی، طبری اور دار قطنی وغیرہ نے ان کا ذکر کیا ہے۔ اور ابن الاثیر نے بحوالہ اشیری ان کا اپنے استدراک میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۱۹۸)\n(2) اسد الغابۃ (۳۲/۲)"}],[1754,"§۱۷۵۵ ۔ (ز) حصین\nطلیح بن عبد اللہ معلمی کے دادا۔ خوبصورتی کی وجہ سے ان کا یہ نام پڑ گیا۔ ان شاء اللہ مہمات میں ان کی حدیث آئے گی۔"],[1755,"§۱۷۵۶ ۔ حصین انصاری سالمی\nانہیں ابوالحصین بھی کہا جاتا ہے۔ ان شاء اللہ تعالی کنیتوں میں تذکرہ ہوگا۔"],[1756,"§۱۷۵۷ ۔ حصین سدوسی\nحصین بن اوس میں ذکر ہوا ہے۔"],[1757,"§۱۷۵۸ ۔ حصین عرجی\nابو عمر:(1) ابوغوث کے حالات میں لکھتے ہیں: ان کے والد حصین فوت ہوئے تو ان پر حج لازم تھا آپ صلی اللہ علیہ وسلم نے انہیں اپنے والد کی طرف سے حج کرنے کا حکم دیا۔ ان کا ذکر (ابو عمر نے) نہیں کیا۔ البتہ ابن الامین نے ان کی کتاب پر اپنے استدراک میں ذکر کیا ہے۔","",{"fn":"(1) التمہید (۳۸۵/۱)"}],[1758,"§۱۷۵۹ ۔ (ز) حصین(1)\n(بے نسبت) ابن مندہ نے منقطع سند کے ذریعہ بحوالہ حارث بن محمد، حصین سے نقل کیا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سنا: \"ہر خاندان کا والی قیامت کے روز طوق پہنے عذاب میں مبتلا یا بخشا ہوا آئے گا۔\"(2)","",{"fn":"(1) اسد الغابۃ (۱۱۹۹)\n(2) کنز العمال (۱۴۷۲۸) المغنی عن حمل الاسفار (۳۱۵/۳) اتحاف السادۃ المتقین (۳۱۴/۸)"}],[1759,"§۱۷۶۰ ۔ (ز) حصین انصاری (بے نسبت)\nابو داؤد نے ناسخ و منسوخ میں اسباط بن نصر کے طریق سے بحوالہ سدی اور انہوں نے اوپر تک مسنداً بیان کیا ہے۔ اللہ تعالیٰ کا ارشاد: \"دین میں کوئی سختی نہیں،\" کے متعلق نقل کرتے ہیں:(1) انصار کے حصین نامی ایک شخص کے بارے میں یہ آیت نازل ہوئی۔ اس کے دو بیٹے تھے۔ شام سے تاجر آئے جنہوں نے ان دونوں کو نصرانیت قبول کرنے کی دعوت دی پھر آئندہ حدیث ذکر کی جس میں ابوالحصین نامی کنیتوں کا ذکر کیا ہے۔ طبری اور قاضی اسمعیل بن اسحاق نے کتاب \"احکام القرآن\" میں اسے درج کیا ہے۔ دونوں بطریق سدی روایت کرتے ہیں کہ ابو حصین انصاری کے دو بیٹے تھے۔ (حدیث) واحدی نے \"اسباب النزول\" میں مسروق کے طریق سے روایت کی ہے کہ انصار میں سے بنی سالم بن عوف کے قبیلہ کے ایک شخص کے دو بیٹے تھے جو نبی صلی اللہ علیہ وسلم کی بعثت سے پہلے نصرانی ہو گئے تھے۔ بعد میں انصار کے ایک گروہ کے ساتھ مدینہ منورہ اناج لائے۔ ان کے والد ان کے پاس پہنچے اور ان کے پیچھے لگے رہے کہ اللہ کی قسم! تم جب تک مسلمان نہیں ہو جاتے میں تم سے جدا نہیں ہوں گا۔ انہوں نے مسلمان ہونے سے انکار کر دیا۔ نبی صلی اللہ علیہ وسلم کے سامنے فیصلہ کے لئے گئے، ان کے والد کہنے لگے: یا رسول اللہ! کیا میری اولاد جہنم میں جائے اور میں دیکھتا رہوں؟ جس پر یہ آیت نازل ہوئی: \"کسی کو زبر دستی مسلمان بنانا دین میں ضروری نہیں\"۔ اسی روایت کو عبد بن حمید نے روح بن عبادہ سے بحوالہ موسیٰ بن عبیدہ، عبداللہ بن عبیدہ سے نقل کیا ہے۔ انصار کے قبیلے بنی سالم بن عوف کی شاخ میں ایک شخص تھا جس کے دو بیٹے تھے جو بعثت سے پہلے نصرانی ہو گئے تھے۔ پھر اس کا مفہوم ذکر کیا۔ موسیٰ ضعیف راوی ہے۔ اس روایت کو طبری نے تفسیر میں محمد بن اسحاق مغازی والے کے طریق سے بحوالہ محمد بن ابی محمد، سعید بن جبیر یا عکرمہ سے بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے: \"دین میں کوئی سختی نہیں۔ یہ آیت انصار کے سالم بن عوف کے حصین نامی شخص کے بارے میں نازل ہوئی جس کے دو بیٹے تھے اور دونوں نصرانی تھے۔ وہ خود مسلمان تھے۔ نبی صلی اللہ علیہ وسلم سے عرض کرنے لگے: انہوں نے نصرانیت قبول کر لی ہے، کیا میں ان دونوں پر سختی نہ کروں؟ جس پر اللہ تعالیٰ نے یہ حکم نازل فرمایا۔ اس کا کچھ حصہ ان شاء اللہ کنیتوں میں آئے گا جس سے اس عنوان کی تکمیل ہو جائے گی۔","",{"fn":"(1) سورۃ البقرہ (۲۵۶)"}],[1760,"§۱۷۶۱ ۔ حضرمی بن عامر(1)\nبن مجمع بن مولہ ابن حمام بن ختبہ بن کعب بن قیس بن مالک بن ثعلبہ بن رودان بن اسد بن خزیمہ اسدی۔ ابو کرم کنیت تھی۔ ابن شاہین وغیرہ نے انہیں صحابہ میں ذکر کیا ہے اور ابو یعلی و ابن قانع نے محفوظ بن علقمہ کے طریق سے بحوالہ حضرمی بن عامر اسدی جو صحابی ہیں روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم میں سے کوئی ہوا کے رُخ پیشاب نہ کرے اور نہ اپنے دائیں ہاتھ سے استنجا کرے۔(2) ابن شاہین بطریق مدائنی ابو معشر، یزید بن رومان، محمد بن کعب، سعید المقبری ان کے سلسلہ سند سے سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے، سلمہ بن محارب، داؤد، بحوالہ شعبی اور کئی اسانید ہیں، فرماتے ہیں: بنی اسد بن خزیمہ نے حضرمی بن عامر ضرار بن ازور، سلمہ بن حبیش، قتادہ بن قائف اور ابو مکعت کو وفد کی صورت میں بھیجا۔ پھر ان کے اسلام لانے کی حدیث ذکر کی ہے۔ نبی صلی اللہ علیہ وسلم نے ان کے لئے ایک تحریر لکھوائی، فرماتے ہیں: حضرمی بن عامر نے سورۃ عبس و تولی سیکھی۔ اس کی قراءت کرتے کرتے اس میں اضافہ کر دیا اور یوں یہ الفاظ بڑھا دیے: \"والذی انعم علی الحبلی فاخرج منھا سنمۃ تسعی\"۔ تو نبی علیہ السلام نے فرمایا: اس میں اضافہ نہ کرنا۔(3) اور اسے منجاب بن حارث کے طریق سے نقل کیا ہے جس میں ہے: وہ سورۃ سَبِّحِ اسْمَ رَبِّکَ الْأَعْلَیٰ تھی۔(4) ہشام بن عکلی اور شرقی بن قطامی کے طریق سے اسی قصہ کا مفہوم مروی ہے۔ عمر بن شبہ نے ابو واک تک صحیح سند سے نقل کیا ہے۔ بنو اسد آئے تو نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: تم کس قبیلے کے لوگ ہو؟ وہ کہنے لگے: ہم بنو زنیہ (آخری بچہ) گھوڑوں کے طاعت والے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں بلکہ تم بنو رشدہ ہو۔ وہ کہنے لگے: ہم اپنے باپ(5) کا نام چھوڑ نہیں سکتے، پھر لمبا قصہ ذکر کیا۔ فتوح میں سیف نے ابو ماجد اسدی کے طریق سے بحوالہ حضرمی بن عامر روایت کی ہے، فرمایا: ہمیں نبی صلی اللہ علیہ وسلم کی بیماری اور یمامہ پر مسیلمہ کذاب کے قصہ کی خبر ملی۔ پھر ارتداد کا کچھ واقعہ ذکر کیا۔ مرزبانی نے اپنی معجم میں لکھا ہے ان کی کنیت ابو کدام تھی۔ جب سیدنا عمر بن خطاب رضی اللہ عنہ نے ان سے یمجیوں کی جنگ میں کہے گئے اشعار کے متعلق پوچھا تو انہوں نے اس سلسلہ میں عمدہ اشعار سنائے۔ ابو علی القالی(6) نے ابن قتیبہ کے طریق سے روایت کی ہے کہ حضرمی بن عامر اپنے بھائیوں میں سے دسویں تھے۔ وہ سب فوت ہوئے تو یہ ان کے وارث ٹھہرے۔ اس کے متعلق ان کا عجم زاد جز بن مالک کہتا ہے: \"اے حضرمی! تجھ جیسا کون ہو سکتا ہے۔ بھائیوں کا وارث ہو کے تو خوش نہیں ہو گیا ہے۔\" تو حضرمی نے جواباً یہ اشعار کہے: \"اے جزو! اگر تم نے مجھے یہ بات جھوٹا سمجھتے کہی ہے تو (میری دعا ہے کہ) تو بھی بہت جلد ایسی صورت حال سے دوچار ہو۔\" خدا کی کرنی دیکھیں! جزو لوگ بھی دس بھائی تھے ایک دفعہ سب ایک کنویں کے کنارے بیٹھے تھے، کنواں زمین میں دھنس گیا، سوائے جزو کے سب ہلاک ہو گئے۔ حضرمی کو اس کی اطلاع ملی تو انہوں نے تقدیر کے موافق اور حد کو برقرار رکھنے والی بات کہی۔","",{"fn":"(1) اسد الغابۃ (۱۲۰۰)\n(2) کنز العمال (۳۶۷۴)\n(3) الدر المنثور (۲۱۴/۶)\n(4) سورۃ الاعلیٰ (۱)\n(5) جامع المسانید (۵۳۲/۲)\n(6) الامالی (۶۷/۱)"}],[1761,"§۱۷۶۲ ۔ حطاب بن حارث(1)\nبن معمر بن حبیب بن وہب بن حذافہ بن جمع قرشی تیمی۔ موسیٰ بن عقبہ نے مہاجرین حبشہ میں ایسا ہی ابن اسحاق اور ذیل میں طبری نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۰۱) استیعاب (۵۷۶)"}],[1762,"§۱۷۶۳ ۔ حطان تمیمی یربوعی\nابن فتون نے ذیل میں ان کا ذکر کیا ہے۔ سعید بن یحییٰ اموی فرماتے ہیں: ہمیں ہمارے والد نے بحوالہ اس شخص کے جس نے حسین بن عبد الرحمن سے سنا کہ مجھ سے عمرو بن میمون اودی نے بیان کیا کہ میں سیدنا عمر رضی اللہ عنہ کے پیچھے دوسری صف میں کھڑا تھا سیدنا عمر رضی اللہ عنہ اور میرے درمیان صرف ابن عباس رضی اللہ عنہما کھڑے تھے۔ پھر آپ کے قتل کیے جانے کا قصہ بیان کیا، فرماتے ہیں جب اسے ایک مہاجر شخص حطان تمیمی یربوعی نے دیکھا تو اس پر کپڑا ڈال دیا۔ اس پر بدحواسی میں ابو لولو کو جب یقین ہو گیا کہ وہ مارا جائے گا تو اس نے اپنی خنجر سے اپنی گردن کاٹ دی۔ میں کہتا ہوں: یہ قصہ صحیح بخاری میں حطان کے نام کے بغیر ہے۔ جبکہ دوسرے قصہ میں ہے کہ جس نے اس پر کپڑا ڈالا تھا وہ ہاشم بن عتبہ تھے اور دیگر ایک واقعہ کے مطابق وہ عبد اللہ بن عوف تھے۔ واللہ اعلم"],[1763,"§۱۷۶۴ ۔ حفشیش\nجیم میں تذکرہ ہو چکا ہے۔"],[1764,"§۱۷۶۵ ۔ (ز) حفص بن حلیمہ سعدیہ (جنہوں نے نبی صلی اللہ علیہ وسلم کو دودھ پلایا تھا)\nنبی صلی اللہ علیہ وسلم کے رضاعی بھائی۔ مجھے ان کی بحوالہ ان کی والدہ ایک روایت بطریق محمد بن عثمان لخمی، محمد بن اسحاق سے، جہم بن ابی جہم سے عبداللہ بن جعفر سے حفص بن حلیمہ سے وہ اپنی والدہ سے وہ آمنہ بنت وہب مادر بزرگوار نبی صلی اللہ علیہ وسلم سے آپ صلی اللہ علیہ وسلم کی ولادت کے قصہ میں ملی ہے۔"],[1765,"§۱۷۶۶ ۔ حفص بن سائب\nابن شاہین محمد بن جعفر فریابی کے طریق سے بحوالہ ہارون بن حفص بن سائب وہ اپنے والد سے روایت کرتے ہیں، فرمایا کہ \"نبی صلی اللہ علیہ وسلم نے میرا نام حفص رکھا۔\"(1)","",{"fn":"(1) جامع المسانید (۵۳۳/۳)"}],[1766,"§۱۷۶۷ ۔ حفص بن ابی العاص\nبن بشر بن عبد بن دہمان بن عبد اللہ بن ابان ثقفی، مشہور صحابی عثمان بن ابی العاص کے بھائی۔ ابن سعد نے چھوٹے طبقہ میں بصرہ فروش ہونے والے صحابہ میں ان کا ذکر کیا ہے اور کبریٰ میں لکھتے ہیں: ہم نے انہیں ان کے بھائی عثمان اور حکم کے ساتھ لکھا تو یہ لیکن ہمیں ان کے صحابی ہونے کے بارے میں علم نہیں۔ جبکہ خلیفہ نے ثقات میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: بار بار یہ گزر چکا ہے کہ حجۃ الوداع سے پہلے قریش اور ثقیف کا جو شخص بھی سچا تھا وہ اسلام لے آیا تھا اور سب کے سب حجۃ الوداع میں شریک ہوئے تھے۔ اتنا ان کے صحابی ہونے کے لئے کافی ہے۔ بلاذری نے ایک بے تقیہ سند سے نقل کیا ہے کہ حفص بن ابی العاص سیدنا عمر رضی اللہ عنہ کے کھانے میں شریک ہوتے تھے۔ (حدیث)"],[1767,"§۱۷۶۸ ۔ حفص بن مغیرہ\nابو عمرو مخزومی۔ بقول بعض فاطمہ بنت قیس کے شوہر، ایک قول ہے ان کا نام عمرو بن حفص بن مغیرہ، کنیت ابو حفص ہے۔ کنیتوں میں حرف عین میں عنوان آئے گا۔"],[1768,"§۱۷۶۹ ۔ (ز) الحکم ابن اقرع\nابن عمرو ہیں، تذکرہ ہوگا۔"],[1769,"§۱۷۷۰ ۔ (ز) حکم بن ایوب\nبعد والے عنوان میں آ رہا ہے۔"],[1770,"§۱۷۷۱ ۔ حکم بن حارث سلمی(1)\nانہیں حکم بن ایوب بھی کہا جاتا ہے۔ امام بخاری(2) اور ابن ابی حاتم(3) فرماتے ہیں: حکم بن حارث صحابی ہیں جن سے عطیہ الدعاء روایت کرتے ہیں۔ ابن حبان(4) کتاب الصحابہ میں لکھتے ہیں: حکم بن حارث سلمی صحابی ہیں، پھر فرماتے ہیں: حکم بن ایوب سلمی اور عطیہ الدعاء کے طریق سے روایت کی ہے۔ فرماتے ہیں: میں نے حکم بن ایوب سلمی سے سنا، فرمایا: میں لوگوں کے اگلے حصہ میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا کہ اچانک میری اونٹنی ست رفتار ہو گئی، آپ صلی اللہ علیہ وسلم نے اسے چھڑکا تو وہ سب(5) سے آگے نکل گئی۔ حدیث اسی طرح ہے حسن بن سفیان، ابن ابی عاصم اور بغوی نے عطیہ الدعاء سے بحوالہ حکم بن حارث سلمی نقل کیا ہے اسی طرح طبرانی(6) بطریق عطیہ حکم سے نقل کرتے ہیں کہ انہوں نے نبی صلی اللہ علیہ وسلم کی معیت میں تین غزوات کیے۔ اور انہوں نے انہیں وصیت کی کہ جب میری وفات ہو جائے تو دفنانے کے بعد میری قبر پر پانی چھڑکنا اور قبلہ رخ ہو کر میرے لیے دعا کرنا۔ اسے ابن اسکن نے بطریق عطیہ نبی سے ایک دوسری حدیث میں نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۰۸) استیعاب (۵۵۱)\n(2) التاریخ الکبیر (۳۳۱/۲)\n(3) الجرح والتعدیل (۱۱۵/۳)\n(4) الثقات (۸۵/۳)\n(5) مجمع الزوائد (۱۱/۹)\n(6) المعجم الکبیر (۳۱۷/۳)"}],[1771,"§۱۷۷۲ ۔ حکم بن حزن کلفی(1)\nاز بنی کلفہ بن حنظلہ بن مالک بن زید مناۃ بن تمیم، یہ نسب بقول امام بخاری ہے۔ ایک قول ہے بنی کلفہ بن عوف بن نصر بن معاویہ بن بکر بن ہوازن، اور دوسرے لوگوں کے ساتھ خلیفہ کا قول ہے۔ ان کی حدیث امام ابو داؤد اور ابو یعلی وغیرہ نے بطریق شعیب بن زرعق طائفی نقل کی ہے۔ فرماتے ہیں: میں حکم بن حزن کلفی کے پاس بیٹھا تھا جنہیں شرف صحابیت حاصل ہے۔ فرماتے ہیں: میں چھ یا آٹھ آدمیوں کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ ہم نے عرض کی یا رسول اللہ! ہم آپ کے پاس اس لئے حاضر ہوئے ہیں تاکہ آپ ہمارے حق میں دعاۓ خیر فرمائیں۔ (حدیث)(2) ابو یعلی کے الفاظ ہیں، مسلم فرماتے ہیں: ان سے صرف شعیب نے روایت لی ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۰۹) استیعاب (۵۵۰)\n(2) ابوداؤد کتاب الصلاۃ باب الرجل یخطب علی القوس (۱۰۹۶) مسند احمد (۲۱۲/۴)"}],[1772,"§۱۷۷۳ ۔ حکم بن ابی حکم اموی\nابن ابی حاتم(1) نے ان کا ذکر کیا کہ مسلمہ بن علقمہ نے داؤد بن ہند سے بحوالہ شعبی قیس بن حجر ان سے روایت کی ہے کہ ہم نے آپس میں عہد کیا کہ ہم رسول اللہ صلی اللہ علیہ وسلم............ (حدیث) طبرانی اور ابن مندہ نے اسی سند سے قیس سے روایت کی ہے کہ حکم کی بیٹی حکم سے کہنے لگی: \"اے بنی امیہ! میں نے تم سے زیادہ بری رائے اور رسول اللہ صلی اللہ علیہ وسلم کے کام میں سست قوم نہیں دیکھی\"۔ اس پر وہ بولے: بیٹا! مجھے کیوں کوستی ہو، میں نے جو دیکھا تم سے وہی بیان کروں گا۔ پھر یہ بات ذکر کی۔ (لیکن) اس میں ان کے مسلمان ہونے کی تو وضاحت نہیں۔ البتہ اس سلسلہ میں معتبر یہی ہے کہ فتح مکہ کے بعد کوئی قریشی غیر مسلم نہیں رہا بلکہ مسلمان ہو کر حجۃ الوداع(2) میں شریک ہوا۔ اس حدیث کو عسکری نے اسی طرح روایت کیا ہے۔ پھر فرمایا: بعض لوگ کہتے ہیں، اس حدیث میں حکم بن ابی العاص یعنی سیدنا عثمان کے چچا ہیں جن کا ذکر آئے گا، جہاں تک ابو عمر ہیں تو انہوں نے اس پر یقین کیا ہے کہ وہ اور ہیں۔ وہ لکھتے ہیں: مجہول ہیں، مجھے ان کے متعلق اس حدیث سے زیادہ کسی بات کا علم نہیں، جبکہ ابن الاثیر نے عسکری کی بات کو درست قرار دیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۱۱۵/۳)\n(2) جامع المسانید (۵۳۹/۲)"}],[1773,"§۱۷۷۴ ۔ حکم بن ابی الحکم انصاری(1)\nغزوہ تبوک میں ان کا ذکر ملتا ہے۔ ابن مندہ نے ان کا ذکر کیا ہے۔ عنقریب کعب بن خزرج کے حالات میں ان کا ذکر آئے گا کہ وہ غزوہ تبوک میں نبی صلی اللہ علیہ وسلم کے ساتھ شریک تھے۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۰)"}],[1774,"§۱۷۷۵ ۔ (ز) حکم بن حیان عبدی ثم نجاری\nمؤرخین نے ان کا اور ان کے بھائی عبد الرحمن کا ذکر وفد عبد القیس میں کیا ہے۔"],[1775,"§۱۷۷۶ ۔ الحکم بن ربیع\nبن عامر بن خالد بن عامر بن زریق انصاری زرقی۔ مسعود کے والد۔ عنقریب ان کے بیٹے مسعود کا تذکرہ ان لوگوں میں آئے گا جنہیں دیدار نصیب ہے اور ان کی ولادت عہد نبوت میں ہوئی تھی۔ انبی حکم کی ایک روایت ہے جسے ابن مندہ نے میمون بن یحییٰ سے بحوالہ خضر بن بکیر، انہوں نے اپنے والد سے نقل کیا ہے، فرمایا: میں نے سلیمان بن یسار سے سنا، انہوں نے ابن الحکم زرقی جو مسعود ہیں ان سے سنا فرماتے ہیں، مجھ سے میرے والد نے بیان کیا کہ وہ منی میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ (حدیث) ابو نعیم فرماتے ہیں: اس سند سے درست روایت ابن وہب کی بحوالہ خرمہ سے جو سلیمان سے بحوالہ حکم ہے۔ فرماتے ہیں: مجھ سے میری والدہ نے بیان کیا۔ میں کہتا ہوں: نسائی نے فرمایا، مجھے معلوم نہیں کہ کسی نے خرمہ کی \"حکم\" کہنے میں متابعت کی ہو۔ درست مسعود بن حکم ہے۔ اسی طرح نسائی نے یہ روایت بطریق ابن وہب، عمرو بن حارث، بکیر بن اشج، سلیمان بن یسار، مسعود بن حکم سے انہوں نے اپنی والدہ سے نقل کی ہے۔ اور اسی روایت کو حکیم بن حکیم اور عبد اللہ بن ابی سلمہ کے طریق سے ان دونوں نے مسعود بن حکم سے انہوں نے اپنی والدہ سے نقل کیا ہے اور یوسف بن مسعود بن حکم کے طریق سے بحوالہ اپنی دادی یہی محفوظ روایت کی ہے۔"],[1776,"§۱۷۷۷ ۔ حکم بن رافع(1)\nبن سنان انصاری۔ ابو نعیم عبد الحکم بن صہیب کے طریق سے بحوالہ جعفر بن عبد اللہ بن حکم روایت کرتے ہیں، فرمایا: میں جب بچہ تھا تو مجھے حکم نے دیکھا کہ میں برتن میں ادھر ادھر سے ہاتھ مار کر کھا رہا ہوں، کہنے لگے: لڑکے! اس طرح شیطان کھاتا ہے آپ صلی اللہ علیہ وسلم جب کھانا تناول فرماتے تو اپنے سامنے کی جگہ سے ہاتھ نہ بڑھاتے تھے۔(2) اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۲)\n(2) کنز العمال (۱۸۱۷۵) جامع المسانید (۵۴/۳)"}],[1777,"§۱۷۷۸ ۔ (ز) حکم بن سعید طائفی\nامام طبرانی(1) نے ابو اسید بن یعلی طائفی کے طریق سے انہوں نے اپنے دادا سے انہوں نے حکم بن سعید سے روایت کی ہے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس بیعت کرنے آیا۔ آپ نے پوچھا: تمہارا نام؟ میں نے عرض کی: حکم۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں بلکہ تم عبد اللہ ہو\"۔ میں کہتا ہوں: انہوں نے حکم بن سعید بن عاص جن کا تذکرہ ان کے بعد آ رہا ہے ان کے سوانح میں ان کا ذکر درج کیا ہے۔ میرے نزدیک وہ ایک اور ہیں۔ اگر یہ طریق محفوظ ہے تو جیسی نامی تبدیلی ان کے متعلق واقع ہوئی ان کے ہم نام کے بارے میں بھی پیش آئی ہے، جس کی دلیل یہ ہے کہ ابو اسید بن یعلی ثقفی ہیں اور ان کے دادا بھی ثقفی اور ان کے دادا کے چچا دونوں ثقفی ہوئے۔ ثقفی، اموی کے علاوہ خاندان ہے۔ ایک ہی قصہ کئی بار واقع ہو یہ بعید امر نہیں ہے۔ خصوصاً جب حوالوں میں اختلاف ہے۔ واللہ اعلم","",{"fn":"(1) المعجم الکبیر (۱۰/۲)"}],[1778,"§۱۷۷۹ ۔ حکم بن سعید(1)\nبن عاص بن امیہ اموی، خالد اور ان کے بھائیوں کے والد، ان کی والدہ ہند بنت مغیرہ مخزومیہ ہیں۔ مسلم مدنی صحابہ میں ان کا ذکر کرتے ہیں۔ امام بخاری(2) نے تاریخ میں سعید بن عمرو بن عاص کے طریق سے روایت کی ہے، وہ فرماتے ہیں: مجھے حکم بن سعید نے بتایا: میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ نے فرمایا: تمہارا نام؟ میں نے عرض کی: حکم۔ فرمایا: \"نہیں بلکہ تم عبد اللہ ہو\"۔(3) اسے ابن ابی عاصم، ابن شاہین، طبرانی اور دار قطنی نے افراد میں سب کے سب عبید بن عبد الرحمن بصری کے طریق سے بحوالہ عمرو بن یحییٰ بن سعید بن عمرو بن عاص وہ اپنے دادا سعید سے یہی روایت کرتے ہیں۔ بعض کے ہاں حکم بن سعید بن عاص لکھا ہے۔ ترمذی نے تعلیق میں حکم بن سعید سے روایت کی ہے اور زبیر نسب قریش میں لکھتے ہیں: عبد اللہ بن سعید بن عاص ان کا نام حکم تھا۔ نبی صلی اللہ علیہ وسلم نے ان کا نام عبد اللہ رکھ دیا۔ وہ کاتب تھے، آپ نے انہیں حکم دیا کہ وہ مدینہ میں کتابت سکھائیں۔ بدر کے روز شہید ہوئے۔ میں کہتا ہوں: ابن اسحاق اور موسیٰ بن عقبہ نے بدریین میں ان کا ذکر نہیں کیا۔ خلیفہ نے کہا: وہ جنگ یمامہ میں شہید ہوئے۔ ابن اسحاق کا قول ہے: غزوہ موتہ میں شہید ہوئے۔ سعید بن عمرو کی ان سے حدیث روایت کرنے کی صراحت سے معلوم ہوتا ہے کہ ان کی وفات تاخیر سے ہوئی ہے کیونکہ وہ زیادہ قدیمی شیخ ہیں جن سے سعید بن عمرو اور سیدہ عائشہ رضی اللہ عنہا نے سماع کیا ہے۔ یہ بھی احتمال ہے کہ یہ صراحت کسی راوی کے وہم پر مبنی ہو۔ یہ معنعن (با واسطہ) روایت ہے اور یہ بھی منقطع۔ واللہ اعلم ابو الحسن بن سمیع نے شام فروش ہونے والے صحابہ میں سے پہلے طبقہ میں ان کا ذکر کیا ہے۔ سراج اپنی سند میں لکھتے ہیں: ابو سائب، ابراہیم بن یوسف بن عمر بن حمزہ بن عمر بن سعد بن ابی وقاص، خالد بن سعید بن عمرو بن سعید۔ ان سلسلہ سند میں ان کے والد سے روایت ہے کہ ان کے چچا خالد اور ان کے والد عمرو، سعید کی اولاد ہیں۔ یہ سب لوگ نبی صلی اللہ علیہ وسلم کی وفات کے بعد اپنی اپنی ذمہ داریوں سے استعفا دے کر واپس آ گئے۔ نبی صلی اللہ علیہ وسلم کے علاوہ یہ لوگ کسی اور کے لیے کوئی حکومتی کام نہیں کرتے۔ سب کے سب شام جہاد میں نکلے اور سب شہید ہو گئے۔ اسی میں ہے کہ حکم حکمت سکھاتے تھے۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۳)\n(2) التاریخ الکبیر (۲۳۱/۲)\n(3) المعجم الکبیر (۳۱۶۶/۳)"}],[1779,"§۱۷۸۰ ۔ حکم بن سفیان(1)\nبن عثمان بن عامر بن معتب بن مالک بن کعب بن سعد بن عوف بن ثقیف ثقفی۔ ابو زرعہ اور ابراہیم حربی کا قول ہے کہ صحابی ہیں۔ اصحاب السنن نے ان کی حدیث وضو(2) کے بعد چھڑکاؤ کے بارے میں روایت کی ہے۔ اس روایت میں مجاہد سے آگے اختلاف ہے۔ بقول بعض ایسے ہی ہے، ایک قول ہے کہ اس کے علاوہ ہے۔ امام بخاری رحمہ اللہ(3) اور امام احمد فرماتے ہیں کہ حکم صحابی نہیں۔ ابن المدینی، بخاری اور ابو حاتم(4) فرماتے ہیں: شیخ سند حکم بن سفیان بحوالہ اپنے والد ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۴) استیعاب (۵۲۹)\n(2) ابوداؤد کتاب الطہارۃ (۱۶۶) نسائی کتاب الطہارۃ (۱۳۴) ابن ماجہ کتاب الطہارۃ (۴۶۱)\n(3) التاریخ الکبیر (۳۲۹/۲)\n(4) الجرح والتعدیل (۱۱۶/۳)"}],[1780,"§۱۷۸۱ ۔ حکم بن صلت(1)\nبن خرمہ بن مطلب بن عبد مناف۔ بقول بعض حکیم۔ ایک قول ہے: صلت بن حکیم۔ ابن وہب، حرملہ بن عمران سے عبد العزیز بن حبان سے وہ حکم بن صلت سے مرفوع روایت کرتے ہیں: \"اپنی نمازوں اور جنازوں میں بے وقوفوں کو آگے نہ کیا کرو\"۔(2) اسے ابو موسیٰ نے بحوالہ عبد اللہ نقل کیا ہے بقول بعض وہ خیبر میں شریک ہوئے تھے، محمد بن ابی حذیفہ جب عریش گئے تو مصر میں انہیں اپنا خلیفہ بنا گئے تھے وہ قریش کے پیادوں میں سے تھے۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۶) استیعاب (۵۴۲)\n(2) کنز العمال (۲۰۳۸۹)"}],[1781,"§۱۷۸۲ ۔ حکم بن ابی عاص(1)\nبن بشر بن عبد بن دہمان ثقفی۔ سیدنا عثمان بن ابی العاص کے بھائی، ان کے بھائی حفص کا تذکرہ گزر چکا ہے۔ ابن سعد فرماتے ہیں: بقول بعض انہیں شرف صحابیت حاصل ہے۔ ان کے بھائی سیدنا عثمان بن ابی العاص نے انہیں بحرین کا والی مقرر کیا تو انہوں نے بہت سی فتوحات کیں۔ راوی کا بیان ہے کہ جب ان کے بھائی طائف کے گورنر تھے سیدنا عمر رضی اللہ عنہ نے انہیں لکھا: آؤ اور اپنے بھائی کی نیابت کرو۔ اور انہیں سیدنا عمر رضی اللہ عنہ سے روایت حاصل ہے جبکہ ان سے معاویہ بن قرۃ روایت کرتے ہیں، وہ سیدنا عمر رضی اللہ عنہ کے پاس \"شہرک\" کے قیدی لائے۔ سیدنا عمر رضی اللہ عنہ نے سیدنا عثمان بن ابی العاص سے فرمایا: ان کے رشتے کر دو، ابو صفرہ مہلب کے والد بھی موجود تھے۔ وہ کہنے لگے: میں انہی جیسا ہوں۔ تو وہ اگر چہ بوڑھے تھے ان کا رشتہ کرا دیا۔ ان کی بیوی کا ختنہ کیا گیا، اگر چہ وہ بڑھیا تھی۔ اس کے متعلق زیاد بن انعم نے اشعار کہے ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۸) استیعاب (۵۴۴)"}],[1782,"§۱۷۸۳ ۔ حکم بن ابی العاص(1)\nبن امیہ بن عبد شمس قرشی اموی، عثمان بن عفان رضی اللہ عنہ کے چچا اور مروان رضی اللہ عنہ کے والد۔ ابن سعد(2) فرماتے ہیں: فتح مکہ کے روز اسلام لائے، اور مدینہ سکونت رکھی۔ پھر نبی صلی اللہ علیہ وسلم نے انہیں طائف کی طرف جلا وطن کر دیا پھر سیدنا عثمان رضی اللہ عنہ کی خلافت میں مدینہ لوٹا دیئے گئے اور وہیں انتقال کیا۔ ابن اسکن کا قول ہے لوگوں کا کہنا ہے کہ نبی صلی اللہ علیہ وسلم نے ان کے لیے بد دعا کی تھی لیکن اس کا کوئی ثبوت نہیں۔ فاکہی بطریق حماد بن سلمہ، بحوالہ ابو سنان، زہری اور عطاء خراسانی سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم کے صحابہ آپ کے پاس آئے تو آپ حکم بن ابی العاص پر لعنت کر رہے تھے۔ صحابہ نے عرض کی: یا رسول اللہ! اس کا کیا قصور ہے؟ فرمایا: \"میں اپنی فلانی الہیہ سے مشغول تھا یہ دیوار کے شگاف سے آیا اور مجھے چونکا دیا\"۔ انہوں نے عرض کیا: کیا ہم بھی اس پر لعنت نہ کریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے یوں نظر آ رہا ہے کہ اس کی اولاد میرے منبر پر چڑھ رہی اور اتر رہی ہے\"۔ لوگوں نے عرض کی: کیا ہم انہیں پکڑ نہ لیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں\"(3)۔ اور رسول اللہ صلی اللہ علیہ وسلم نے انہیں جلا وطن کر دیا۔ طبرانی(4) نے حدیث حذیفہ سے روایت کی ہے جب ابو بکر رضی اللہ عنہ خلیفہ بنے تو حکم کے متعلق گفتگو ہوئی کہ مدینہ لوٹا لیا جائے۔ آپ نے فرمایا: \"جو گرہ رسول اللہ صلی اللہ علیہ وسلم نے لگائی ہے اسے کھولنے کا نہیں\"۔ اسی طرح حدیث عبد الرحمن بن ابی بکر سے مروی ہے، فرمایا کہ حکم نبی صلی اللہ علیہ وسلم کی مجلس میں بیٹھا کرتے تھے۔ آپ جب گفتگو کرتے تو وہ اپنے چہرے پر پھڑکڑاتے، آپ نے دیکھ لیا تو فرمایا: \"خدا ایسا ہی کرے\"۔ چنانچہ وہ مرتے دم تک ایسے ہی کرتے رہے۔ اس کی سند میں نائل ہے۔ اسی روایت کو بیہقی(5) نے دلائل میں اسی سند سے لکھا ہے۔ اس میں حرام بن صردا ضعیف کی طرف منسوب ہے۔ اسی طرح مالک بن دینار کے طریق سے بحوالہ ہند جو زوجہ رسول سیدہ خدیجہ رضی اللہ عنہا کے بیٹے ہیں روایت کی ہے کہ نبی صلی اللہ علیہ وسلم کے پاس سے گزرے تو وہ آپ کی طرف انگلی سے اشارہ کرنے لگے۔ آپ صلی اللہ علیہ وسلم نے جھٹ سے دیکھ فرمایا: \"اے اللہ! اسے لنگڑا بنا دے\"۔ تو وہ اسی جگہ گر گئے۔(6) ہشام بن عدی، صالح بن حسان سے روایت کرتے ہیں کہ اختف نے معاویہ رضی اللہ عنہ سے کہا: مروان کے لیے یہ کیسی حاجت یا پائی جاتی ہے؟ تو انہوں نے فرمایا: کہ حکم ان لوگوں میں سے تھے جو میری بہن ام حبیبہ کی رخصتی کے وقت نبی صلی اللہ علیہ وسلم کے پاس آئے تھے۔ ان کے پاس ان کے جوٹوں کی ذمہ داری تھی۔ تو رسول اللہ صلی اللہ علیہ وسلم انہیں گھورنے لگے۔ کسی نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! آپ حکم کو گھور رہے ہیں؟ فرمایا: ابن اکثر و میاس کی اولاد، جس وقت تمہیں یا چالیس سال کی ہوگی حکمران بن جائے گی۔ ہم نے ابن نجیب کے جز میں زبیر بن محمد کے طریق سے بحوالہ صالح بن ابی صالح، نافع بن جبیر بن مطعم بحوالہ ان کے والد روایت کی ہے، فرمایا: ہم لوگ نبی صلی اللہ علیہ وسلم کے ساتھ تھے، وہاں سے حکم بن ابی عاص کا گزر ہوا، تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"اس کی اولاد سے میری امت کے لیے خرابی ہے\"۔(7) ابن ابی خیثمہ(8) نے حدیث عائشہ سے روایت کی ہے کہ آپ نے مروان سے فرمایا: (یہ اس وقت کی بات ہے جب عبد الرحمن یزید بن معاویہ کی بیعت سے باز رہے تھے) جہاں تک مروان تمہارا تعلق ہے تو میں گواہی دیتی ہوں کہ رسول اللہ صلی اللہ علیہ وسلم نے جب تمہارے والد پر لعنت بھیجی تھی اس وقت تمہاری پیدائش بھی نہیں ہوئی تھی۔ میں کہتا ہوں: اس قصہ کی اصل بخاری میں اس اضافہ کے علاوہ موجود ہے۔ ابو عمر نے ان کے جلا وطن ہونے کا ایک اور سبب لکھا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کا راز افشاء کرتے تھے، بقول بعض وہ نبی صلی اللہ علیہ وسلم کی چال کی نقل اتارتے تھے۔ یہ بھی کہا جاتا ہے کہ سیدنا عثمان رضی اللہ عنہ نے جب انہیں مدینہ لوٹا لیا تو یہ عذر پیش کیا کہ انہوں نے نبی صلی اللہ علیہ وسلم سے حکم کے بارے اجازت مانگی تھی۔ فرماتے ہیں: میں نے ان کے متعلق سفارش کی تھی تو آپ صلی اللہ علیہ وسلم نے مجھ سے انہیں لوٹانے کا وعدہ فرمایا تھا۔ ابن سعد نے بحوالہ واقدی انہوں نے ثعلبہ بن ابی مالک تک اپنی سند سے نقل کیا ہے، حکم کا انتقال خلافت عثمانی میں ہوا تو سیدنا عثمان رضی اللہ عنہ نے ان کی قبر کی جگہ سخت گرمی کے دن خیمہ لگوا دیا جس پر لوگوں نے چہ میگوئیاں کیں۔ آپ نے فرمایا: عہد فاروقی میں زینب بنت جحش کی قبر پر بھی تو خیمہ لگتا تھا۔ اس قوت تمہیں کوئی معترض اور نکتہ چینی کرنے والا نظر آیا تھا؟ حکم کا انتقال خلافت عثمانی میں ۳۳ھ میں ہوا۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۷) استیعاب (۵۴۷)\n(2) الطبقات (۲۲۰/۵)\n(3) الطبقات الکبریٰ لابن سعد (۴۴۷/۵)\n(4) المعجم الکبیر (۳۱۶۶/۳)\n(5) دلائل النبوۃ (۳۲۹/۲)\n(6) التاریخ الکبیر (۳۳۱/۲)\n(7) اسد الغابۃ (۳۷/۲)\n(8) مجمع الزوائد (۲۴/۵) کنز العمال (۳۱۰۶۶) علل الحدیث (۲۷۵۱)"}],[1783,"§۱۷۸۴ ۔ حکم بن عبد اللہ ثقفی(1)\nابن مندہ نے بطریق اسرائیل، حکم بن عمرو سے بحوالہ یعلی بن مرہ، حکم بن عبد اللہ ثقفی سے نقل کیا ہے، فرماتے ہیں: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کی معیت میں کسی سفر کے لیے روانہ ہوئے۔ راستے میں ایک عورت آپ کے پاس اپنا بچہ لا کر کہنے لگی: \"یا رسول اللہ! اسے باری کا بخار ہو جاتا ہے\"۔ پھر حدیث ذکر کی۔(2) ابو نعیم فرماتے ہیں: کئی سندوں سے مروی ہے جو یعلی بن مرہ سے جس میں حکم بن عبد اللہ کا ذکر نہیں اور نہ یہ اضافہ صحیح ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۱۹)\n(2) جامع المسانید (۵۴۹/۲)"}],[1784,"§۱۷۸۵ ۔ حکم بن عمرو بن شرید(1)\nبغوی فرماتے ہیں: بخاری نے ان کا صحابہ میں ذکر کیا ہے، لیکن ان کی کسی حدیث کا ذکر نہیں کیا۔ میں کہتا ہوں: ان کی حدیث حسن بن سفیان نے بطریق عبد الحمید بن جعفر، بحوالہ اپنے والد، ابن شرید سے نقل کی ہے کہ میں نے نبی صلی اللہ علیہ وسلم کی اقتدا میں نماز پڑھی، ایک شخص چھینکا تو میں نے \"یرحمک اللہ\" کہہ دیا۔(2) حسن بن سفیان فرماتے ہیں: محمد بن لطشی فرماتے ہیں: ان ابن شرید کا نام حکم ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۲)\n(2) جامع المسانید (۵۵/۳)"}],[1785,"§۱۷۸۶ ۔ حکم بن عمرو بن مجدع(1)\nبن جذیم بن حارث بن نفعیلہ بن سلیل بن ضمرہ بن بکر بن عبد مناۃ بن کنانہ، ابو عمرو غفاری، رافع کے بھائی، انہیں حکم بن اقرع بھی کہا جاتا ہے۔ غفار کی طرف ان کی نسبت اس وجہ سے ہے کہ نفعیلہ بن سلیل، غفار کے بھائی ہیں۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں ان کی حدیث بخاری اور بقیہ چار کتب میں ہے۔ ان سے ابو الشعثاء ابو حاجب، عبد اللہ بن صامت، حسن اور ابن سیرین وغیرہ روایت کرتے ہیں۔ ابن سعد لکھتے ہیں: وہ تا مرگ نبی صلی اللہ علیہ وسلم کے ساتھ رہے۔ پھر بصرہ فروش ہو گئے۔ زیاد نے انہیں خراسان کا والی بنا دیا جہاں ان کی وفات ہوئی۔ اوس بن عبد اللہ بن بریدہ سے بحوالہ ان کے والد مروی ہے کہ معاویہ رضی اللہ عنہ کی بات پر ان سے ناراض ہوئے، وہ سرا گورنر کی چیخ کر انہیں بیڑیاں ڈال دیں اور اسی حالت میں ان کا ۴۵ھ میں انتقال ہوا۔ مدائنی فرماتے ہیں: ۵۰ھ میں اور عسکری کا قول ہے کہ ۵۱ھ میں فوت ہوئے تھے۔(2) میں کہتا ہوں: جب ان کے پاس زیاد کی طرف سے ناراضگی کا خط پہنچا تو انہوں نے اپنے لیے موت کی دعا کی اور فوت ہو گئے۔ اور ابو عمر نے زیاد کی ولایت کے قصہ کے بارے میں لکھا ہے کہ یہ ان کے ارادے سے نہ تھی بلکہ ہوا یوں تھا جب ان کی وفات ہونے لگی تو انہوں نے اپنے کام کا نگران انس بن ابی ایاس کو بنا دیا تھا۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۳) استیعاب (۵۴۳)\n(2) جامع المسانید (۵۵۱/۳)"}],[1786,"§۱۷۸۷ ۔ حکم بن عمرو بن عقبہ(1)\nبن مالک بن کعب بن عمرو بن سعد بن عوف بن ثقیف ثقفی۔ ابو عمر کا قول(2) ہے: اس وفد کے ایک فرد ہیں جو عبد یا لیل کے ساتھ ثقیف کے مسلمان ہونے کی خبر لائے تھے۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۴) استیعاب (۵۵۲)\n(2) استیعاب (۵۴۳)"}],[1787,"§۱۷۸۸ ۔ (ز) حکم بن عمرو ثعلبی\nفتوح میں ان کا ذکر ہے، انہوں نے ہی مکران کا محاصرہ کر کے اس کے بادشاہ کو شکست دی تھی اور سیدنا عمر رضی اللہ عنہ کی طرف فتح کی خوشخبری بھیجی تھی، جس کا لمبا قصہ ہے۔"],[1788,"§۱۷۸۹ ۔ حکم بن عمیر ثمالی(1)\nابن ابی حاتم بحوالہ اپنے والد فرماتے ہیں: ان کی طرف نبی صلی اللہ علیہ وسلم کی ایسی احادیث مروی ہیں جو منکر کا درجہ رکھتی ہیں، جنہیں عیسیٰ بن ابراہیم جو ضعیف راوی ہے، روایت کرتا ہے وہ موسیٰ بن ابی حبیب سے جو ضعیف راوی ہے وہ اپنے چچا حکم سے روایت کرتے ہیں۔ میں کہتا ہوں: ان میں سے ایک حدیث ابن ابی عاصم(2) نے بقیہ کے طریق سے بحوالہ عیسیٰ اسی سند سے نقل کی ہے اس میں فرماتے ہیں: حکم سے مروی ہے جو صحابی رسول ہیں۔ پھر حدیث ذکر کی۔ ابن مندہ فرماتے ہیں: بقیہ نے اسی سند سے کئی احادیث روایت کی ہیں۔ میں کہتا ہوں: ان میں سے ایک وہ حدیث ہے جو ابن ابی خیثمہ نے بحوالہ حوطی، بقیہ سے روایت کی ہے متن کے الفاظ ہیں: دو یا ان سے زیادہ افراد جماعت کا حکم رکھتے ہیں۔ بقیہ فرماتے ہیں: میں نے یہ روایت صفوان کے سامنے بیان کی تو انہوں نے فرمایا: انہوں نے سچ کہا۔ مجھے اس روایت کا راوی موسیٰ کے علاوہ مل گیا۔ ابراہیم بن دیزیل اپنی کتاب صفین میں علاء بن جریر کے طریق سے روایت کرتے ہیں کہ ہمیں طائف کے بزرگ نے بتایا جس کی عمر اسی سال تھی کہ حکم بن عمیر ثمالی سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابو بکر اس وقت تمہاری کیا حالت ہوگی جب تم حکومت کے والی بنو گے؟\"(3) پھر بقیہ حدیث ذکر کی۔ موسیٰ سے ان کی روایت میں مجھے عیسیٰ کا متابع بھی مل گیا جو روایت حکم سے مروی ہے۔ اسے ابن اسکن نے نقل کیا ہے اور ابو نعیم نے دوسری سند سے موسیٰ سے بحوالہ حکم بن عمیر روایت کی ہے کہ وہ بدری تھے۔ ابو عمر لکھتے ہیں: حکم بن عمیر نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں: \"دو یا ان سے زیادہ افراد جماعت کہلاتے ہیں\"۔(4) ان کی حدیث اہل شام سے ملی ہے پھر فرماتے ہیں حکم بن عمرو، ثمالی، شمالہ ازد کی شاخ ہے۔ وہ بدر میں شریک ہوئے۔ اہل شام نے ان کی طرف سے ایسی منکر احادیث روایت کی ہیں جو صحیح نہیں۔ یوں انہوں نے ایک کی دو شخصیتین بنا دیں۔ وہ ثمالی جن کی نسبت سے منکر احادیث مروی ہیں وہ حکم بن عمیر ہیں، شاید ان کے والد کا نام عمرو تھا لیکن مشہور عمیر ہو گیا۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۵) استیعاب (۵۴۵)\n(2) السنۃ لابن ابی عاصم (۲۱/۱)\n(3) تنزیہ الشریعۃ لابن عراق (۲۱۸) الموضوعات لابن الجوزی (۲۷/۲)\n(4) ابن ماجہ کتاب اقامۃ الصلاۃ والسنن فیہا (۹۷۲) السنن الکبریٰ (۶۹/۳) لسان المیزان (۱۱۹۳/۴)"}],[1789,"§۱۷۹۰ ۔ حکم بن کیسان(1)\nہشام بن مغیرہ مخزومی، ابو الجہل کے والد کے غلام، نبی صلی اللہ علیہ وسلم نے مدینہ سے جو پہلی مہم بھیجی اس میں گرفتار ہو گئے اس سریہ کے امیر عبد اللہ بن جحش تھے۔ چنانچہ گرفتاری کے بعد حضور صلی اللہ علیہ وسلم کی خدمت میں پیش ہوئے۔ سیرت ابن اسحاق میں یہ قصہ مشہور ہے۔ واقدی اپنی سند سے، مقداد بن عمرو سے روایت کرتے ہیں کہ میں نے ہی حکم کو قید کیا تھا۔ سیدنا عمر رضی اللہ عنہ انہیں قتل کرنا چاہتے تھے لیکن بعد میں وہ نبی صلی اللہ علیہ وسلم کے سامنے ایمان لے آئے۔ اور بئر معونہ میں شہید ہوئے۔ ایسا ہی ابن اسحاق وغیرہ کا بیان ہے۔ یحییٰ بن عدی، یونس سے بحوالہ زہری اور ابن عباس اور ابو بکر بن ابی حثم سے روایت ہے، دونوں فرماتے ہیں: حکم بن کیسان مولیٰ بنی مخزوم (جو چھنے، سینگھی لگانے کا کام کرتے تھے) نے سیدنا عثمان بن عفان کی بہن آمنہ بنت عفان (جو جاہلیت میں ماما تھیں) ان سے شادی کر لی تھی۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۶) استیعاب (۵۴۰)"}],[1790,"§۱۷۹۱ ۔ (ز) حکم بن مرہ(1)\nابن مندہ: ان کے صحابی ہونے اور ان کی روایت میں تامل ہے، حکم بن فضیل، شیبہ بن مساور بحوالہ حکم بن مرہ صحابی رسول صلی اللہ علیہ وسلم سے روایت ہے کہ آپ نے ایک شخص کو برے طریقے سے نماز پڑھتے دیکھا۔ (حدیث)(2)","",{"fn":"(1) اسد الغابۃ (۱۲۲۷)\n(2) کنز العمال (۱۹۰۶۹) جامع المسانید (۵۶۶/۳)"}],[1791,"§۱۷۹۲ ۔ (ز) حکم بن مسعود\nبن عمرو ثقفی۔ ابو عبید کے بھائی جنگ جسر میں اپنے بھائی کے ساتھ شریک ہوئے اور شہادت پائی۔ کنیتوں میں ان کے بھائی کے حالات میں ان کا ذکر آئے گا۔"],[1792,"§۱۷۹۳ ۔ حکم بن مسلم عقیلی\nبقول ابو احمد عسکری: صحابی ہیں اور سیدنا عثمان رضی اللہ عنہ سے روایت لیتے ہیں۔ ابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[1793,"§۱۷۹۴ ۔ حکم بن منہال(1)\nیا ابن مینا ابو علی بطریق حویرث روایت کرتے ہیں کہ انہوں نے حکم بن منہال سے سنا کہ نبی صلی اللہ علیہ وسلم نے سیدنا عمر رضی اللہ عنہ سے فرمایا: \"میرے لیے قریشیوں کو جمع کرو\"۔ (حدیث) اسی میں ہے: \"جھانجا قوم میں شامل ہے\"۔(2) ایسا ہی ابن الاثیر نے بطریق ابو علی نقل کیا ہے اور بطریق ابن ابی عاصم(3) مقدسی سے جو ابو علی کے شیخ ہیں ان سے روایت کیا ہے اس میں ہے حکم بن مینا نے کہا: ابو علی کی دوسری مستند سند کے نسخہ میں ایسا ہی ہے شاید وہ بعد والے ہوں۔","",{"fn":"(1) ابوداؤد کتاب الادب (۵۱۲۲) مسند احمد (۱۷۱/۳) المعجم الکبیر (۱۴۲/۲) المصنف لعبد الرزاق (۱۹۸۹۷) کنز العمال (۳۰۳۷۶) (۵۶۴۴) الدر المنثور (۳۱۸۳)\n(2) الاحاد والمثانی (۲۵۱/۵)\n(3) اسد الغابۃ (۱۲۳۰)"}],[1794,"§۱۷۹۵ ۔ حکم بن مینا انصاری(1)\nان کے مولیٰ ہیں۔ ابن سعد(2) نے ان کا ذکر کیا ہے کہ ان کی اولاد کہتی ہے: ابو عامر راہب جو حنظلہ غسیل الملائکہ کے والد تھے انہوں نے ابو سفیان بن حرب کو مینا دیا، انہوں نے آگے عباس رضی اللہ عنہ کو ہبہ کر دیا۔ آپ نے انہیں آزاد کر دیا۔ مینا نبی صلی اللہ علیہ وسلم کے ہمراہ تبوک میں شریک ہوئے۔ رہے حکم جو ان کے بیٹے ہیں، تو امام بخاری(3) تاریخ میں اور دار قطنی افراد میں بطریق شعیث بن حکم بن مینا بحوالہ اپنے والد روایت کرتے ہیں کہ میں دمشق جامع مسجد کے دروازے پر بلال سیدنا ابو بکر کے آزاد کردہ غلام اور ابو جندل کے ساتھ وضو کر رہا تھا تو اچانک ہم نے مسح علی الخفین (موزوں پر مسح) کا تذکرہ کیا۔ پھر حدیث ذکر کی۔ ابن مندہ بطریق عبد اللہ بن ابی بکر بن حزم، شعیث بن حکم بحوالہ ان کے والد روایت کرتے ہیں کہ ایک شخص اسلام لایا تو وہ زخمی ہو گیا۔ آپ صلی اللہ علیہ وسلم نے اسے دم کیا۔ ایسا ہی ان کے ہاں شعیث بغیر تصغیر لکھا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۰)\n(2) الطبقات الکبریٰ (۲۲۸/۵)\n(3) التاریخ الکبیر (۲۴۳/۲)"}],[1795,"§۱۷۹۶ ۔ حکم زرقی ابن رزیق\nتذکرہ ہو چکا ہے۔"],[1796,"§۱۷۹۷ ۔ حکم ابو شبث ابن مینا\nتذکرہ ہو چکا ہے۔"],[1797,"§۱۷۹۸ ۔ حکم انصاری(1)\nمطیع کے دادا، مسعود بن حکم زرقی کے چچاؤں میں سے ایک ہیں۔ بغوی، ابن سکن وغیرہ نے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ نے ابو عبد اللہ کنیت بتائی ہے اور بطریق محمد بن قاسم، مطیع ابو یحییٰ انصاری (جو عابد و زاہد شخص تھے) سے ان کی حدیث نقل کی ہے۔ فرمایا: \"مجھ سے میرے والد بحوالہ ضمیر سے دادا روایت کی ہے کہ نبی صلی اللہ علیہ وسلم جمعہ کے دن منبر پر کھڑے ہوئے تو ہماری طرف رخ انور فرماتے\"۔ محمد بن قاسم فرماتے ہیں: مجھے ایک محدث نے بتایا یہ مطیع بن فلان بن حکم، مسعود بن حکم کے عم زاد ہیں۔ حکم احد میں شریک رہے تھے۔","",{"fn":"(1) الجامع الکبیر (۲۷۵/۲)"}],[1798,"§۱۷۹۹ ۔ حکیم بن اشرف\nمقاتل بن سلیمان نے اس آیت \"جو لوگ تم میں سے فوت ہو جاتے ہیں اور اپنی بیویاں بیوہ چھوڑ جاتے ہیں تو ان کی ازواج کے لیے وصیت ہے\"(1) کی تفسیر میں ان کا ذکر کیا ہے۔","",{"fn":"(1) سورۃ البقرہ (۲۲۴)"}],[1799,"§۱۸۰۰ ۔ حکیم بن امیہ(1)\nبن حارث بن اقص سلمی نبی امیہ کے حلیف۔ ابن ہشام نے ان کے وہ اشعار ذکر کیے ہیں جن میں بنی امیہ کو نبی صلی اللہ علیہ وسلم سے عداوت رکھنے سے روکتے ہیں۔ حکیم بن حارث بن امیہ کی اولاد میں سے اپنے دادا کے مشابہ تھے۔ بعثت سے پہلے، قریش کے اتفاق سے ان کی تادیب و تربیت کیا کرتے تھے جس کے متعلق ایک شاعر کہتا ہے: \"میں روزانہ بلحاظ کا چکر اس خوف سے لگاتا ہوں کہ حکیم مجھے ادب سکھا دے\"۔ فاکہی نے کتاب مکہ میں بحوالہ ابو ثابت زہری اس کا ذکر کیا ہے، ابن الاثیر نے بحوالہ اشیری اپنے استدراک میں ان کا ذکر کیا اور اسے ابن ہشام اور ابن اسحاق کی طرف منسوب کیا کہ وہ بہت پہلے مکہ میں اسلام لا چکے تھے۔","",{"fn":"(1) اسد الغابۃ (۱۲۳۱)"}],[1800,"§۱۸۰۱ ۔ (ز) حکیم بن حارث طائفی\nثعلبی نے اپنی تفسیر میں بحوالہ ابن عباس رضی اللہ عنہما نقل کیا ہے کہ انہوں نے اپنی بیوی اور بچوں سمیت ہجرت کی تھی۔ انہی کے متعلق یہ آیت: \"جو لوگ تم میں سے فوت ہو جاتے ہیں اور بیویاں چھوڑ جاتے ہیں\"(1) نازل ہوئی۔ ابن فغون نے اپنے استدراک میں ان کا ذکر کیا ہے یہ قصہ ابن اسحاق سے اپنی تفسیر میں روایت کیا ہے۔ فرمایا: مجھے بحوالہ مقاتل بن حیان اس آیت کی تفسیر میں بتایا گیا کہ ایک شخص جو طائف کا رہنے والا تھا، مدینہ آیا، اس کی نرینہ اور مادہ اولاد تھی۔ اس کے ساتھ اس کے والدین اور اہلیہ بھی تھی۔ مدینہ میں اس کا انتقال ہو گیا، جس کا مقدمہ نبی صلی اللہ علیہ وسلم کے حضور پیش ہوا تو آپ صلی اللہ علیہ وسلم نے والدین اور اولاد کو دستور کے موافق حصہ تو دیا لیکن بیوی کو محروم رکھا۔ البتہ انہیں یہ حکم دیا کہ وہ سال بھر تک بیوی کو مرحوم خاوند کے ترکہ میں سے خرچ دیں۔","",{"fn":"(1) سورۃ البقرہ (۲۲۴)"}],[1801,"§۱۸۰۲ ۔ حکیم بن حزام(1)\nبن خویلد بن اسد بن عبد العزی بن قصی اسدی، زوجہ رسول سیدہ خدیجہ رضی اللہ عنہا کے بھتیجے، ان کی والدہ صفیہ ہیں۔ بقول بعض فاختہ، ایک قول ہے کہ زینب بنت زہیر بن حارث بن اسید بن عبد العزی ہیں۔ کنیت ابو خالد تھی، کتب ستہ میں ان کی حدیث ہے۔ ان سے ان کا عبد اللہ بن حارث بن نوفل، سعید بن المسیب، موسیٰ بن طلحہ اور عمرو وغیرہ روایت کرتے ہیں۔ موسیٰ بن عقبہ بحوالہ ابو حبیب مولیٰ زبیر روایت کرتے ہیں کہ میں نے حکیم بن حزام کو فرماتے سنا: میں واقعہ فیل سے تیرہ سال پہلے پیدا ہوا، اور جب عبد المطلب نے عبد اللہ کو ذبح کرنا چاہا تو اس وقت میں سمجھدار بچہ تھا۔ واقدی نے ایسا ہی نقل کیا ہے۔ اس میں یہ اضافہ ہے: نبی صلی اللہ علیہ وسلم کی ولادت سے پانچ سال پہلے، ان کے والد حرب فجار میں، جس میں نبی بھی شریک تھے، قتل ہو گئے تھے۔ زبیر بن بکار کا بیان ہے کہ حکیم بن حزام مکہ میں پیدا ہوئے، قریش کے سردار تھے اور بعثت سے پہلے ہی نبی صلی اللہ علیہ وسلم کے دوست تھے اور بعثت کے بعد بھی انہوں نے اپنی سابقہ دوستی، محبت میں کوئی کمی نہ آنے دی، لیکن (تعجب کی بات ہے) اسلام تاخیر سے قبول کیا حتیٰ کہ فتح مکہ کے موقع پر مسلمان ہوئے۔ سیرت کی کتابوں میں یہ روایت ثابت ہے اور صحیح بھی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا تھا: \"جو حکیم بن حزام کی حویلی میں داخل ہو گیا وہ مامون و محفوظ ہے\"۔(2) تالیف قلبی والوں میں سے تھے۔ حنین میں شریک ہوئے جس کی غنیمت میں سے انہیں سو اونٹ ملے۔ پھر ان کا اسلام سنور گیا۔ اور یہ بھی بدر میں کفار کے ساتھ شریک ہوئے اور فح جانے والوں میں یہ بھی سچ نکلے، جب تاکید کے لیے قسم کھاتے تو فرماتے: اس ذات کی قسم جس نے مجھے بدر سے بچایا تھا۔ زبیر فرماتے ہیں، اسلام کا ظہور ہوا تو (رفادہ) مرہم پٹی کی ذمہ داری ان کے پاس تھی۔ وہ نیکی کے کام کرتے اور صلہ رحمی کرتے تھے۔ صحیح(3) میں ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے پوچھا کہ میں جاہلیت میں جو نیکی کے کام کرتا تھا کیا مجھے ان کا اجر ملے گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نیکی کے سابقہ کاموں سمیت مسلمان ہوئے\"۔ وہ دار الندوہ ان کی ملکیت میں تھا جس میں انہوں نے بعد میں امیر معاویہ رضی اللہ عنہ کے ہاتھوں ایک لاکھ دراہم میں فروخت کر دیا۔ جس پر عبد اللہ بن زبیر نے انہیں ملامت کی تو فرمانے لگے: بھتیجے! میں نے اس کے بدلے جنت میں ایک گھر خرید لیا ہے اور تمام دراہم کو صدقہ کر دیا۔ وہ قریش کے نسب و واقعات کے عالم تھے۔ ۵۰ھ بقول بعض ۵۳ھ، ایک قول ہے ۵۸ھ، کسی کا قول ہے ۶۰ھ میں فوت ہوئے۔ ایک سو بیس سال زندہ رہنے والوں میں سے ہیں۔ آدھا عمر جاہلیت میں اور آدھا اسلام میں گزارا۔ تاریخ میں امام بخاری(4) فرماتے ہیں: ۶۰ھ میں عمر ۱۲۰ سال فوت ہوئے۔ یہ ابراہیم بن منذر کا قول ہے جسے بطریق عمر بن عبد اللہ بن عروہ، بحوالہ عروہ مسنداً ذکر کیا ہے کہ امیر معاویہ کی خلافت کے دس سال گزرنے کے بعد انتقال فرمایا۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۴) استیعاب (۵۵۲)\n(2) تہذیب تاریخ دمشق (۴۲۰/۴)\n(3) بخاری کتاب الزکاۃ من تصدق فی الشرک ثم اسلم (۱۳۶۹) مسلم کتاب الایمان بیان حکم الکافر اذا اسلم بعدہ (۱۳۱۹)\n(4) التاریخ الکبیر (۱۱/۲)"}],[1802,"§۱۸۰۳ ۔ حکیم بن حزن(1)\nبن ابی وہب بن عمرو بن عائذ بن عمران بن مخزوم، سعید بن المسیب (مشہور تابعی) کے چچا، بقول ابن اسحاق، عمرو اور ابو معشر: جنگ یمامہ میں شہید ہوئے۔ ابن اسحاق فرماتے ہیں: فتح مکہ کے روز اپنے والد اور والدہ فاطمہ بنت سائب مخزومیہ کے ساتھ مسلمان ہوئے۔ ابن مندہ کا بیان ہے: ان کی کوئی روایت مشہور نہیں۔","",{"fn":"(1) اسد الغابۃ (۱۲۲۵) استیعاب (۵۵۵)"}],[1803,"§۱۸۰۴ ۔ حکیم بن طلیق(1)\nبن سفیان بن امیہ بن عبد شمس اموی۔ ہشام بن کلبی کا قول ہے: تالیف قلبی والوں میں تھے۔ آپ صلی اللہ علیہ وسلم نے انہیں سو اونٹ عطا کیے۔ ان کی کوئی اولاد نہیں رہی۔ ابو عبید فرماتے ہیں: ان کا ایک مہاجر نامی بیٹا تھا اور ایک بیٹی تھی جس سے زیاد بن امیہ نے شادی کی تھی۔","",{"fn":"(1) اسد الغابۃ (۱۲۳۶) استیعاب (۵۵۴)"}],[1804,"§۱۸۰۵ ۔ حکیم بن عامر عبدی ثم محاربی\nابو عبیدہ نے وفد عبد القیس کے ان لوگوں میں ذکر کیا ہے جو نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تھے۔ رشاطی فرماتے ہیں: ابو عمر اور ابن فغون نے ان کا ذکر نہیں کیا۔"],[1805,"§۱۸۰۶ ۔ حکیم بن معاویہ نمیری(1)\nباوردی بحوالہ بخاری فرماتے ہیں: ان کے صحابی ہونے میں تامل ہے۔ اہل حمص سے ان کی حدیث ملتی ہے۔ ابن ابی حاتم(2) بحوالہ اپنے والد روایت کرتے ہیں کہ انہیں شرف صحابیت حاصل ہے۔ اور تاریخ میں ہے کہ ان کے صحابی ہونے میں تردد ہے۔ میں کہتا ہوں: ان کی حدیث کا مدار اسمعیل بن عیاش پر ہے جسے سلیمان بن سلیم سے بحوالہ یحییٰ بن جابر، معاویہ بن حکیم سے وہ اپنے چچا حکیم بن معاویہ سے روایت کرتے ہیں کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آ کر کہنے لگے: اللہ تعالیٰ نے آپ کو کیا دے کر بھیجا ہے؟ (حدیث) ترمذی(3) کی روایت ہے۔ بقول بعض، حکیم بن معاویہ سے بحوالہ ان کے چچا محمد بن معاویہ بھی ابن ماجہ کی روایت ہے، جسے عقبہ نے سلیمان سے بحوالہ یحییٰ، معاویہ اور حکیم سے والد کے حوالہ ان کے والد نقل کیا ہے اور ابن ابی عاصم(4) نے اپنے طریق سے روایت کی ہے، جبکہ ابن ابی خیثمہ نے بطریق سعید بن سنان، یحییٰ بن جابر سے یونہی روایت کرتے ہیں۔ یہ زیادہ بہتر ہے اس لیے کہ پہلی روایت سے یہ لازم آتا ہے کہ حکیم ان کے والد اور چچا کا نام ہو۔ ابو عمر(5) کا قول ہے: جس نے بھی صحابہ کے متعلق کوئی کتاب لکھی ہے اس نے ان میں اس شخصیت کا ذکر کیا ہے۔(6)","",{"fn":"(1) اسد الغابۃ (۱۲۳۸) استیعاب (۵۶۶)\n(2) الجرح والتعدیل (۲۰۷/۳)\n(3) ترمذی کتاب الایمان حدیث (۲۶۱۶)\n(4) ابن ماجہ کتاب الفتن (۳۹۷۳)\n(5) الآحاد والمثانی (۱۴۹/۳)\n(6) الجرح والتعدیل (۲۰۷/۳)"}],[1806,"§۱۸۰۷ ۔ حکیم والد معاویہ(1)\nابن ابی خیثمہ نے ان کا صحابہ میں ذکر کیا ہے جو میرے نزدیک غلط ہے۔ ان کے علاوہ کسی نے ان کا ذکر نہیں کیا۔ اور جو حدیث ان کے حوالہ سے ذکر کی ہے وہ: بہز بن حکیم بحوالہ ان کے والد ان کے دادا سے ہے۔ ان کے دادا معاویہ بن حیدہ ہیں۔ ایسا ہی علامہ ابن عبد البر(2) نے ذکر کیا ہے۔ پھر بطریق ابن ابی خیثمہ حوطی سے، بقیہ بحوالہ سعید بن سنان، یحییٰ بن جابر سے، بحوالہ معاویہ بن حکیم وہ اپنے والد سے روایت کی ہے کہ انہوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! (اللہ تعالیٰ) ہمارے رب نے آپ کو کیا احکام دے کر بھیجا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی عبادت کرو اور اس کے ساتھ کسی چیز کو شریک نہ ٹھہراؤ، نماز قائم کرو، زکوٰۃ ادا کرو، ہر مسلمان دوسرے مسلمان کے لیے حرمت والا ہے۔ یہی تمہارا دین ہے جہاں بھی تم رہو تمہارے لیے (اس پر عمل) کافی ہے\"۔(3) پھر بطریق عبد الوارث، بحوالہ بہز بن حکیم، ان کے والد ان کے دادا سے روایت درج کی ہے کہ میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ کے پاس آنے سے پہلے میں نے کئی بار آنے کی قسم کھائی پھر ایسی حدیث ذکر کی۔ اس میں بھی سابقہ مضمون ہے۔ ابو عمر نے اس بات پر غور کیا ہے کہ راوی کا نام بدل گیا ہے۔ وہ حکیم بن معاویہ تھے نہ معاویہ بن حکیم۔ جبکہ حکیم بن معاویہ مشہور تابعی ہیں۔ اس لیے وہ پورے ذوق سے کہہ گئے کہ یہ غلط ہے۔ لیکن یہ احتمال پھر بھی باقی ہے کہ وہ کوئی اور ہوں۔ اور اس میں کوئی بعد نہیں کہ دونوں نے ایک جیسا سوال کیا ہو۔ خصوصاً جب وہ مختلف ہے ابن ابی عاصم نے وحدان میں ان کا ذکر کیا ہے اور ان کی حدیث نقل کی ہے جو عبد الوہاب بن نجدہ وہی حوطی سے مروی ہے جو اس میں ابن ابی خیثمہ کے شیخ ہیں۔","",{"fn":"(1) الجرح والتعدیل (۲۰۷/۳)\n(2) اسد الغابۃ (۱۲۳۹) استیعاب (۵۵۷)\n(3) اسد الغابۃ (۴۷/۲)"}],[1807,"§۱۸۰۸ ۔ حکیم اشعری(1)\nمجھے ان کی اس حدیث کے علاوہ کوئی روایت معلوم نہیں جو صحیحین(2) میں حدیث ابو موسیٰ اشعری سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے اشعری رفقاء کی قرآن پڑھنے کی آوازوں کی پہچان ہے جب وہ رات ہوتے ہی اسے شروع کرتے ہیں (یعنی مساجد میں)۔ ان میں سے حکیم ہے جب وہ لشکر سے مقابلہ کرتا ہے\"۔ پھر حدیث ذکر کی۔ ابو علی غسانی نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن اثیر اور دیگر شراح بخاری کا گمان ہے کہ آپ کا یہ ارشاد \"ان میں سے ایک حکیم ہے\" ان میں سے کسی غیر معروف شخص کی صفت ہے۔ ایسا ہی عیاض نے اپنے شیخ ابو علی صدفی سے نقل کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۱۲۳۱)\n(2) ترمذی کتاب الایمان (۲۶۱۶) الدر المنثور (۵۷۸/۱)"}],[1808,"§۱۸۰۹ ۔ (ز) حلال (بے نسبت)\nجہنی، بقول بعض مزنی۔ امام احمد بطریق سفیان ثوری، ابو اسحاق سے وہ بحوالہ جہینہ یا مزینہ کے ایک شخص سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ایک شخص کو \"یا حرام یا حرام\" پکارتے سنا، جو ان کا شعار تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یا حلال یا حلال\"!"],[1809,"§۱۸۱۰ ۔ (ز) حلبس\nبروزن جعفر۔ بقول بعض تصغیر ہے۔ بے نسبت۔ ابن مندہ نے بطریق نضر بن علقمہ، اپنے بھائی محفوظ سے انہوں نے ابن عائذ سے بحوالہ حلبس نقل کیا کہ نبی صلی اللہ علیہ وسلم نے اپنی ازواج کو یہ حکم دیا تھا کہ جب کوئی سونے لگے تو تینتیس(۳۳) بار الحمد للہ، تینتیس(۳۳) بار سبحان اللہ اور تینتیس(۳۳) بار اللہ اکبر پڑھ لیا کرے۔(1)","",{"fn":"(1) کنز العمال (۱۸۲۵۷)"}],[1810,"§۱۸۱۱ ۔ حُلیس(1)\nتصغیر ہے۔ حسن بن سفیان نے اپنی مسند میں ان کا ذکر کیا ہے اور بطریق ابو الزاہر حلیس سے روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قریش کو وہ صفات حاصل ہیں جو دوسرے لوگوں کو نہیں ملیں\"۔ (حدیث)(2) اسے ابو نعیم نے سابقہ شخصیت کے سوانح میں درج کیا ہے اور فرمایا: اہل حمص میں ان کا شمار ہوتا ہے، مجھے تو لگتا ہے وہ اور ہیں۔ تاریخ دمشق میں جو ہیں ان سے ابن عائذ روایت کرتے ہیں اور وہ پہلے والے ہیں، یعنی","",{"fn":"(1) اسد الغابۃ (۱۲۴۱) استیعاب (۶۰۶)\n(2) کنز العمال (۳۲۸۰۵) جامع المسانید (۵۹۱/۳)"}],[1811,"§۱۸۱۲ ۔ حُلیس(1)\nیہ بھی تصغیر ہے۔ ابن زید بن صفوان بن صباح بن کریم بن لیث بن زید بن عامر بن ربیعہ بن کعب بن ربیعہ بن ثعلبہ بن سعد بن فہمہ۔ فتی۔ ابن شاہین نے ان کا ذکر کیا ہے اور سیف بن عمر کے طریق سے اپنی مسند سے نقل کیا ہے کہ وہ اپنے بھائی حارث بن زید بن صفوان کی وفات کے بعد نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ آپ نے ان کے چہرے پر ہاتھ پھیرا اور برکت کی دعا دی۔ انہوں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! میں مظلوم ہوں، کیا میں بدلہ لے سکتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی ظلم کیا جائے درگزر اس کی زیادہ مستحق ہے\"۔(2) (حدیث)","",{"fn":"(1) اسد الغابۃ (۱۲۴۰)\n(2) جامع المسانید (۵۹۰/۳)"}],[1812,"§۱۸۱۳ ۔ (ز) جلیلہ بن جنادہ\nبن سعید بن عمرو بن عمرو بن فطر بن نافذ بن مرہ بن تیم بن سعد بن کعب بن عمرو فزاری۔ ابن کلبی نے \"جمہرہ\" میں ان کا ذکر کیا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے بیعت کی۔ اسی طرح میں نے ایک صحیح شدہ حاشیہ میں جاعلہ ہے، یعنی، نظام اور یاد سے لکھا دیکھا ہے۔"],[1813,"§۱۸۱۴ ۔ حمّاد(1)\nان کا ذکر اس حدیث میں آتا ہے جسے ابو موسیٰ نے بطریق یقطان بن حماد بن یاسر جو ایک ضعیف راوی ہے۔ زہری سے بحوالہ ابو سلمہ، سیدنا ابو ہریرہ رضی اللہ عنہ سے نقل کیا ہے۔ فرمایا: ایک دفعہ نبی صلی اللہ علیہ وسلم اپنے صحابہ میں تشریف فرما تھے کہ ایک بوڑھا شخص لاٹھی ٹیکتے ٹیکتے آ گیا۔ اس نے نبی صلی اللہ علیہ وسلم کو سلام کیا جواباً تمام حاضرین نے سلام کہا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"حماد! بیٹھئے! آپ خیر پر کاربند ہیں\"۔ پھر انہوں نے اس کے متعلق آپ صلی اللہ علیہ وسلم سے پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی جب چالیس برس کا ہو جاتا ہے تو اللہ تعالیٰ اسے تین آفات سے محفوظ رکھتا ہے\"۔(2) یہی حدیث ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۴۲)\n(2) کنز العمال (۴۲۶۵۹) اللآلی المصنوعۃ (۷۲/۱) تاریخ بغداد (۷۱/۲)"}],[1814,"§۱۸۱۵ ۔ جمار(1)\nمشہور جانور کے نام پر یہ نام ہے جس کی وجہ کوئی حماقت نادانی نہیں کچھ اور ہے۔ امام بخاری(2) بطریق زید بن اسلم وہ اپنے والد سے وہ سیدنا عمر رضی اللہ عنہ سے روایت کرتے ہیں کہ عبد اللہ نامی ایک شخص نبی صلی اللہ علیہ وسلم کو ہنساتا اور خوش کرتا تھا۔ اس کا لقب حمار تھا۔ (حدیث) اسی میں ہے، اس کے متعلق ہے، ابو علی دوسری سند سے واقدی کا بیان ہے ان کا یہ قصہ غزوہ خیبر میں پیش آیا۔ ابو علی دوسری سند سے بحوالہ زید بن اسلم اسی سلسلہ سے نقل کرتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں گھی یا شہد کا ڈبہ ہدیے میں بھیجا کرتے تھے۔ پھر اس کا مالک لے کر آتا تو فرماتے: انہیں گھی دو۔ میں کہتا ہوں: ایسا ہی واقعہ نعمان کے ساتھ پیش آیا جو زبیر بن بکار \"کتاب الفکاہۃ والمزاح\" نے ذکر کیا ہے۔ ابو بکر مروزی اپنی مسند ابو بکر میں بطریق زید بن اسلم روایت کرتے ہیں کہ سیدنا عبد اللہ جو حمار کے نام سے مشہور تھے، انہوں نے عہد فاروقی میں شراب پی لی تھی تو سیدنا عمر رضی اللہ عنہ نے سیدنا زبیر اور عثمان کو حکم دیا کہ انہیں کوڑے لگائیں۔ (حدیث)","",{"fn":"(1) اسد الغابۃ (۱۲۴۲)\n(2) بخاری کتاب الحدود (۶۷۸۰)"}],[1815,"§۱۸۱۶ ۔ حماس(1)\nابن قیس بقول بعض ابن خالد بن قیس بن مالک دلی۔ ابن اسحاق اور واقدی کا بیان ہے کہ فتح مکہ کے موقع پر یہ کہ میں تھے۔ اسلحہ تیار کر کے اپنی بیوی سے کہنے لگے میں ان کے مقابلہ میں جاتا ہوں تمہیں ویسے بھی خادم کی ضرورت ہے باہر نکل کر مسلمانوں کا کثر و دیکھا تو واپس گھر آ گئے۔ بیوی سے کہا اری! دروازہ بند کر لے۔ وہ کہنے لگی: ناس ہوا! خادم لینے گئے تھے، کیا ہے؟ اور انہیں ملامت کرنے لگی تو اس موقع پر یہ اشعار کہے: \"اگر تم جنگ کے روز ہوتی تو دیکھتی جب صفوان اور عکرمہ بھاگ نکلے تھے، اور مسلمانوں نے تلواریں لیے ہمیں آ لیا۔ ایسی تلواریں جو مدد مقابل کے ہر کندھے اور کھوپڑی کو کاٹ کے رکھ دیتیں۔ وہ ان سے ایسا وار کرتے جس سے صرف شور سنائی دیتا۔ تو ملامت کا لفظ بھی منہ سے نہ نکالتی\"۔ ابو عمر(2) نے یہی قصہ صفوان بن امیر کے حالات میں ذکر کیا ہے لیکن انہوں نے ان کا نام خناس بن قیس لیا۔ بہر کیف پہلا نام زیادہ صحیح ہے اور موسیٰ بن عقبہ نے بھی مغازی میں یہ قصہ نقل کیا ہے۔ وہ لکھتے ہیں: جب بنو بکر کو شکست ہوئی تو قبیلہ بنو ذیل کا ایک شخص اپنی بیوی کے پاس آیا پھر وہ قصہ ذکر کیا جس کے آخر میں ہے، ابن شہاب نے کہا: یہ اشعار حماس، بنی سعد بن لیث کے (بھائی) رشتہ دار نے کہے ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۲۴۴) استیعاب (۶۰۴)\n(2) استیعاب (۶۵۹/۱)"}],[1816,"§۱۸۱۷ ۔ حماس (بے نسبت)\nابن قانع بطریق حارث بن سلمہ، ابو جعفر خطمی، حمید بن حماس، بحوالہ اپنے والد روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے ہاں تشریف لائے، ہم لوگ سو چکے تھے، آپ نے فرمایا: \"بنی حماس! نیکی کا حکم کرتے رہنا اور برائی سے روکتے رہنا\"۔(1)","",{"fn":"(1) السنن الکبریٰ (۹۳/۱۰) حلیۃ الاولیاء (۲۸۷/۸)"}],[1817,"§۱۸۱۸ ۔ (ز) حمّال بن مالک\nبن جحال الاسدی فتوح میں سیف نے لکھا ہے کہ سیدنا سعد نے جب عراق کا رخ کیا تو انہیں پیادہ فوج کا امیر مقرر کیا۔"],[1818,"§۱۸۱۹ ۔ حمام بن عمر اسلمی(1)\nطبرانی(2) بطریق یزید بن نعیم روایت کرتے ہیں کہ قبیلہ اسلم کا ایک شخص عبید بن عمیر نامی کا بیان ہے کہ زمانہ جاہلیت میں میرے چچا نے ایک باندی سے مقاربت کر لی جس سے اس کے پاؤں بھاری ہو گئے اور اس کے حمام نامی لڑکا ہوا۔ وہ نبی صلی اللہ علیہ وسلم کے پاس اپنے بیٹے کی بات کرنے آئے، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اپنا بیٹا لے جاؤ!\" تھوڑی دیر میں باندی کا آقا بھی آ گیا۔ آپ نے اس کے سامنے دو غلام پیش کیے اور فرمایا: \"ان میں سے جو تم بھائے لے لو اور اس شخص کا بیٹا چھوڑ دو!\" تو اس شخص نے رافع نامی غلام لے لیا اور اس کا بیٹا چھوڑ دیا۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے بھی اپنا بیٹا پہچان لیا اور اسے اپنے قبضہ میں (کسی بھی طریقہ سے) لے لیا تو اس کی آزادی آزاد کی غلام آزاد کرتا ہے\"۔ اس کی سند حسن ہے۔ اسے باوردی قتی بن مخلد اور طبرانی نے تہذیب الآثار میں اسی سند سے ان الفاظ میں نقل کیا ہے: قبیلہ اسلم کا ایک شخص عمر نامی قبیلہ اسلم ہی کے ایک شخص عبید کے ساتھ ہو لیا۔ پھر اس عمر نے ایک رشڈی باندی سے مقاربت کر لی جس سے حمام نامی ایک لڑکا ہوا۔ یہ سب جاہلیت کی بات ہے، پھر وہ عمر نبی صلی اللہ علیہ وسلم کے پاس آئے اس کے بعد وہ حدیث ذکر کی۔","",{"fn":"(1) اسد الغابۃ (۱۲۴۵)\n(2) المعجم الکبیر (۳۵۹۹/۴)"}],[1819,"§۱۸۲۰ ۔ (ز) حمام اسلمی\nدوسرے ہیں مہمات میں ابن حاصرہ کے ذیل میں ان کا تذکرہ آئے گا۔"],[1820,"§۱۸۲۱ ۔ حُمام بن الجُموح(1)\nبن زید انصاری۔ ابن کلبی کا بیان ہے کہ غزوہ احد میں شہید ہوئے۔ ابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۴۶)"}],[1821,"§۱۸۲۲ ۔ حمران بن جابر یمامی(1)\nابو سالم ابن مندہ بطریق محمد بن جابر، عبد اللہ بن بدر، وہ اپنی دادی ام سالم سے وہ ابو سالم حمران بن جابر سے جو وفد کے ایک فرد تھے روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"بنی امیہ کے لئے ہلاکت ہے\"۔(2) تین بار یہ کلمات فرمائے (مراد جو اسلام نہیں لائے۔)","",{"fn":"(1) اسد الغابۃ (۱۲۴۸) استیعاب (۵۸۵)\n(2) کنز العمال (۳۱۰۵۹)"}],[1822,"§۱۸۲۳ ۔ حمران بن حارثہ اسلمی(1)\nاسماء کے بھائی۔ بعض اہل علم سے روایت ہے کہ یہ لوگ آٹھ بھائی تھے۔ سب اسلام لائے اور صحابہ میں شامل ہو گئے۔ ان کے نام یہ ہیں:(۱) اسماء(۲) حمران(۳) خراش(۴) ذویب(۵) سلمہ(۶) فضالہ(۷) مالک(۸) ہند۔ ان میں سے حمران کے متعلق ذکر کیا جاتا ہے کہ وہ بیعت رضوان میں بھی شریک تھے۔ ابن الاثمین نے اپنے استدراک میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: طبرانی نے یہ روایت بھی کی ہے کہ آٹھوں کے آٹھ بیعت رضوان میں شریک تھے جس کا کچھ تذکرہ مالک بن حارثہ کے حالات میں آئے گا۔ ابو موسیٰ نے ان کا ذکر کر کے کہا: فزواری ہیں، اسلمی نہیں کہا۔ جو واضح غلطی ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۴۹)"}],[1823,"§۱۸۲۴ ۔ حُمُرہ\nمالک(1) بن ذی شعار بن مالک بن مجمع بن سنکر بن مالک بن عدی بن سعد بن رافع بن مالک بن ہشم بن حاشد بن ہشم بن حیوان بن نوف بن ہمدان ہمدانی۔ ابن سعد(2) بحوالہ اپنے رجال مدنی سے نقل کرتے ہیں کہ ہمدان کا وفد نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، ان میں حرمہ بن مالک بن ذی شعار بھی تھے۔ نبی صلی اللہ علیہ وسلم نے فرمایا: \"ہمدان اچھا قبیلہ ہے\"۔ (حدیث) بعض روایات میں حمرہ بن مالک لکھا ہے، شاہد کی نے تغییر بنا دی ہو۔ ابن کلبی کا قول ہے: یہ کل تین سو عرب یا تین سو عرب کے گھرانے تھے جنہوں نے آپ سے دوستی کا اقرار کیا۔","",{"fn":"(1) اسد الغابۃ (۱۲۵۶) اس میں حمزہ کی جگہ حمرہ ہے۔\n(2) الطبقات الکبریٰ (۷۴/۲)"}],[1824,"§۱۸۲۵ ۔ حمزہ بن ابی اسید\nاسمٰعیلی نے صحابہ میں ان کا ذکر کیا ہے اور ان کے والد کا نام قلمبند کیا ہے۔ یہ بات خطیب نے \"موتلف\" میں رشیدی کے حالات میں لکھی ہے اور علی بن معبد، محمد بن سلمہ، محمد بن اسحاق، زہری، محمد بن خالد انصاری ان کے سلسلہ سند میں حمزہ بن ابی اسید کے حوالہ سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم جنازہ کے لیے باہر تشریف لائے، تو راستے میں ایک بھیڑ یا بازو پھیلائے بیٹھا تھا۔ پھر حدیث ذکر کی۔ خطیب فرماتے ہیں: یہی لگتا ہے کہ وہ حمزہ بن ابی اسید انصاری ہوں۔ ان کے والد کا نام حمزہ کے پیش سے ہے۔ میں کہتا ہوں: قسم ثانی میں تذکرہ ہوا ہے۔"],[1825,"§۱۸۲۶ ۔ حمزہ بن حُمیر(1)\nبنی عبید بن عدی انصاری کے حلیف، واقدی نے ان کا یہی نام لیا ہے۔ البتہ ابن اسحاق فرماتے ہیں: خارجہ بن حمیر۔ یہ بھی احتمال ہے کہ دونوں بھائی ہوں۔ حمیر اسی طرح قلمبند کیا گیا ہے، بقول بعض: تبعیر حمیر سے تقصیر با لاتشدید ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۵۰) استیعاب (۵۶۱)"}],[1826,"§۱۸۲۷ ۔ حمزہ بن عامر\nبن مالک بن خنساء بن مبدول انصاری بقول ابن سعد: احد میں وہ اور ان کے بھائی سعد شریک ہوئے۔ بیان کیا جاتا ہے کہ ان کے والد کا نام تمار تھا۔ کبھی دال کی طرف نسبت کر کے حمزہ بن مالک بھی کہا جاتا ہے۔"],[1827,"§۱۸۲۸ ۔ حمزہ بن عبد المطلب(1)\nنام و نسب: بن ہاشم بن عبد مناف قرشی ہاشمی۔ ابو عمارہ، نبی صلی اللہ علیہ وسلم کے چچا اور آپ صلی اللہ علیہ وسلم کے رضاعی بھائی، دونوں کو ثویبہ باندی ابو لہب نے دودھ پلایا تھا جس کا ثبوت صحیحین میں ہے۔ والدہ کی طرف سے آپ کے قریبی رشتہ دار بھی بنتے ہیں، وہ اس طرح کہ سیدنا حمزہ رضی اللہ عنہ کی والدہ ہالہ بنت اہیب بن عبد مناف بن زہرہ، حضرت آمنہ بنت وہب بن عبد مناف (والدہ محترم نبی صلی اللہ علیہ وسلم) کی چچا زاد بہن لگتی ہیں۔ ولادت: آپ صلی اللہ علیہ وسلم سے دو سال، بقول بعض چار سال پہلے پیدا ہوئے۔ اسلام: آپ بعثت کے دوسرے سال مشرف با اسلام ہوئے اور آپ صلی اللہ علیہ وسلم کے ساتھ یوں جڑ گئے کہ بس آپ کے حامی و ناصر بن گئے۔ آپ کے ساتھ ہی ہجرت فرمائی۔ ابن اسحاق(2) نے ان کے اسلام لانے کا طویل قصہ ذکر کیا ہے۔ مواخاۃ: کا رشتہ سیدنا زید بن حارثہ سے قائم ہوا۔ غزوات میں شرکت: بدر میں شریک ہوئے اور خوب جوہر دکھائے۔ شیبہ بن ربیعہ کو ایک ہی وار میں دو نصف کر دیا پھر عتبہ بن ربیعہ کے قتل میں شریک ہوئے یا اس کے برعکس صورتحال پیش آئی۔ طعیمہ بن عدی آپ کے ہاتھوں ہی موت کے گھاٹ اترا۔ اسلام میں پہلا پرچم: بقول مدائنی رسول اللہ صلی اللہ علیہ وسلم نے انہیں جھنڈا باندھ کر دیا اور انہیں ایک مہم پر روانہ فرمایا۔ یہ اسلام کا پہلا جھنڈا تھا۔ شہادت: احد میں شہادت سے سرفراز ہوئے۔ امام بخاری(3) نے حدیث وحشی سے ان کے قتل کیے جانے کا واقعہ بیان کیا ہے، جو ہجرت کے تیسرے سال نصف شوال میں پیش آیا۔ عمر: آپ نے ساٹھ سے کم سال کی عمر پائی ہے۔ نبوی لقب: \"اسد اللہ\" تھا۔ آپ صلی اللہ علیہ وسلم نے انہیں سید الشہداء کا نام عطا کیا۔ ایک قول کے مطابق شہادت سے پہلے انہوں نے تیس(۳۰) سے زائد سواروں کو تیغ کیا تھا۔ جنازے میں اعزاز: بخاری کی روایت ہے کہ نبی صلی اللہ علیہ وسلم شہداء احد کو ایک قبر میں دو دو میتوں کو دفن کرتے تھے۔ (حدیث) سیدنا حمزہ کی میت دھری رہتی اور دوسرے حضرات کے جنازے لائے جاتے تو جتنی بار دوسروں کی نماز جنازہ پڑھی جاتی سیدنا حمزہ کی بھی ساتھ نماز جنازہ پڑھی جاتی تھی۔ سیدنا حمزہ رضی اللہ عنہ اور عبد اللہ بن جحش رضی اللہ عنہ دونوں ایک قبر میں دفن کیے گئے۔ فعیلانیات میں ہم نے حدیث ابو ہریرہ روایت کی ہے کہ شہادت کے بعد رسول اللہ صلی اللہ علیہ وسلم سیدنا حمزہ رضی اللہ عنہ کو غور سے دیکھنے لگے، چونکہ آپ کا مثلہ کیا گیا تھا جس سے آپ صلی اللہ علیہ وسلم کو شدید صدمہ پہنچا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"چچا جان! اللہ کی رحمت ہو آپ پر آپ بڑے صلہ رحم اور کار خیر میں بڑے تیز رفتار تھے\"۔ نیز فعیلانیات میں عمر بن شبکی روایت سے سری بن عیاض بن معقد، معقد بن سلمٰی بن مالک سے وہ اپنے نانا ابو مرشد سے وہ حلیف سے وہ سیدنا حمزہ بن عبد المطلب سے آپ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں، آپ نے فرمایا: یہ دعا نہ چھوڑنا: اَللّٰهُمَّ انی اسئلک باسمک الاعظم و رضوانک الاکبر۔(4) (حدیث) \"اے اللہ! میں آپ سے آپ کے سب سے بڑے نام کے ذریعہ اور آپ کی عظیم رضا کے واسطے سے سوال کرتا ہوں\"۔ کعب بن مالک نے مندرجہ ذیل اشعار میں آپ کا مرثیہ کہا ہے: \"میری آنکھ روئے اور اسے رونے کا حق ہے۔ لیکن اس صحیح اللہ کے شیر پر رونے اور واویلا کرنے سے کیا حاصل جب لوگوں نے یہ کہا کہ حمزہ شہید ہو گئے\"۔ فوائد ابی طاہر میں بطریق حمزہ بن زید، ابو زبیر سے بحوالہ جابر مروی ہے، فرمایا: \"ہم اس دن اپنے احد میں شہید ہونے والے لوگوں پر روئے جس دن معاویہ نے نہر کھدوائی تھی، ہم نے دیکھا ان کی لاشیں تروتازہ ہیں، ایک شخص کی پھاڑی سیدنا حمزہ رضی اللہ عنہ کے پاؤں پر لگ گئی جس سے خون کا فوارہ پھوٹ پڑا\"۔","",{"fn":"(1) اسد الغابۃ (۱۲۵۱) استیعاب (۵۵۹)\n(2) السیرۃ النبویۃ (۱/۲۳۲، ۲۳۴)\n(3) بخاری باب الصلوۃ علی الشہید حدیث (۱۳۴۲)\n(4) المعجم الکبیر (۱۶۶/۳) کنز العمال (۳۲۱۷)"}],[1828,"§۱۸۲۹ ۔ حمزہ بن عُمَر(1)(3)\nباوردی ان کا ذکر کر کے کہتے ہیں: ان کا صحابی ہونا صحیح نہیں۔ فرماتے ہیں: مطین، مجاب، شریک، ہشام بن عمرو وہ ان کے سلسلہ سند میں ان کے والد سے وہ حمزہ بن عمر سے روایت کرتے ہیں، فرمایا: میں نے نبی صلی اللہ علیہ وسلم کے ساتھ کھانا کھایا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"دائیں ہاتھ سے اور بسم اللہ پڑھ کر\"۔(2) مجاب فرماتے ہیں: اس میں شریک کو وہم ہوا ہے، درست وہ روایت ہے جو ہمیں علی بن مہر نے بحوالہ ہشام ابن انہوں نے اپنے والد کے حوالہ سے نقل کی ہے کہ عمر بن ابی سلمہ سے یہ روایت مروی ہے۔ میں کہتا ہوں: عمرو بن ابی سلمہ والا طریق، ترمذی، نسائی اور ابن ماجہ میں درج ہے جو ہشام سے مروی طرق سے منقول ہے۔ ترمذی فرماتے ہیں: اس میں ہشام سے آگے اختلاف ہے۔ ابو نعیم نے یہی عنوان قائم کیا ہے جسے ابو اسحاق طبرانی مطین سے پورے کا پورا نقل کیا ہے اور ابو موسیٰ نے انہی کے طریق سے درج کیا ہے، فرماتے ہیں: اگر چہ اس میں وہم واقع ہوا ہے پھر بھی ابو نعیم کو اس میں وہم ہوا ہے۔ وہ اس طرح کہ طبرانی نے یہ نام حمزہ بن عمرو اسلمی کے حالات میں لکھا ہے علیحدہ عنوان نہیں قائم کیا۔ تو ابو نعیم کو یوں وہم ہوا کہ انہوں نے عمرو سے واؤ کم کر کے علیحدہ عنوان دے دیا۔ اسی طرح انہیں دو خطاؤں میں الجھنا پڑا۔ میں پھر کہتا ہوں: اصل میں غلطی ابو نعیم سے نہیں بلکہ طبرانی سے ہوئی کیونکہ انہوں نے اس نام کو حمزہ بن عمرو کے حالات کے آخر میں درج کیا، جسے ان سے مطین نے بیان کیا ہے جس کا صحیح گواہ باوردی کی موافقت ہے جیسا کہ پہلے بتا چکا ہوں۔ انہوں نے کہا: حمزہ بن عمر انہوں نے خود واؤ استعمال نہیں کیا۔ اگر چہ مجاب نے اس بات کو وثوق سے لکھا ہے کہ اس میں وہم شریک سے ہوا ہے لیکن اس کا احتمال ہے۔ اس میں کیا رکاوٹ ہے کہ سارا اختلاف ہشام سے آگے ہو، اگر ایسی بات نہ ہوتی تو میں تم آخر میں ان کا ذکر کرتا۔ یہ ان ناموں میں سے ہے جن کے بارے میں اللہ تعالیٰ نے احتیاط سے استخارہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۵۳)\n(2) ترمذی کتاب الاطعمۃ (۱۸۵۷) ابن ماجہ کتاب الاطعمۃ (۳۲۶۴)\n(3) المعجم الکبیر (۱۷۸/۳)"}],[1829,"§۱۸۳۰ ۔ حمزہ بن عمّار\nبن مالک، حمزہ بن عامر میں تذکرہ ہو چکا ہے یہاں ابن دباغ نے ذکر کیا ہے۔"],[1830,"§۱۸۳۱ ۔ حَمفط بن شریق(1)\nبن غانم بن عامر بن عبد اللہ بن عبید بن عوفج بن عدی بن کعب قرشی تمیم عدوی۔ زیر کتاب نسب میں لکھتے ہیں: فتوحات میں شریک رہے اور طاعون عمواس میں فوت ہوئے۔ ابن عساکر نے ان کا ذکر کیا اور ابن الاثیر نے اپنے استدراک میں ان کا تذکرہ کیا ہے۔(2)","",{"fn":"(1) اسد الغابۃ (۱۲۵۸)\n(2) اسد الغابۃ (۵۵/۲)"}],[1831,"§۱۸۳۲ ۔ حَمل(1)\nابن سعدانہ بن حارث بن مقبل بن کعب بن علیم کنی، دومۃ الجندل والے، حارث بن قطن میں پہلے ان کا تذکرہ گزر چکا ہے۔ ابن سعد لکھتے ہیں: ہشام بن محمد، ابن ابی صالح جو بنی کنانہ کے ایک شخص ہیں، ان کے سلسلہ سند میں دسعید بن ابراہیم سے روایت ہے، فرمایا: حارث بن قطن اور حمل بن سعدان نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ہم سب لوگ اسلام لے آئے۔ آپ نے حمل بن سعدانہ کے لیے ایک پرچم بنایا۔ اسی پرچم کے ساتھ جنگ صفین میں سیدنا معاویہ کا ساتھ دیا۔ رشاطی فرماتے ہیں: حمل بن سعدانہ سیدنا خالد بن ولید کی جنگوں میں شریک رہے۔ ابو محمد اسود عذری فرماتے ہیں: شاعر کے اس شعر میں وہی مراد ہیں: \"ذو راھمر! ابھی حمل جنگ میں شریک ہونے والا ہے\"۔ میں کہتا ہوں: انہی اشعار کو سیدنا سعد بن معاذ نے بھی پڑھا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۵۹) استیعاب (۵۶۳)"}],[1832,"§۱۸۳۳ ۔ حمل بن مالک(1)\nبن نابغہ بن جابر بن ربیعہ بن کعب بن حارث بن کبیر بن ہند بن طارق بن لحیان بن ہذیل بن مدرک ہذلی ابو نضلہ۔ نصرہ فروش ہوئے، وہیں ان کا دائرہ تھا۔ جثین کے واقعہ میں صحیح کی حدیث ابو ہریرہ رضی اللہ عنہ میں ان کا ذکر آتا ہے۔ اس حدیث کو ابو داؤد اور نسائی نے صحیح سند کے ذریعہ ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے پیٹ کے بچے کی دیت کے متعلق لوگوں سے نبی صلی اللہ علیہ وسلم کی حدیث کا مطالبہ کیا۔ جس پر حمل بن مالک کھڑے ہو کر فرمانے لگے۔۔۔۔ پھر وہ حدیث ذکر کی(2) جس سے پتہ چلتا ہے کہ وہ خلافت فاروقی تک زندہ رہے۔ اور جوبات عامر بن قرش کے حالات میں آ رہی ہے کہ وہ عبدنوی میں شہید ہو گئے تھے۔ بے حد کمزور ہے۔ عمران بن عونیم کے سوانح میں خود حمل بن مالک کی حدیث سے جثین کا قصہ آ رہا ہے۔ اسی میں ہے کہ آپ صلی اللہ علیہ وسلم نے انہیں ہذیل کی زکوٰۃ کی وصولی پر مقرر فرما دیا تھا۔","",{"fn":"(1) اسد الغابۃ (۱۲۶۰) استیعاب (۵۶۲)\n(2) ابوداؤد کتاب الدیات باب دیۃ الجنین (۴۵۷۲) نسائی کتاب القسامۃ باب قتل المرأۃ بالمرأۃ (۴۷۵۳)"}],[1833,"§۱۸۳۴ ۔ حُمفہ دوسی(1)\nابوداؤد طیالسی(2)، مسدد اور حارث نے اپنی اپنی مسند میں، ابن ابی شیبہ نے اپنے \"مصنف\" میں اور ابن المبارک نے کتاب الجہاد میں بطریق حمید بن عبد الرحمن حمیری روایت کی ہے کہ ایک صحابی جن کا نام حمر تھا، انہوں نے دور فاروقی میں اصبہان کے جہاد میں شرکت کی۔ انہوں نے یہ دعا کی: اے اللہ! محمد کا گمان ہے کہ وہ تیری ملاقات پسند کرتا ہے۔ اللہ! اگر وہ سچا ہے تو اس کی سچائی کو ثابت کر دے اور اگر جھوٹا ہے تو اسی پڑ ڈال دے اگر چہ وہ نہ چاہے۔۔۔۔ (حدیث) اس میں ہے کہ وہ شہید ہو گئے تو ابو موسیٰ نے فرمایا: \"وہ شہید ہیں۔ امام احمد نے کتاب الزہد میں ہرم بن حیان کے طریق سے روایت کی ہے کہ انہوں نے صحابی رسول محمد کے قریب رات بسر کی تو دیکھا وہ پوری پوری رات روتے رہتے تھے اور کبھی کھجوروں دل بیٹھتے تھے\"۔(3)","",{"fn":"(1) اسد الغابۃ (۱۲۶۱) استیعاب (۵۹۶)\n(2) ابوداؤد طیالسی فی مسندہ (۵۰۵)\n(3) اسد الغابۃ (۵۶/۲)"}],[1834,"§۱۸۳۵ ۔ حمنن بن عوف(1)\nبن عبد عوف بن عبد بن حارث بن زہرہ بن کلاب، عبد الرحمن بن عوف کے بھائی۔ زبیر نے نسب قریش میں ان کا ذکر کیا ہے کہ وہ مسلمان ہونے کے بعد یا آٹھ سال زندہ رہے اور تو ان کی وفات تک ہی قیام رکھا۔ نہ ہجرت کی اور نہ بند میں داخل ہوئے۔ خثعم، میں نے ایسا ہی لکھا دیکھا ہے۔ (ابن) الا امین وغیرہ نے یوہی قلم بند کیا ہے۔ اور نسب الدبیر میں بھی ایسا ہی ہے۔ فرماتے ہیں، حمنن کی وفات پر ایک شاعر کہتا ہے: \"تعجب ہوگا کہ اگر بنی عوف کی عورتیں آ نہوند بہا ئیں جب حمنن وفات پا چکا ہے\"۔ وزیر ابراہیم مغربی نے اپنی کتاب \"منثور\" میں اسی طرح لکھا ہے، البتہ انہوں نے کی جگہ آ خز میں ذا لکھ دی، اور کہا کہ حمنن سے مشتق ہے جس کے معنی صعوبت دینی کے آتے ہیں۔ اور اس میں نون زائدہ ہے۔ ان کے متعلق کہا جاتا ہے کہ وہ اپنے قبیلہ میں سب سے صلح جو آدمی تھے۔","",{"fn":"(1) اسد الغابۃ (۱۲۶۲) استیعاب (۵۸۲)"}],[1835,"§۱۸۳۶ ۔ حُمید بن ثُور(1)\nبن حزن بن عمرو بن عامر بن ابی ربیعہ بن نہیک بن بلال بن عامر بن صحصہ بلالی ابو ایشی۔ بعض نے کچھ اور کنیت بتائی ہے۔ ابن شاہین اور غریبین میں خطابی، عقیلی، ازدی ضعفاء میں اور طبرانی کے سب کے سب بطریق یعلی بن اشدق (جو ضعیف راوی ہے)۔ روایت کرتے ہیں کہ حمید بن ثور نے ان سے فرمایا کہ جب وہ مسلمان ہو کر نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے، تو یہ اشعار کہے: \"میرا دل تسلی سے دور ہو گیا خواہش سے خواہ مخواہ\"۔ دوسرے اشعار میں فرماتے ہیں: \"بالآخر میں محمد مصطفیٰ صلی اللہ علیہ وسلم کے پاس پہنچ گیا جو اللہ تعالیٰ کی ہدایت کی دینے والی کتاب کی آیات تلاوت فرماتے ہیں\"۔ ابن شاہین نے سارے اشعار بیان کیے ہیں۔ یعلی ضعیف اور متروک راوی ہے۔ محمد بن سلمہ نمی نے اسلامی شعراء کے پہلے طبقہ میں ان کا ذکر کیا ہے۔ ابن ابی خیثمہ نے نبی صلی اللہ علیہ وسلم سے روایت کرنے والے شعراء میں ان کا تذکرہ کیا ہے۔ ابراہیم بن منذر فرماتے ہیں: ہمیں محمد بن ابی الفضل نحوی نے بتایا کہ سیدنا عمرو رضی اللہ عنہ نے تمام شعراء کی جانب یہ حکم بھیجا کہ کوئی بھی کسی عورت کے محاسن والے اشعار نہیں کہے گا، تو حمید بن ثور جن کی ایک محبوبہ تھی اس کے متعلق یہ اشعار کہہ دیے: \"اللہ کی قسم! مالک کے طویل درخت تمام درختوں کی شاخوں سے خوبصورت ہیں اگر چہ میں اپنے دل کو مرو سے بہلا تا رہوں حالانکہ مجھے اس سرو تک جانے کا راستہ معلوم تھا\"۔ قاسم نے اسی سند سے دلائل میں ذکر کیا ہے، مزہ بانی کا بیان ہے کہ وہ ایک فصیح شاعر تھے، ہجو میں جوان سے مقابلہ کرتا یہ اس سے بازی لے جاتے۔ نبی صلی اللہ علیہ وسلم کی خدمت میں بھی آئے، خلافت عثمانی تک زندہ رہے۔ زبیر بن بکار کا قول ہے کہ مجھے میرے والد نے بتایا کہ حمید بن ثور کی اسموئی خلیفہ کے ہاں گئے، اس نے پوچھا کیسے آتا ہوا؟ انہوں نے جواباً یہ اشعار کہے: \"مجھے تمہارے پاس وہی اللہ لایا ہے جو تم سے بڑھ کر بھلائی پہنچانے والا ہے۔ تم تک میرا ورد ہی رہنما ہے\"۔ زبیر نے ان کے یہ اشعار(2) پڑھے ہیں: \"اللہ تعالیٰ جوانی اور ہماری بات کو ختم نہ کرے کہ جب ہم بچو کا حرکات کریں گے تو توبہ کر لیں گے\"۔","",{"fn":"(1) اسد الغابۃ (۱۲۶۵)\n(2) دیوانہ (۵۲)"}],[1836,"§۱۸۳۷ ۔ (ز) حمید بن جمیل\nعبد اللہ بن جمیل میں ان کا تذکرہ آئے گا۔ عبد العزیز بن بزدہ نے ان کا یہ نام بتایا ہے۔"],[1837,"§۱۸۳۸ ۔ (ز) حمید بن خالد\nتہذیب الآثار میں طبرانی بطریق عبد اللہ بن ربیعہ، حمید بن خالد سے روایت کرتے ہیں، فرمایا: وہ صحابی رسول ہیں۔ پھر حدیث ذکر کی۔"],[1838,"§۱۸۳۹ ۔ (ز) حمید بن زہیر\nبن حارث بن اسد بن عبد العزی بن قصی قرشی اسدی۔ فاکہی کی کتاب میں مجھے یہ حوالہ ملا ہے کہ کعبہ کی چھٹی طرف بنی اسد کا ایک گھر تھا جو مسجد کے ساتھ ملا ہوا تھا۔ حمیدی فرماتے ہیں: میرے دادا حمید بن زہیر نے اپنا گھر صدقہ کر دیا اور اپنی تحریر میں لکھا ہے: میں نے اپنی وہ حویلی جس کا سایہ کعبہ پر اور کعبہ کا سایہ اس پر پڑتا تھا صدقہ کر دی۔ میں کہتا ہوں: زبیر نے نسب قریش میں یہ قصہ عبد اللہ بن حمید کے حوالے سے، جو انھی کی اولاد میں سے ہیں، نقل کیا ہے۔ دونوں میں کوئی منافات نہیں کیونکہ میں ممکن ہے کہ ہر ایک نے وقف کیا ہو۔"],[1839,"§۱۸۴۰ ۔ حمید بن عبد الرحمن(1)\nبن عوف بن خالد بن عفیف بن نجد بن رکاش بن کلاب بن ربیعہ بن عامر بن صحصہ عامری ثم رؤاسی، وہ اور ان کے بھائی جنید اور عمرو بن مالک بن عامر نبی صلی اللہ علیہ وسلم کے پاس آئے۔ حرف جیم جدید میں تذکرہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۶۶) تجرید (۱۴۰/۱)"}],[1840,"§۱۸۴۱ ۔ حمید بن عبد یغوث بکری(1)\nابن مندہ نے بطریق عبد الرحمن بن عمرو بن جبلہ، زیاد بن عبد اللہ سے بحوالہ موسیٰ بن عمرو، حمید بن عبد یغوث سے روایت کی ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: \"ابو کبیر میں اور میں اس کا (اسلامی) بھائی ہوں\"۔(2) میں کہتا ہوں: عبد الرحمن انتہائی ضعیف راوی ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۶۷) استیعاب (۵۶۵)\n(2) کنز العمال (۳۲۵۰۰)"}],[1841,"§۱۸۴۲ ۔ حمید بن منہب(1)\nبن حارثہ الطائی۔ ابو عمر(2) فرماتے ہیں: ان کی طرف صحابی ہونے کی نسبت کرنا صحیح نہیں۔ البتہ سیدنا علی اور عثمان رضی اللہ عنہما سے سامع حاصل ہے۔ ایک جماعت نے انہیں صحابہ میں ذکر کیا ہے۔ میں کہتا ہوں: یہ زکریا بن یحییٰ بن اسکن الطائی کے دادا ہیں جو بخاری کے شیخ ہیں۔ یحییٰ وہی عمر بن حصین بن حمید کے بیٹے ہیں۔ وہ ابن منہب بن حارثہ بن خرم بن اوس ہیں۔ اگر حمید صحابی ہوتے تو یہ چاروں بالترتیب صحابی بن جاتے۔ لیکن کسی نے بھی حارثہ اور منہب کو صحابہ میں ذکر نہیں کیا۔ اس سے اس شخص کا کون مزید بڑھ جاتا ہے جس نے حمید کو صحابہ میں ذکر کیا ہے۔ حرف الف میں اوس بن حارثہ کا ذکر گزر چکا ہے جس سے یہ لازم آتا ہے کہ وہ پانچ ہیں۔ لیکن یہ انتہائی بعید بات ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۶۳)\n(2) استیعاب (۴۳/۱)"}],[1842,"§۱۸۴۳ ۔ حمید انصاری(1)\nبقول بعض یہ وہی ہیں جن کا زبیر رضی اللہ عنہ سے حزہ کی نالی میں جھگڑا ہو گیا تھا۔ وہ حدیث صحیحین(2) میں بطریق زہری عروہ و بن زبیر سے مروی ہے، اس میں ان کا نام نہیں لیا گیا۔ اس میں صرف اتنا ہے کہ ایک انصاری کا زبیر رضی اللہ عنہ سے جھگڑا ہو گیا۔ اسے ابو موسیٰ نے بطریق لیث، بجوا الزہری نقل کیا ہے جس میں ان کا نام حمید لیا ہے۔ ابو موسیٰ فرماتے ہیں: مجھے ان کا نام صرف اسی طریق میں ملا ہے۔ میں کہتا ہوں: ان پر پھر اعتراض ہوتا ہے کہ بعض طرق میں ہے کہ وہ بدر میں شریک ہوئے تھے۔ لیکن بدری صحابہ میں حمید نامی کوئی شخصیت نہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۱۲۶۹) استیعاب (۶۰۰)\n(2) بخاری کتاب المساقاۃ (۲۳۵۹) (۲۳۶۰) مسلم کتاب الفضائل (۶۰.۶۵)"}],[1843,"§۱۸۴۴ ۔ (ز) حمید (دوسرے بے نسبت)\nباوردی بطریق عطاء بن سائب، مالک بن حارث سے بحوالہ ایک شخص جبکہ کتاب میں بحوالہ حمید ہے، روایت کرتے ہیں، فرمایا: نبی صلی اللہ علیہ وسلم نے ایک شخص کو کسی سریہ کا امیر بنایا۔ جب آیا آپ نے اس سے پوچھا: امارت کیسی لگی؟ انہوں نے عرض کیا: میں تو اپنے آپ کو عام سا آدمی سمجھتا رہا۔ آپ نے فرمایا: \"بادشاہت والا گھاٹی کے دروازے پر ہوتا ہے مگر جسے اللہ تعالیٰ بچا لے\"۔ (حدیث)۔ اسے طبرانی(1) نے اسی سند سے نقل کیا ہے، لیکن حمید بن ثور کے حالات میں لکھی ہے اور دوسری سند سے روایت کی تو حمید کی جگہ خیثمہ کہا۔","",{"fn":"(1) المعجم الکبیر (۵۵/۴)"}],[1844,"§۱۸۴۵ ۔ (ز) حُمیر(1)\nابن عدی القاری نطی۔ ابن ماکولا(2) نے ان کا ذکر کیا ہے کہ انکیں شرف صحابیت حاصل ہے۔ یہ بھی ذکر کیا کہ انہوں نے عبد اللہ بن ابی کی باندی معاذہ سے شادی کر لی تھی جن کا ذکر خواتین کے حصے میں آئے گا۔ جن سے اسم سعید اور پھر جزواں حارث اور عدی پیدا ہوئے۔ جس کی وضاحت معاذہ کے حالات میں آئے گی، اور ان کا ذکر بھی آئے گا جو بغیر تشدید حُمیر کہتے ہیں۔","",{"fn":"(1) الاکمال (۵۱۷/۲)\n(2) الاکمال (۵۱۷/۲)"}],[1845,"§۱۸۴۶ ۔ حُمیر (دوسرے) جیسے پہلا نام تھا\nانجمن ہیں اور نبی مکرمہ جو انصاری شاخ ہے اس کے حلیف ہیں۔ پہلے پہل مسجد ضرار والوں میں شامل تھے پھر تائب ہو گئے۔ یہ بات ابن ماکولا(1) نے بحوالہ الغلابی نقل کی ہے کہ عنقریب عبد اللہ بن حمیر انجمنی اور حمیر بن جحیر کا ذکر آئے گا۔ وہاں دیکھ لیا جائے۔","",{"fn":"(1) اسد الغابۃ (۱۲۷۰)"}],[1846,"§۱۸۴۷ ۔ (ز) حمیضہ بن مالک\nبن سعد حمرہ بغیر تشدید میں تذکرہ گزر چکا ہے۔"],[1847,"§۱۸۴۸ ۔ حُمیضہ ضاد سے تصغیر ہے۔ ابن البان خانطو والی میں بعنوان تصغیر تذکرہ ہو گا۔"],[1848,"§۱۸۴۹ ۔ حمیضہ بن رقیم انصاری(1)\nاز اول اللہ، عدووی اور قدر اج نے انہیں شرکاء احد میں ذکر کیا ہے اور اول اللہ کے چار افراد کے علاوہ کوئی مسلمان نہیں ہوا، ان میں سے ایک یہ بھی ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۲۷۲)"}],[1849,"§۱۸۵۰ ۔ (ز) حُمیضہ بن النعمان\nبن حمید البارقی۔ سیف کا بیان ہے سیدنا عمر رضی اللہ عنہ نے انہیں دستوں کا امیر مقرر کیا تھا اور سیدنا سعد بن ابی وقاص رضی اللہ عنہ کے ساتھ اھل کے آغاز میں عراق روانہ کیا تھا۔ طبری نے بھی ان کا ذکر کیا ہے۔ اور یہ پہلے بتایا جا چکا ہے کہ اس دور میں صرف صحابہ ہی امیر مقرر ہوتے تھے۔"],[1850,"§۱۸۵۱ ۔ حُمیل (تصغیر ہے)(1)\nابن بصیر بن ابی بصیرہ الغفاری۔ علی بن المدینی کا قول ہے: میں نے بنی غفار کے ایک بوڑھے سے پوچھا: آپ کے قبیلے میں جمیل بن بصیر نامی کوئی شخص ہے؟ تو وہ بولا: میاں! تم نے یہ نام بالکل غلط بولا ہے، یہ نام تو حُمیل ہے۔ اور اپنے پاس کھڑے ایک لڑکے کی طرف اشارہ کرتے ہوئے کہا: وہ اس لڑکے کے دادا تھے۔ مصعب زبیری کا قول ہے: جمیل، بصیرہ اور جمیل کے دادا ابو البصرہ نسب کو شرف صحابیت حاصل ہے۔ ابن اسکن کا قول ہے: ان کے دادا ابو البصرہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خیبر میں شریک ہوئے۔ جمیل کی کنیت بھی ابو البصرہ ہے۔","",{"fn":"(1) اسد الغابۃ (۵۹/۱)"}],[1851,"§۱۸۵۲ ۔ حُفیلہ بن عامر\nبن اثیب الازحی۔ ابن بکیر نے ان کا ذکر کیا ہے کہ احزاب کے روز رسول اللہ صلی اللہ علیہ وسلم کے ساتھ معاہدہ کرنے والوں میں سے ہیں۔ میں کہتا ہوں: یہ مشہور صحابی فصیم بن مسعود غفاری کے بچے ہیں۔ رشاطی کا قول ہے: ابو عمر اور ابن فتون نے صحابہ رضی اللہ عنہم میں حفیلہ کا ذکر نہیں کیا ہے یعنی باوجود یک ان کی شرطوں کے مطابق ہیں۔ میں کہتا ہوں: ان کے نام کو قلمبند کرنے میں اختلاف ہے۔ بقول بعض: حفیم سے جمیل اور بقول بعض: حفیلہ، اور پھر دوسرے حرف میں بھی اختلاف ہے بعض نے با سے اور بعض نے ثا سے لکھا ہے، ہر ایک طرف سے پہلے اشارہ ہو چکا ہے۔"],[1852,"§۱۸۵۳ ۔ حنبل بن کعب\nاہل، حرف حاء میں تذکرہ ہو گا۔"],[1853,"§۱۸۵۴ ۔ احنش ابن عقیل(1)\nبنی حُفیلہ بن جمیل کے فرد، غفار کے بھائی۔ ان کی ایک طویل حدیث ہے، اسی میں ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں اسلام کی دعوت دی تو وہ اسلام لے آئے۔ ابن الاثیر(2) نے اسی طرح لخبر حال ذکر کیا ہے اور ابن فتون نے \"ذویل\" میں قاسم کی طرف اس کی نسبت کی ہے۔ اور \"دلائل\" میں یہ روایت مجھے موسیٰ بن عقبہ کے طریقہ سے بحوالہ منور بن محمد ملی ہے، فرماتے ہیں: ہم سیدنا عمر رضی اللہ عنہ کے ساتھ حج کے ارادے سے نکلے، جب مقام عرجن پر پہنچے تو کسی آواز دینے والے نے راستے سے آواز دی: بچھڑو! ہم لوگ ظہر گئے۔ وہ پوچھنے لگا: کیا تم میں رسول اللہ صلی اللہ علیہ وسلم ہیں؟ سیدنا عمر رضی اللہ عنہ نے اس سے کہا: جانتے ہو کیا کہہ رہے ہو؟ اس نے کہا: جی ہاں۔ آپ نے فرمایا: وفات پا گئے ہیں۔ اس نے \"انا للہ وانا الیہ راجعون\" پڑھا، پھر اس نے کہا: ان کے بعد کون والی بنا؟ آپ نے فرمایا: ابو بکر وہ کہنے لگا کیا وہ تم میں موجود ہیں؟ آپ نے فرمایا: وفات پا گئے ہیں۔ اس نے انا للہ وانا الیہ راجعون پڑھا، پھر اس پر کہا: ان کے بعد والی کون بنا؟ آپ نے فرمایا: عمر۔ اس نے کہا: کیا وہ تم میں موجود ہیں؟ آپ نے فرمایا: وہی ہے جس سے تم مخاطب ہو۔ اس نے کہا: مدد! مدد! آپ نے فرمایا: تم کون ہو؟ اس نے کہا: میں حنش بن عقیل، بنی حُفیلہ بن جمیل کا ایک فرد ہوں۔ میری رسول اللہ صلی اللہ علیہ وسلم سے بنی جعال کے کشادہ میدان میں ملاقات ہوئی تھی، آپ صلی اللہ علیہ وسلم نے مجھے اسلام کی دعوت دی تو میں مسلمان ہو گیا۔ آپ نے مجھے اپنے بچے ہوئے ستوں میں سے پینے کے لیے دیئے۔ تو آج تک جب بھی میں پیاسا ہوتا ہوں تو اس کی سیرابی اور جب بھوکا ہوتا ہوں تو اس کی سیری محسوس کرتا ہوں۔ پھر میں نے سفید پہاڑ کی چوٹی کا قصد کیا جس میں اپنے اہل وعیال کے ساتھ دس سال تک رہا، روزانہ پانچ وقت نماز پڑھتا، رمضان کے روزے اور دس ذو الحجہ میں قربانی کے لیے جانور ذبح کرتا، مجھے رسول اللہ صلی اللہ علیہ وسلم نے ایسے ہی سکھایا تھا۔ پھر وہ کہنے لگا: ہمیں قحط سالی کی شکایت ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تمہیں مدینہ پہنچ چکی ہے۔ آپ نے فرمایا: پانی کے مقام پر مجھ سے ملنا۔ راوی کا بیان ہے کہ وہاں سے گزر کر جب ہم واپس آئے پانی والے سے اس شخص کے متعلق پوچھا تو اس نے بتایا: یہ اس کی قبر ہے۔ سیدنا عمر رضی اللہ عنہ نے قبر پر آئے اور اس کے لیے دعا و استغفار کیا۔","",{"fn":"(1) اسد الغابۃ (۱۲۷۵) استیعاب (۵۷۷) تجرید (۱۴۱/۱)\n(2) استیعاب (۴۴۸/۱)"}],[1854,"§۱۸۵۵ ۔ حَنطب بن حارث(1)\nبن عبید بن عمرو بن حزم قریشی مخزومی ابو عبد اللہ۔ بقول ابو عمر: فتح مکہ کے روز اسلام لائے۔(2) باوردی وغیرہ نے بطریق مخیرہ بن عبد الرحمن، مطلب بن عبد اللہ بن حنطب بحوالہ ان کے والد وہ اپنے دادا سے روایت کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"ابو بکر و عمر کی حیثیت ایسی ہے جیسے چہرے میں آنکھیں اور کان ہوتے ہیں\"۔(3) ابو عمر فرماتے ہیں: ان کی اس کے علاوہ کوئی حدیث نہیں۔ میں کہتا ہوں: لیکن اس کی سند میں کافی اختلاف ہے، ان شاء اللہ تعالیٰ ان کا تذکرہ عبد اللہ بن حنطب کے سوانح میں آئے گا۔","",{"fn":"(1) اسد الغابۃ (۱۲۷۹) استیعاب (۵۶۸) تجرید (۱۴۱/۱)\n(2) کنز العمال (۳۲۶۵۵) جامع المسانید (۶۰.۱۰/۳)\n(3) مسند احمد (۶۷/۵)"}],[1855,"§۱۸۵۶ ۔ (ز) حنظلہ بن ثعلبہ\nبن سیار۔ نزدیک ہی ابن سیار میں ان کا تذکرہ ہو گا۔"],[1856,"§۱۸۵۶ ۔ حنظلہ بن حذیم(1)\nبن حنیفہ تیمی۔ انیس اسدی، اسد خزیمہ اور مالکی بھی کہا جاتا ہے۔ مالک، بنی اسد بن خزیمہ کا بطن ہے۔ تمیم تک ان کا نسب ان کے دادا حنیفہ کے حالات میں بیان ہو گا۔ یہ ان کے والد اور دادا، تینوں صحابی ہیں۔ ان کے متعلق عقلی نے حنظلہ بن حنیفہ بن حذیم کی روایت لکھا ہے اور اول بدل کر دیا ہے۔ امام بخاری رحمہ اللہ نے یہ بات کسی راوی سے نقل کی ہے۔ امام احمد(2) نے فرمایا: ابو سعید مولیٰ بنی ہاشم نے ہمیں بحوالہ ذیال بن عبید بتایا، وہ فرماتے ہیں: میں نے اپنے دادا حنظلہ بن حذیم سے سنا کہ میرے دادا حنیفہ نے حذیم سے فرمایا: میرے بچوں کو اکٹھا کرو۔ پھر انہیں وصیت فرمائی۔ فرمایا: یہ جو یتیم میری گود میں ہے اس کے لیے سوا ونٹ ہیں۔ اس پر حذیم نے کہا: ابا جان! میں نے آپ کے بیٹوں سے سنا ہے کہ وہ کہتے ہیں کہ جب تک ہمارا باپ زندہ ہے اس کی خوشی کے لئے تو ہم اس کا اقرار کریں گے لیکن جب وہ فوت ہو گیا تو اس سے پھر جائیں گے۔ چنانچہ بارگاہ نبوت میں یہ مقدمہ پیش کیا۔ حنیفہ، حذیم اور ان کے ساتھ حنظلہ جو ابھی لڑکے تھے، اپنے باپ حذیم کے ساتھ سوار تھے آگے۔ حنیفہ نے نبی صلی اللہ علیہ وسلم کے سامنے اپنا واقعہ بیان کیا۔ آپ اتنے ناراض ہوئے کہ گھٹنوں کے بل بیٹھ کر فرمانے لگے: نہیں۔ بلکہ صدقہ واحسان پانچ یا دس میں حد ہو گئی ہیں، اگر بڑھ جائیں تو چالیس۔ فرمایا: پھر انہوں نے آپ کو الوداع کہا۔ یتیم کے پاس ایک لٹھی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یتیم کی یہ لٹھ بری ہو گئی\"۔ حذیم نے عرض کی: میرے پاس ہمیں بچے ہیں یہ ان میں سب سے کم سن ہے۔ یعنی حنظلہ اس کے لیے اللہ تعالیٰ سے دعا کریں تو آپ نے ان کے سر پر ہاتھ پھیر کر فرمایا: اللہ تجھے برکت دے، یا فرمایا: \"تجھے برکت مل گئی\"۔ ذیال فرماتے ہیں: میں نے خود دیکھا کہ حنظلہ کے پاس ایسا شخص لایا جاتا جس کا چہرہ سوجا ہوتا تھا، آپ اپنے ہاتھوں پر پھونک مارتے اور بسم اللہ پڑھ کر اپنے سر کے اس مقام پر جہاں نبی صلی اللہ علیہ وسلم نے اپنا دست مبارک رکھا تھا رکھتے اور پھر ورم والی جگہ پر ہاتھ پھیرتے تو وہ ختم ہو جاتا۔ حسن بن سفیان نے اسے اپنی سند میں دوسری سند سے بحوالہ ذیال روایت کی ہے اور اس میں یہ اضافہ نقل کیا ہے کہ یتیم کا نام ضرلیس بن حنیفہ تھا جو بالغ کے مشابہ تھے۔ طبرانی(3) نے یہ طویل روایت مختصر نقل کی ہے۔ اور ابو یعلیٰ نے اسی سند سے روایت تو کی ہے لیکن مکمل نہیں۔ اسی طرح یعقوب بن سفیان اور تحیتی وغیرہ نے اپنی سند میں روایت کی ہے۔ حسن بن سفیان، باوردی اور ابن اسکن نے مسلم بن قتیبہ کے طریق سے بحوالہ ذیال روایت کی ہے، فرمایا: میں نے اپنے دادا حنظلہ سے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"بلوغت کے بعد یتیمی نہیں رہتی اور ماہواری کا خون دیکھنے کے بعد کوئی لڑکی نماز نہ پڑھے\"۔","",{"fn":"(1) اسد الغابۃ (۱۲۷۷) استیعاب (۵۶۹)\n(2) التاریخ الکبیر (۳۷/۱)\n(3) المعجم الکبیر (۳۵۰.۲/۴)"}],[1857,"§۱۸۵۸ ۔ حنظلہ بن ابی حنظلہ انصاری(1)\nمسجد قباء کے امام، امام بخاری(2) نے صحابہ میں ان کا ذکر کیا ہے اور ان کی ایک موقوف حدیث بطریق جبلہ بن سحیم روایت کی ہے کہ میں نے حنظلہ انصاری مسجد قباء کے امام کی اقتداء میں نماز پڑھی، وہ صحابی رسول اللہ صلی اللہ علیہ وسلم تھے۔ انہوں نے سورہ مریم کی قراءت کی، جب آیت سجدہ آئی تو سجدہ کیا۔ اس کی سند صحیح ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۷۸)\n(2) کنز العمال (۳۲۴۴۰) جامع المسانید (۲۱۱/۳)"}],[1858,"§۱۸۵۹ ۔ حنظلہ بن ابی حنظلہ ثقفی(1)\nعبد الصمد بن سعید نے تحس فروش ہونے والے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ اور ابن شاہین بطریق ابن عائد، غضیف بن حارث سے بحوالہ قدامہ اور حنظلہ (جو دونوں ثقفی ہیں) روایت کی ہے، فرماتے ہیں: آپ صلی اللہ علیہ وسلم کی عادت مبارک تھی کہ جب دن اچھی طرح ہو جاتا، ہر ایک چلا جاتا اور لوگ گھروں کی طرف لوٹ جاتے تو آپ مسجد تشریف لاتے، دو گانہ ادا فرماتے یا چار رکعتیں پڑھتے۔ دیکھتے کیا کوئی دکھ رہا ہے، پھر لوٹ جاتے۔(2) ابن اسکن فرماتے ہیں: اس کی سند صحیح ہے جو مشہور نہیں۔","",{"fn":"(1) المعجم الکبیر (۳۴/۲) کنز العمال (۳۰۳۰۱)\n(2) ترمذی کتاب صفۃ القیامۃ والرقائق والورع (۵۹) (۲۵۱۴)"}],[1859,"§۱۸۶۰ ۔ (ز) حنظلہ بن راہب\nابن ابی عامر میں تذکرہ ہو گا۔"],[1860,"§۱۸۶۱ ۔ حنظلہ بن ربیع(1)\nبن صیفی بن رباح بن حارث بن مخاشن بن معاویہ بن شریف بن جرہ بن اسید بن عمرو بن تمیم ابو ربی، انہیں حنظلہ کاتب بھی کہا جاتا ہے۔ اتم بن صیفی کے بھتیجے ہیں۔ ابن اسحاق کا بیان ہے، نبی صلی اللہ علیہ وسلم سے روایت کی اور آپ صلی اللہ علیہ وسلم کے کاتب بھی رہے۔ آپ نے انہیں اہل طائف کی جانب سفیر بنا کر بھیجا تھا۔ قادسیہ میں شریک ہوئے۔ کوفہ فروش ہوئے تو جنگ جمل میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ قریشیاء ڈیرہ جمایا اور بالآخر امیر معاویہ کی خلافت میں وفات پا گئے۔ لوگوں کا کہنا ہے کہ جنات نے ان کے سوگ میں مرثیہ کہا تھا۔ ان کی بیوی نے ان کے متعلق یہ اشعار کہے تھے: \"حنظلہ کاتب پر آنسو بہا تے بہاتے میری آنکھیں ضائع ہو جائیں گی\"۔ ترمذی(2) میں بطریق ابو عثمان نہدی سیدنا حنظلہ سے مروی ہے وہ کاتب رسول اللہ صلی اللہ علیہ وسلم تھے۔ ان سے عثمان نہدی اور ان کا بھتیجا مرقع بن صیفی بن رباح بن ربیع وغیرہ روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۲۸۴) تجرید (۱۴۲/۱)\n(2) ترمذی کتاب التفسیر باب سورۃ سبا (۳۲۲۲) المعجم الکبیر (۳۲۵/۸)"}],[1861,"§۱۸۶۲ ۔ (ز) حنظلہ بن ربیعہ اسدی\nابن اسحاق کا بیان ہے کہ وہ تمیم کے وفد میں شامل تھے، نبی صلی اللہ علیہ وسلم نے انہیں سے فرمایا: \"اپنی قوم کو اسلام کی دعوت دینا\"۔(1) غالب گمان یہی ہے وہ پہلے والے ہیں، اس لیے کہ ان کے والد کے نام کے متعلق گزرا ہے کہ وہ ربیعہ ہیں وہ اسدی ہیں بھی شاید ان کی اصل اسیدی ہو۔ نیز حنظلہ کاتب کو اسیدی (تشدید سے) اسید بن عمرو بن تمیم کی طرف نسبت کی وجہ سے کہا جاتا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۸۱) استیعاب (۵۶۷)"}],[1862,"§۱۸۶۳ ۔ (ز) حنظلہ بن سیّار\nبن سعد بن حذیمہ بن سعد بن عجل عجلی۔ ابو عبیدہ نے کتاب الامثال میں لکھا ہے وہ جاہلیت میں سردار تھے انہی نے ذی قار کے روز تو چرپا یا تھا جس پر کبر بن وائل نے پڑھ کر فارسیوں کو شکست دی تھی۔ آپ صلی اللہ علیہ وسلم کو اس کی اطلاع ملی تو آپ صلی اللہ علیہ وسلم نے بڑی مسرت فرمائی اور ارشاد فرمایا: \"یہ پہلا دن ہے جس میں عرب اہل عجم سے آدھے ہو گئے اور میری وجہ سے ان کی مدد کی گئی\"۔(1) اس روز سیدنا حنظلہ نے غنیمت کا خمس نبی صلی اللہ علیہ وسلم کی طرف بھیجا اور آپ صلی اللہ علیہ وسلم نے فتح کو خبر دی جبکہ اس سے پہلے چوتھائی حصے کے باج گزار تھے۔ سیدنا حنظلہ رضی اللہ عنہ کو جب یہ آیت معلوم ہوئی: \"تمہیں علم ہو جانا چاہیے کہ جو مال غنیمت بھی تمہیں حاصل ہو تو اس میں سے پانچواں حصہ اللہ اور اس کے رسول کا ہے\"۔(2) تو بہت خوش ہوئے۔ اسی کے متعلق فرماتے ہیں: \"ہم نے گھوڑوں کے ساتھ ایک وفد بھیجا جنہیں اودنیاں نبی محمد صلی اللہ علیہ وسلم کی طرف لے جا رہی تھیں۔ ہر جز اور قوم سے جو سابقہ پڑا کہ انہوں نے کیسے جنگ کی اور جو کچھ گھاٹ پر اترنے کے وقت نعمان سے پیش آیا سب کچھ کہا کہ بھجا ہے\"، نعمان بن زرعہ ثقفی مراد ہیں، اس سے پتہ چلتا ہے کہ وہ اسلام لائے تھے اس واسطے کہ یہ واقعہ ہجرت کے کافی مدت بعد پیش آیا ہے اور یہ بلند نہیں کہ وہ حجۃ الوداع میں شریک ہوئے ہوں گے۔ تمیم اشعراء میں مزبانی نے ان کا سرسری ذکر کیا ہے۔ لیکن انہوں نے لکھا ہے: \"حنظلہ بن ثعلبہ بن سیار عجلی\" اور ان کے وہ اشعار درج کیے ہیں جن میں وہ عربوں کو فارسیوں سے جنگ کی ترغیب دیتے ہیں: \"میری قوم جنگ سے خوش رہنا، آج ہی وہ دن ہے جس میں فارسیوں کے دانت توڑ دو\"۔ چند اشعار یہ ہیں: \"ان کی فوجیں اتر آئی ہیں سو ہمت کوشش کرو۔ مجھے کیا پیاری ہے جبکہ میں سخت اور مضبوط ہوں، اور کمان کی تانت ایسی سخت ہے جیسے اونٹ کا بازو یا اس سے بھی زیادہ سخت\"۔ ابن ہشام کا قول ہے کہ جنگ ذی قار میں وہ بنی عجل میں کے سردار تھے البتہ جنہوں نے قربا لگایا تھا وہ ان کے بیٹے سعد بن حنظلہ تھے۔ واللہ اعلم","",{"fn":"(1) السیرۃ النبویۃ (۶۱/۳)\n(2) سورۃ الانفال: ۴۱"}],[1863,"§۱۸۶۴ ۔ حنظلہ بن طفیل سلمی\nفتوحات شام کے ایک امیر۔ یعقوب بن سفیان نے اپنی تاریخ میں بواسطہ عمار، سلمہ سے بحوالہ ابن اسحاق ذکر کیا ہے کہ ۱۵ھ میں ابو عبیدہ بن الجراح حنظلہ بن طفیل سلمی کو حمص روانہ کیا جسے اللہ تعالیٰ نے ان کے ہاتھ فتح کر دیا۔ میں کہتا ہوں: بارہا گزر چکا ہے کہ ان مواضع میں صحابہ ہی امیر بنائے جاتے تھے۔"],[1864,"§۱۸۶۵ ۔ حنظلہ بن ابی عامر(1)\nبن صیفی بن مالک بن امیر بن ضبیعہ بن زید بن عوف بن عمرو بن عوف بن مالک بن اوس انصاری اوسی۔ شمیل (نہبالے) مالک سے مشہور ہیں۔ جاہلیت میں ان کے والد راہب سے جانے پہچانے جاتے تھے۔ ویسے ان کا نام عمرو ہے بقول بعض عبد عمرو تھا۔ وہ بعثت بعد الموت اور دین ابراہیمی کا ذکر کرتے رہتے تھے۔ لیکن جب نبی صلی اللہ علیہ وسلم مبعوث ہوئے تو آپ صلی اللہ علیہ وسلم سے حسد و عناد رکھنا شروع کر دیا۔ مدینہ سے نکل کر احد میں قریش کا ساتھ دیا۔ پھر انبی کے ساتھ مکہ لوٹ گئے۔ اس کے بعد روم کے لیے پا برکاب ہوئے اور وہیں وہ ۹ھ میں ہلاک ہو گئے۔ ایک قول ہے ۱۰ھ میں یہ واقعہ ہوا۔ ہر قل نے ان کی میراث کنانہ بن عبد یالیل ثقفی کو دے دی۔ (آزر کے گھر ابراہیم) ان کے بیٹے حنظلہ مسلمان ہو گئے ان کا اسلام ایسا سنورا کہ غزوہ احد میں شہید ہوئے جس میں کسی کا اختلاف نہیں۔ ابن شاہین، ہشام بن کتب کی ایک اچھی سند سے بحوالہ ان کے والد روایت کرتے ہیں کہ حنظلہ بن ابی عامر اور عبد اللہ بن ابی بن سلول دونوں نے اپنے اپنے باپوں کو قتل کرنے کی اجازت مانگی۔ آپ صلی اللہ علیہ وسلم نے دونوں کو اس سے روک دیا۔ ابن اسحاق فرماتے ہیں: محمد بن عاصم بن عمر بن قتادہ نے بیان کیا اور سراج نے اسی طرح ابن اسحاق(2) کے طریق سے نقل کیا ہے کہ یحییٰ بن عباد بن عبد اللہ بن زبیر نے بحوالہ اپنے دادا اپنے والد سے روایت کرتے ہیں کہ حنظلہ بن ابی عامر غسیل ثقفی اور ابو سفیان بن حرب آپس میں تختم لگھا تھے جب حنظلہ ابو سفیان پر قتل کرنے کے لیے پڑھے تو شداد بن شعب نے انہیں دیکھ لیا، تلوار سے حملہ کر کے انہیں شہید کر دیا۔ ورنہ ابو سفیان کو قتل کرنے ہی والے تھے۔ ادھر نبی صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے ساتھی (حنظلہ) کو فرشتے غسل دے رہے ہیں۔ جا کر اس کی بیوی سے (ماہر ا) پوچھنا\"۔ انہوں نے جواب دیا کہ جونہی ان کے کان شور کی آواز پڑی تو وہ جنابت کی حالت میں نکل گئے۔ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسی بنا پر فرشتے انہیں غسل دے رہے ہیں\"۔","",{"fn":"(1) اسد الغابۃ (۱۲۸۷)\n(2) اسد الغابۃ (۶۴/۲)"}],[1865,"§۱۸۶۶ ۔ حنظلہ بن عمرو اسلمی(1)\nحسن بن سفیان نے ان کا صحابہ میں تذکرہ کیا ہے اور حسین بن مہدی سے بحوالہ عبد الرزاق، ابن جریج(2)، زیاد بن ربیعہ، ابو الزناد، حنظلہ بن علی اسلمی ان کے سلسلہ سند میں حنظلہ بن عمرو اسلمی سے روایت ہے، فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہم روانہ فرمائی۔۔۔ (حدیث)۔ ابو نعیم فرماتے ہیں: اس میں حسن سے وہم ہوا ہے۔ درست یوں ہے: \"حمزہ بن عمرو سے مروی ہے\"۔ چنانچہ امام احمد(3) بطریق عبد الرزاق سے اور محمد بن بکر ابن جریج سے اور ابو داؤد محمد بن حمزہ بن عمرو اسلمی کے طریق سے وہ بحوالہ اپنے والد اسی طرح روایت کرتے ہیں۔ میں کہتا ہوں: یہ ساری باتیں اپنی جگہ درست ہیں لیکن اس سے احتمال کی نفی نہیں ہوتی۔","",{"fn":"(1) اسد الغابۃ (۱۲۸۵)\n(2) المصنف لعبد الرزاق (۹۴۱۸) عن حمزۃ بن عمرو الاسلمی\n(3) مسند احمد (۴۰۷/۲)"}],[1866,"§۱۸۶۷ ۔ (ز) حنظلہ بن قسامہ(1)\nبن قیس بن عبید بن ظریف طائی۔ ابو عمر(2) نے ان کی بیٹی زینب جو اسامہ بن زید رضی اللہ عنہ کی اہلیہ تھیں کے سوانح میں ان کا ذکر کیا ہے کہ وہ اپنی بیٹی کے ساتھ آئے تھے۔ جس کی وضاحت زبیر بن بکار کی کتاب النسب کے حوالہ سے ان شاء اللہ تعالیٰ صحیح تفصیل کے ساتھ آئے گی۔","",{"fn":"(1) اسد الغابۃ (۱۲۹۱) تجرید (۱۴۲/۱)\n(2) استیعاب (۴۳۲/۱)"}],[1867,"§۱۸۶۸ ۔ حنظلہ بن قیس(1)\nالحنفی الیمامی۔ بخوی وغیرہ نے ان کا ذکر کیا ہے۔ اور بطریق دھشم، بحوالہ عمران بن جاریہ انہوں نے اپنے والد سے نقل کیا ہے کہ ان میں اور ان کے چچا کی اولاد میں سے کسی شخص سے جسے حنظلہ بن قیس کہا جاتا تھا کبریاں چرانے کی جگہ پر جنگ چھڑ گئی۔ حنظلہ نے جاریہ کا ہاتھ ان کی دائیں کہنی کے درمیان (جھٹ سے) وار کر کے کاٹ دیا، دونوں نے نبی صلی اللہ علیہ وسلم کی بارگاہ میں مقدمہ پیش کیا۔ آپ نے کاٹنے والے سے فرمایا: \"اپنا ہاتھ دے دو\"، تو اس نے انکار کر دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر دیت دو۔۔۔\" (حدیث) اسی حدیث کو ابن ماجہ(2) نے حدیث دھشم سے نقل کیا ہے۔ اور جس نے وار کیا اس کا اور جس پر وار ہوا دونوں کے نام خفی رکھے ہیں۔ ابن الاثیر(3) نے ابن دباغ کی کتاب پر اپنے اشتراک میں اس کا ذکر کر کے کہا: حنظلہ بن قیس انصاری ظفری کا تعلق بنی حارث بن ظفر سے ہے انہوں نے نبی صلی اللہ علیہ وسلم کی خدمت میں مقدمہ پیش کیا۔ ان کا انصاری کہنا وہم ہے باوجود یکہ اس کی وضاحت موجود ہے کہ وہ جاریہ کے عم زاد ہیں۔ اور جاریہ حنفی ہیں جیسا کہ ان کے حالات میں پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۹۰)\n(2) ابن ماجہ کتاب الدیات (۲۶۳۶)\n(3) اسد الغابۃ (۱۱۸۲) تجرید (۱۲۴)"}],[1868,"§۱۸۶۹ ۔ حنظلہ بن نعمان(1)\nبن عامر بن عجلان بن عمرو بن عامر بن زریق انصاری۔ عدوی کا بیان ہے کہ وہ احد میں شریک ہوئے اور سیدنا حمزہ کی اہلیہ خولہ سے شادی کی تھی۔ باوردی اور طبرانی نے حدیث عبد اللہ بن ابی رافع سے ذکر کیا ہے کہ انہوں نے انہیں جنگ صفین میں سیدنا علی رضی اللہ عنہ کے حامیوں میں شمار کیا ہے۔ البتہ انہوں نے یہ بھی کہا ہے: حنظلہ بن نعمان انصاری۔ یہ بھی احتمال ہے کہ عددی نے جن کا ذکر کیا ہو یہ ان کے علاوہ ہوں۔","",{"fn":"(1) جامع المسانید (۶۱۲/۳) اتحاف السادۃ (۲۷۰)"}],[1869,"§۱۸۷۰ ۔ حنظلہ بن ہوذہ(1)\nبن خالد بن ربیعہ بن عمرو بن عامر بن مصعب۔ عبدان نے ایک منقطع سند سے نقل کیا ہے کہ وہ تالیف قلبی والوں میں سے تھے۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۹۲)"}],[1870,"§۱۸۷۱ ۔ حنظلہ عبشمی(1)\nعسکری نے ان کا ذکر کیا اور بطریق قتادہ، ابو العالیہ سے بحوالہ صحابی رسول صلی اللہ علیہ وسلم حنظلہ عبشمی روایت کی ہے: \"جو قوم کسی جگہ بیٹھ کر اللہ تعالیٰ کا ذکر کرتی ہے تو آسمان سے ایک فرشتہ اعلان کرتا ہے، اٹھو (تو) تمہارے گناہ معاف اور تمہاری برائیاں نیکیوں سے بدل دیا گیا ہے\"۔(2) اس کے سلسلہ سند میں قتادہ وہ تک ضعیف ہے۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۹۵)\n(2) الاکمال (۵۰۹/۲)"}],[1871,"§۱۸۷۲ ۔ حُنیف (تصغیر)(1)\nابن راکب بن حارث بن امیر بن زید بن سالم بن عوف بن عمرو بن عوف انصاری۔ عدوی اور عسکری کا کہنا ہے: احد میں شریک ہوئے جبکہ مصعب زبیری بحوالہ ابن الفتح ان قتل کرتے ہیں کہ احد اور بعد کی مہمات میں شریک کار رہے۔ اور ان کے بیٹے(2) رکاب بن حنیف بدر میں شریک اور بئر معونہ کے واقعہ میں شہید ہوئے۔ دوسرے بیٹے عصمہ بن رکاب نے بیعت رضوان کی اور جنگ یمامہ میں شہادت پائی۔ العسکری نے تینوں کا اسی طرح ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۹۱) استیعاب (۶۰۲)\n(2) مسند احمد (۷۲/۵) مستدرک (۱۹۲/۱) السنن الکبریٰ (۶۰/۱۰) سنن دارقطنی (۲۶۱/۳) کنز العمال (۳۹۷)"}],[1872,"§۱۸۷۳ ۔ (ز) حُنیفہ\nابن جبیر بن بکر کی بن سعد بن ثعلب بن زید مناۃ بن تمیم تھی۔ حنظلہ بن حذیم کے دادا۔ حنظلہ کی سرگزشت میں ان کا تذکرہ گزرا ہے۔"],[1873,"§۱۸۷۴ ۔ حنیفہ ابو حُرّہ رقاشی کے چچا(1)\nان کی حدیث ابو داؤد نے حمدان بن سلمہ بحوالہ علی بن زید، ابو حرّہ سے انہوں نے اپنے چچا سے نقل کی کہ ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا کسی مسلمان کا مال اس کی طیب رضا مندی کے بغیر (استعمال کرنا) جائز نہیں۔(2) باوردی، طبرانی اور کئی دوسرے لوگوں نے اس پر اعتماد کیا ہے کہ ان کے چچا کا نام حنیفہ ہے۔ بقول بعض: حنیفہ ابو حرّہ کا نام ہے۔ ایک قول ہے کہ ابو حرّہ کا نام حکیم ہے۔","",{"fn":"(1) التاریخ الکبیر (۱۰۴/۱)\n(2) الجرح والتعدیل (۲۸۵/۳)"}],[1874,"§۱۸۷۵ ۔ حنین(1)\nعباس بن مطلب کے آزاد کردہ غلام۔ امام بخاری، ابو حاتم(2) اور ابن حبان(3) کا قول ہے کہ صحابی ہیں۔ سنکو یہ ہے \"فوائد\" میں اور امام بخاری نے تاریخ میں ضمین بن عبد اللہ بن حنین سے بحوالہ ان کی چچھی کی وہ اپنے ماموں سے روایت کرتی ہیں انہیں ابن شاعر کہا جاتا تھا، کہ ان کے دادا نبی صلی اللہ علیہ وسلم کے غلام تھے، آپ صلی اللہ علیہ وسلم نے انہیں اپنے چچا سیدنا عباس رضی اللہ عنہ کو ہبہ کر دیا، انہوں نے نے انہیں آزاد کر دیا۔ وہ نبی صلی اللہ علیہ وسلم کی خدمت کیا کرتے تھے۔ آپ صلی اللہ علیہ وسلم جب وضو کر لیتے تو وضو کا بچا پانی اپنے صحابہ کو دے دیتے۔ حنین نے وہ پانی باہر نکالا تو صحابہ کرام نے آپ صلی اللہ علیہ وسلم سے اس بات کی شکایت کی، جس پر وہ بولے میں نے پینے کے لیے وہ پانی روک لیا تھا۔ (حدیث) یعقوب بن شیبہ اپنی سند میں جلال ح ابن کثیر کے طریق سے روایت کرتے ہیں، فرمایا: میں نے حنینا صحابی سے سنا: جنگ خیبر میں ہم لوگ تھے تو آپ صلی اللہ علیہ وسلم نے غنیموں پر سعد بن ابی وقاص اور سعد بن عبادہ رضی اللہ عنہما کو مقرر فرمایا۔ اسی میں ہے: \"سونابار برسراہ ہونا چاہیے\"۔(4) یہ عبد اللہ بن حنین سیدنا علی بن ابی طالب رضی اللہ عنہ سے روایت لینے والوں میں شامل ہیں۔ نسائی بھی نافع کے طریق سے بحوالہ ابراہیم بن عبد اللہ بن حنین وہ اپنے والد سے وہ سیدنا علی رضی اللہ عنہ سے رشمی لباس پہننے کی ممانعت میں ایک حدیث روایت کرتے ہیں۔ بقول بعض اس کی سند یوں ہے: نافع، عبد اللہ بن حنین سے وہ سیدنا علی رضی اللہ عنہ سے۔ اور ایک قول ہے نافع، حنین سے وہ سیدنا علی رضی اللہ عنہ سے۔ بہر کیف یہ پہلی سند زیادہ صحیح ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۹۹)\n(2) السنن الکبریٰ (۲۷۷/۵) المطالب العالیۃ (۱۲۹۴) الدر المنثور (۳۶۸/۱)\n(3) الثقات (۱۸۶/۴)\n(4) مسند احمد (۴۶۷/۳)"}],[1875,"§۱۸۷۶ ۔ حُوشب (بے نسبت)(1)\nمسند میں امام احمد(2) حمان بن کریب کے طریق سے روایت کرتے ہیں کہ ان میں سے ایک لڑکا محص میں فوت ہو گیا جس کی وجہ سے اس کے باپ کو بڑا دھچکا لگا۔ (تعزیت کے وقت) صحابی رسول صلی اللہ علیہ وسلم حوشب رضی اللہ عنہ نے ان سے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا۔ پھر اس شخص کی فضیلت میں حدیث سنائی جس کا کوئی بچہ فوت ہوا ہو۔ ابن اسکن فرماتے ہیں: اس میں ابن سمیع منفرد ہیں، جو ضعیف راوی ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۳۰۰)\n(2) جامع المسانید (۶۱۷/۳)"}],[1876,"§۱۸۷۷ ۔ حوشب (دوسرے)(1)\nحسن بن سفیان نے اپنی \"مسند\" میں اور ترمذی نے \"نوادر\" میں لیث کے طریق سے بحوالہ زید بن حوشب انہوں نے اپنے والد سے روایت کی ہے، فرماتے ہیں: میں نے نبی صلی اللہ علیہ وسلم سے سنا: \"اگر جرج فتیر (دین کی سمجھ بوجھ رکھنے والا) علم والا ہوتا تو اسے معلوم ہو جاتا کہ اپنی مال کو جواب دینا رب تعالیٰ کی عبادت سے بہتر ہے\"۔(2) ابن مندہ کہتے ہیں: غریب ہے یہ حکیم بن ریان، بحوالہ لیث بیان کرنے میں منفرد ہیں۔ ومیا طلی نے اپنے بخاری کے فتح پر حاشیہ میں لکھا ہے۔ جس کا خلاصہ یہ ہے لیث کی روایت ہے پھر پوری سند سے یہ حدیث نقل کی، پھر لکھتے ہیں: یہ وہی حوشب ہیں ذو ظلم سے مشہور ہیں اور ان کا نسب بیان کیا۔ عجیب بات ہے کیونکہ مذکورہ ذو ظلم صحابی نہیں جیسا کہ قسم ثالث میں آئے گا اور ان کے عالم نبوی کی صراحت موجود ہے۔ ایسی ہی تجویز یہ بھی کی ہے کہ صاحب عنوان وہی ذو ظلم ہیں۔ واللہ اعلم","",{"fn":"(1) تجرید (۱۴۴/۱) اسد الغابۃ (۱۳۰۱) استیعاب (۵۹۱)\n(2) کنز العمال (۴۰۵۴۱) الدر المنثور (۱۷۴/۴)"}],[1877,"§۱۸۷۸ ۔ حوط بن عبد العزی(1)\nیحییٰ حنائی، مسند، بخاری، طبرانی، ابن اسکن اور بخوی نے بطریق عبد الوارث بن سعید، حسین معلم سے بحوالہ بریدہ، حوط بن عبد العزی بجبر بخوی کی روایت میں حوط یا حویط سے مروی ہے کہ نبی صلی اللہ علیہ وسلم کے پاس سے ایک گروہ گزرا جس میں گھنٹی والے جانور تھے۔ آپ نے انہیں حکم دیا کہ \"گنٹھیاں اتار دو\"۔ ابن اسکن کا قول ہے: ابن عبد الوارث نے کہا کہ غلطی کی۔ وہ تو حوط بن عبد العزیز ہیں جو صحابی ہیں۔ اور جو انہیں صحابی کہتا ہے تو اس نے بے گلی پا گئی ہے۔ میں نے اس کے متعلق اپنے والد سے سنا ہے۔ اسی طرح اس سند میں عبد العزیز ہے شاید اس میں تحریف ہو گئی ہو اس واسطے کہ امام بخاری نے ایک جماعت کی طرح ان کا ذکر کیا ہے۔ ابو عمر(2) فرماتے ہیں: صحیح یہ ہے کہ وہ حوطا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۳۰۳) تجرید (۱۴۴/۱)\n(2) استیعاب (۴۵۴/۱)"}],[1878,"§۱۸۷۹ ۔ حَوط بن قرواش(1)\nبن حصین بن شامہ بن شہیب بن حدرد۔ ابن مندہ نے حاتم بن فضل بن سالم بن جون بن عثمان بن حوط بن قرواش کے طریق سے نقل کیا کہ فرماتے ہیں: مجھ سے میرے والد، ان سے ان کے والد نے بحوالہ جون بن غیاث وہ اپنے والد حوط سے روایت کرتے ہیں۔ فرمایا: میں اور بنی عدی کا وافد نامی شخص نبی صلی اللہ علیہ وسلم کے پاس آئے۔ یہ پہلا واقعہ ہے جب وہ اسلام لائے۔(2) اور بھی حدیث ذکر کی۔","",{"fn":"(1) اسد الغابۃ (۱۳۰۸)\n(2) جامع المسانید (۶۱۸/۳)"}],[1879,"§۱۸۸۰ ۔ حوط بن یزید ساعدی\nحارث بن زیاد ساعدی کے چچا زاد بھائی، حارث کے سوانح میں ان کا تذکرہ ہوا ہے۔"],[1880,"§۱۸۸۱ ۔ حُوَیرث\nبقول بعض آبی المحرم کا نام ہے۔"],[1881,"§۱۸۸۲ ۔ حُوَیرث(1)\nمالک کے پدر بزرگوار۔ بعض کا کہنا ہے کہ صحابی ہیں۔ طبرانی، عامر حمدری کے طریق سے بحوالہ ابو قلباب، مالک بن حویث سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ان کے والد کو یہ آیت پڑھائی: \"اس دن کوئی اس کے عذاب جیسا عذاب نہیں دے گا\"۔(2) اسی روایت کو حسن بن سفیان نے خالد الحذاء کے طریق سے بواسطہ ابو قلباب، مالک بن حویث سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے یہ آیت پڑھائی لیکن اپنے والد کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۱۳۰۹) استیعاب (۵۹۷)\n(2) سورۃ الفجر: ۲۵"}],[1882,"§۱۸۸۳ ۔ حُویصہ بن مسعود(1)\nبن کعب بن عامر بن عدی بن مجدعہ بن حارثہ بن حارث بن نزرج بن عمرو بن مالک بن اوس انصاری، احمد و خندق اور باقی غزوات میں شریک ہوئے۔ ابن اسحاق(2) حدیث محمد سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے کعب بن اشرف کے قتل ہو جانے کے بعد فرمایا: \"جو یہودی بھی ہاتھ چڑھے اس کا کام تمام کر دو\"۔ چنانچہ ابھی حویصہ اسلام نہیں لائے تھے کہ ایک سن رسیدہ یہودی تاجر پر کوڈ پڑے اور مار مار کر اسے قتل کر دیا۔ صحیحین(3) میں حدیث سہیل بن ابی خثمہ میں، عبد اللہ بن سہل کے قتل کے واقعہ میں ان کا ذکر ثابت ہے، اسی میں تھا کہ (جس مقتول کے قاتل کا پتہ نہ ہو تو جس جگہ سے لاش ملے گی وہاں کے رہائشی پچاس آدمیوں سے قسم لی جائے گی کہ نہ ہم نے اسے قتل کیا اور نہ ہمیں قتل کا پتہ) کا ذکر ہے۔ چنانچہ اس موقع پر عبد الرحمن بن سہل بات کرنے لگے جو عمر تھے آپ علیہ السلام نے فرمایا: \"بڑے کو موقع دو، بڑے کو بات کرنے دو\"۔ تو حویصہ نے گفتگو کی۔ (حدیث)","",{"fn":"(1) اسد الغابۃ (۱۳۱۰) استیعاب (۵۹۷)\n(2) السیرۃ النبویۃ (۴۹، ۴۸/۳)\n(3) بخاری کتاب الادب باب اکرام الکبیر (۶۰/۴) مسلم کتاب القسامۃ (۴۳۱۸)"}],[1883,"§۱۸۸۴ ۔ حویطب بن عبد العزی(1)\nبن ابی قیس بن عبد وذان بن نصر بن مالک بن حسل بن عامر بن لوی قریشی عامری ابو محمد۔ ابو الاصبغ، فتح مکہ کے سال اسلام لائے اور حنین میں شریک ہوئے۔ تالیف قلبی والوں میں سے تھے۔ سیدنا عمر رضی اللہ عنہ کے عہد میں حدود حرم کی تجدید کی۔ امام بخاری(2) لکھتے ہیں: ایک سو بیس(۱۲۰) سال زندہ رہے۔ واقدی کا قول ہے کہ امیر معاویہ رضی اللہ عنہ کی حکومت میں ۵۵ھ میں فوت ہوئے۔ ابن معین کا بیان ہے: مجھے حویطب کی نبی صلی اللہ علیہ وسلم سے روایت کردہ کوئی حدیث یاد نہیں پڑتی۔ اھ۔ جبکہ امام بخاری(3) نے سائب بن یزید کے طریق سے ان سے بحوالہ مسعودی سیدنا عمر رضی اللہ عنہ سے عمال کے بارے میں ایک حدیث روایت کی ہے وہ مسلم و ابو داود اور چار صحابہ ہیں۔ نیز ان سے ان کے بیٹے ابو سفیان اور ابو حق، عبد اللہ بن بریدہ وغیرہ روایت کرتے ہیں۔ واقدی فرماتے ہیں: ہمیں عبد الرحمن بن عبد اللہ بن ابی بکر بن حزم کے حوالہ سے بتایا کہ حویطب فرماتے تھے: میں صلح حدیبیہ سے پہلا اور مجھے یقین تھا کہ محمد (صلی اللہ علیہ وسلم) غالب رہیں گے۔ پھر لباس قصہ ذکر کیا۔ ابن سعد طبقات میں منذر بن جہم وغیرہ کے طریق سے بحوالہ حویطب روایت کرتے ہیں، فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم مکہ میں داخل ہوئے تو مجھے سخت خوف دامن گیر ہوا پھر طویل قصہ ذکر کیا۔ اور اپنے اہل خانہ کو ایک محفوظ مقام میں پہنچا کر خود عوف کے باغ میں چھپا۔ انھتے میں ابو زر سے ملے ان سے پہلے سے شناسائی تھی و جان پہچان ہمیشہ فائدہ دیتی ہے۔ میں نے انہیں سلام کیا اور ان سے ساری بات ذکر کی۔ وہ کہنے لگے: اپنے گھر والوں کو لے آؤ تمہیں امن ہے۔ انہوں نے جا کر رسول اللہ صلی اللہ علیہ وسلم کو اطلاع دی جس سے مجھے کافی اطمینان ہو گیا۔ پھر ابو زر مجھ سے کہنے لگے: ابو محمد! کب تک ایسے رہو گے، تم سے کئی بھلائی کے کام رہ گئے جبکہ رسول اللہ صلی اللہ علیہ وسلم تمام لوگوں سے بڑھ کر اچھا برتاؤ کرنے والے ہیں۔ سب سے بردبار ہیں۔ ان کی شرافت و عزت تمہاری شرافت و عزت ہو گی۔ میں نے کہا: میں تمہارے ساتھ جاتا ہوں۔ وہ کہنے لگے: یاد رکھنا! جو بھی نبی صلی اللہ علیہ وسلم پر نظر پڑے تو کہنا: السلام علیک ایھا النبی و رحمۃ اللہ۔ چنانچہ میں نے یہ کلمات کہے، آپ نے فرمایا: وعلیک السلام۔ پھر میں نے شہادتین پڑھیں جس سے آپ صلی اللہ علیہ وسلم کو بڑی مسرت ہوئی۔ فرمانے لگے: \"اللہ کا شکر ہے جس نے تمہیں ہدایت سے نوازا\"۔ فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے مجھ سے قرض مال لیا تو میں نے آپ صلی اللہ علیہ وسلم کو چالیس ہزار قرض دیا۔ اور آپ صلی اللہ علیہ وسلم کے ساتھ حنین میں شریک ہوا۔ وہاں سے مجھے غنیمت میں سے حصہ دیا۔ اس کے بعد حویطب مدینہ آگئے اور وفات تک وہیں رہائش پذیر رہے اور اپنے مکہ والے گھر کو امیر معاویہ رضی اللہ عنہ کے ہاتھوں ہزار دینار میں فروخت کر دیا۔ جنہیں بعض لوگوں نے بہت زیادہ سمجھا۔ تو حویطب بولے: جس کے پانچ عیال ہوں اس کے لیے کچھ بھی نہیں۔ عبد الرزاق، ابو حق کے طریق سے بحوالہ حویطب روایت کرتے ہیں: ایک مالکن عورت اپنی باندی کو کھینچ رہی تھی، اس نے اسے کہا: تجھ سے بیت اللہ کی پناہ! تو اس کا ہاتھ شل ہو گیا۔ اسلام کا ظہور ہوا تو اس کا ہاتھ اسی طرح شل تھا۔ طبرانی دوسری سند سے ابن ابی شیخ کے طریق سے وہ اپنے والد سے وہ حویطب سے روایت کرتے ہیں، لیکن اس میں ہے کہ پناہ مانگنے والی عورت تھی اور کھینچنے والا اس کا خاوند تھا۔","",{"fn":"(1) اسد الغابۃ (۱۳۱۱) تجرید (۱۴۶/۱)\n(2) التاریخ الکبیر (۱۲۲/۱)\n(3) الطبقات (۳۲۵/۵)"}],[1884,"§۱۸۸۵ ۔ حیّان بن ابجر الکنانی(1)\nبقول طبری کہا جاتا ہے کہ صحابی ہیں۔ ابن مندہ بطریق عبد اللہ بن جبلہ بن حیّان بن ابجر، وہ اپنے والد سے وہ اپنے دادا حیّان سے روایت کرتے ہیں کہ ہم لوگ نبی صلی اللہ علیہ وسلم کے ساتھ تھے، ایک جگہ پڑاؤ کے دوران میں ہانڈی جس میں مردار کا گوشت تھا آگ جلا رہا تھا۔ اتنے میں مردار کی حرمت کا حکم نازل ہو گیا تو میں نے (بھری) ہنڈیا انڈیل دی۔ ابو احمد حاکم ایک دوسرے طریق سے جو عبد اللہ بن سعید بن حیّان بن ابجر تک منسوب ہوتا ہے، روایت کرتے ہیں کہ حیّان بن ابجر صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ شریک تھے۔ آپ نے ان کی کنیت ابو القصر رکھی۔(2)","",{"fn":"(1) جامع المسانید (۶۲۱/۳)\n(2) تجرید (۱۴۵/۱)"}],[1885,"§۱۸۸۶ ۔ حیّان بن بُج(1)\nجبان میں ذکر گزرا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۳۱۸)"}],[1886,"§۱۸۸۷ ۔ حیّان بن قیس\nبقول بعض نابغہ جدی کا نام ہے۔"],[1887,"§۱۸۸۸ ۔ (ز) حیّان بن کرز بلوی\nفتح مصر میں شریک تھے، بقول ابو یونس صحابی ہیں۔"],[1888,"§۱۸۸۹ ۔ حیّان بن ملّہ (انیف بن ملّہ کے بھائی)\nبقول بعض ان کا نام حسان یسین سے ہے۔ امام بخاری(1) فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ ابن اسحاق فرماتے ہیں: مجھے جذام کے ایک عالم نے بتایا جس پر مجھے کسی غلط بیانی کی تہمت (کا خدشہ) نہیں کہ حیّان، دحیہ کلبی کے ساتھ تھے جب وہ قاصد بن کر قیصر روم کی جانب روانہ ہوئے تھے۔ انہوں نے انہیں سورۃ فاتحہ سکھائی۔ ان کا تذکرہ ان کے بھائی انیف کے سوانح میں گزر چکا ہے۔ نیز حکیم بن امیر اور سعید والد ضمرہ کے حالات میں ان کا تذکرہ آئے گا۔","",{"fn":"(1) التاریخ الکبیر (۵۳/۱)"}],[1889,"§۱۸۹۰ ۔ حیّان بن نملہ انصاری(1)\nابو عمران۔ ابن مندہ فرماتے ہیں: امام بخاری(2) نے ان کا ذکر کیا ہے۔ ان کے صحابی ہونے میں تامل ہے۔ حسن بن سفیان، بخوی اور طبرانی نے بطریق حمید بن علی، عمران بن حیّان سے وہ اپنے والد سے روایت کرتے ہیں کہ انہوں نے نبی صلی اللہ علیہ وسلم کو خمیر میں دیکھا کہ آپ صلی اللہ علیہ وسلم لوگوں کو غنیمت کی تقسیم سے پہلے کسی چیز کی فرختگی سے منع کر رہے تھے۔ لمبی حدیث ہے طبرانی نے یہ روایت لکھی ہے۔ ابن اسکن ان سے روایت کرتے ہیں کہ آپ نے قبروں کی زیارت سے روکا تھا۔ میں نے نہیں دیکھا کہ کسی نے ان کے والد کا نام نملہ سوائے ابن مندہ کے بتایا ہو۔ رہے دیگر حضرات انہوں نے تو حیّان انصاری کہا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۳۱۹) استیعاب (۵۸۴) تجرید (۱۴۶/۱)\n(2) بخاری کتاب الرقاق (۶۰۵۷) ترمذی کتاب التفسیر سورۃ عبس (۳۳۲۲)"}],[1890,"§۱۸۹۱ ۔ (ز) حیّان بن وہب\nبقول بعض ابو رمثہ کا نام ہے۔"],[1891,"§۱۸۹۲ ۔ (ز) حیّان (بے نسبت، دوسرے)\nابن مندہ بطریق عبد الملک بن ابجر، حیّان سے روایت کرتے ہیں، فرمایا: \"میرے والد مجھے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں لے گئے۔ آپ بیت اللہ کے صحن میں تشریف فرما تھے، آپ کے پے نماں ل تھے جن پر مہندی کی رنگت چڑھی ہوئی تھی\"۔ یہ روایت انہوں نے حیّان بن ابجر کے حالات میں درج کی ہے، میرے خیال میں وہ اور ہیں۔"],[1892,"§۱۸۹۳ ۔ حیّان\nمولیٰ قریش۔ ابن اسکن نے ان کا تذکرہ کیا کہ ان کا شمار اہل مدینہ میں ہوتا ہے۔ اور عبد اللہ بن محمد بن علی نفیلی کے طریق سے بحوالہ یحییٰ بن عبد اللہ بن انیس، عیسیٰ بن سمرہ بن حیّان مولیٰ قریش، وہ اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں، فرمایا: نبی صلی اللہ علیہ وسلم منبر پر چڑھ کر فرمانے لگے: \"لوگو! سنو! جب تک وضو نہیں ہو گا نماز نہیں ہو گی اور اس شخص کا وضو (کامل) نہیں جس نے بسم اللہ نہیں پڑھی\"۔(1) میں کہتا ہوں: ہمیں ان کی یہ حدیث ابن مندہ کی کتاب \"المعرفۃ\" میں عالی سند سے پہنچی ہے لیکن اس میں ان کا نام مذکور نہیں۔ البتہ کنیتوں میں ان کا ذکر کیا ہے۔ چنانچہ فرماتے ہیں: ابو ہرہ، اور حدیث ابو جعفر عقیلی کے طریق سے بیان کی ہے۔ ایسا ہی ابراہیم نے بحوالہ طبرانی دوسری سند سے نقل کیا ہے۔ دونوں بطریق نفیلی بیان کرتے ہیں۔ جبکہ ابو کندہ سنیو میں ہم نے اسی طرح روایت کی ہے۔ جہاں تک مجھے معلوم پڑتا ہے ان کا نام صرف ابن مندہ کی اس روایت میں لیا گیا ہے۔","",{"fn":"(1) ابوداؤد کتاب الطہارۃ باب فی التسمیۃ علی الوضوء (۱۰۱) ترمذی ابواب الطہارۃ (۲۵) ابن ماجہ کتاب الطہارۃ (۳۹۹)"}],[1893,"§۱۸۹۴ ۔ حیّان ربعی\nان کا ذکر ان کے بیٹے دینار بن حیّان کے سوانح میں آئے گا۔"],[1894,"§۱۸۹۵ ۔ حَیدہ بن مُعَرّم(1)\nبن خمرہ بن قرط بن جناب بن حارث بن محمد بن عدی بن جندب بن عمیر بن عمرو بن تمیم تیمی، وردان کے بھائی۔ ہشام کلبی فرماتے ہیں: دونوں بھائی نبی صلی اللہ علیہ وسلم کی خدمت میں آ کر مسلمان ہوئے۔ لیکن ان دونوں کا ذکر طبری اور ابن ماکولا(2) نے کیا ہے ان شاء اللہ تعالیٰ حرف عین میں عبیدہ بن قرط ظبری کے حالات میں ان کا تذکرہ ہو گا کہ نبی صلی اللہ علیہ وسلم نے ان کے لئے خیر و برکت کی دعا فرمائی تھی۔","",{"fn":"(1) اسد الغابۃ (۱۳۲۰)\n(2) الاکمال (۵۷۶/۲)"}],[1895,"§۱۸۹۶ ۔ حیدہ بن معاویہ\nبن قشیر بن کعب بن ربیعہ بن عامر بن صعصعہ عامری ثم قشیری، انہیں اور ان کے بیٹے معاویہ بن حیدہ کو شرف صحابیت حاصل ہے۔ بلاذری ان کا ذکر کرنے کے بعد لکھتے ہیں: ثابت نہیں۔ ہشام بن کلبی کا قول ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی بارگاہ میں آئے۔ ہشام فرماتے ہیں: مجھے میرے والد نے بتایا کہ میں نے خراسان میں انہیں دیکھا تھا وہ فقیہ، بہز بن حکیم کے دادا ہوتے ہیں۔ ابو حاتم عجمانی نے معمر بن میں ان کا ذکر کر کے لکھا ہے: \"انہوں نے دور جاہلیت دیکھا ہے اور عراق پر بشر کی عسکرانی تک زندہ رہے جب ان کی وفات ہوئی تو وہ ہزار مردوں اور عورتوں کے چچا تھے\"۔ باوردی اور بیہقی نے \"دلائل\" میں داؤد بن ابی ہند کے طریق سے بحوالہ بہز بن حکیم وہ اپنے والد سے وہ اپنے دادا حیدہ بن معاویہ سے روایت کرتے ہیں کہ زمانہ جاہلیت میں وہ عمرہ کرنے روانہ ہوئے۔ مکہ میں بیت اللہ کا طواف کرتے ایک بوڑھا نظر آیا جو یہ اشعار پڑھ رہا تھا: \"اے میرے رب! میرے سوار محد کو لوٹا دے۔ میرے رب! اسے لوٹا کر مجھ پر احسان فرما\"۔ میں نے لوگوں سے کہا: یہ بوڑھا کون ہے؟ لوگوں نے جواب دیا: یہ قریش کے بزرگ ہیں۔ جن کا نام عبد المطلب ہے میں نے پوچھا محمد (صلی اللہ علیہ وسلم) ان کا کیا لگتا ہے؟ انہوں نے بتایا: پوتا۔ جو انکیس سے زیادہ چہیتا و محبوب ہے۔ فرماتے ہیں: تھوڑی ہی دیر گزری تھی کہ وہ آ گئے۔ اسی سے ملتا جلتا قصہ سعید والد کندیر نے بیان کیا ہے۔ ابراہیم بن طریق، بہز بن حکیم سے وہ اپنے والد حکیم سے وہ اپنے والد معاویہ سے روایت کرتے ہیں کہ ان کے والد حیدہ کے چھوٹے بیٹے تھے۔ جبکہ وہ بے حد مالدار، جسے انہوں نے ایک بیوی کی اولاد کے لئے مخصوص کر دیا۔ تو ان کے بیٹے معاویہ سیدنا عثمان رضی اللہ عنہ کے پاس آ کر سارا واقعہ بیان کرنے لگے۔ سیدنا عثمان رضی اللہ عنہ نے چیز بزرگ کو یہ اختیار دیا کہ یا تو وہ اپنا مال واپس لے لے یا اپنے بیٹوں میں تقسیم کر دے۔ چنانچہ انہوں نے اپنا مال واپس لے لیا۔ جب ان کی وفات ہوئی تو بڑوں نے اپنے چھوٹے بھائیوں کے لیے وہ مال استعمال کرنا چھوڑ دیا۔ امام بہز فرماتے ہیں: حیدہ لمبا عرصہ زندہ رہے یہاں تک کہ انہوں نے اسد بن عبد اللہ قسری کا دور دیکھا جب وہ خراسان میں اپنے بھائی خالد بن عبد اللہ تشیری کی جانب سے گورنر مقرر تھا۔"],[1896,"§۱۸۹۷ ۔ حیدہ (بے نسبت)(1)\nابن اسکن، اسماعیلی اور ابن مندہ طلق بن حبیب کے طریق سے روایت کرتے ہیں کہ انہوں نے حیدہ کو فرماتے سنا کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سنا ہے: \"تمہیں قیامت کے روز ننگے پیر ننگے بدن اور بے ختنہ اٹھایا جائے گا، سب سے پہلے ابراہیم علیہ السلام کو پوشاک پہنائی جائے گی\"۔(2) (حدیث) ابن اسکن فرماتے ہیں: شاید یہ معاویہ بن حیدہ یعنی پہلے والے کے والد ہوں۔ میں کہتا ہوں: میرے گمان میں طلق اور حیدہ کا درمیانی واسطہ چھوٹ گیا ہے۔ اس واسطے کہ روایت معاویہ بن حیدہ سے معروف ہے جسے ان سے ان کا بیٹا حکیم بن معاویہ، بہز بن حکیم بحوالہ اپنے والد کی روایت سے نقل کرتا اور بہز بن حکیم کی روایت کے بغیر بھی مروی ہے۔ واللہ اعلم","",{"fn":"(1) حاکم فی المستدرک (۲۵۱/۲) جامع المسانید (۶۲۷/۳)\n(2) دلائل النبوۃ (۲۸۱/۶)"}],[1897,"§۱۸۹۸ ۔ (ز) حیر نجرہ اسرائیلی(1)\nپہلے یہودی تھے پھر مسلمان ہو گئے۔ حاکم، ابو سعید نے \"شرف المصطفیٰ\" میں اور بیہقی نے \"دلائل\" میں ابو علی بن اشعث(2) کے طریق سے (جو ایک ضعیف راوی ہے) اپنی سند سے نقل کیا ہے کہ سیدنا علی رضی اللہ عنہ سے مروی ہے کہ حیر نجرہ نامی ایک یہودی تھا جس کے نبی صلی اللہ علیہ وسلم کے ذمہ چند دانیر تھے جن کا اس نے آپ صلی اللہ علیہ وسلم سے تقاضا کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس تمہیں دینے کے لیے کچھ نہیں\"۔ وہ بولا: تب تو میں دانیر لیے بغیر یہاں سے نہ لوں گا اور حجرہ آپ صلی اللہ علیہ وسلم کے پاس بیٹھ گیا۔ آپ صلی اللہ علیہ وسلم کے صحابہ اسے ملامت کرنے لگے جس پر آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے نبی پر ظلم کرنے سے منع کیا گیا ہے\"۔ جب آفتاب بلند ہوا تو وہ یہودی اسلام لے آیا اور اپنا وہ مال اللہ تعالیٰ کی راہ میں صدقہ کر دیا۔ پھر نبی صلی اللہ علیہ وسلم کی سیرت میں لمبی حدیث ذکر کی۔ بعض نسخوں میں مجھے یہ نام حجرہ دو وجہوں سے تصغیر کی صورت لکھا نظر آیا ہے۔ بہر حال یہاں قابل اعتماد ہے۔ اس واسطے کہ میں نے حافظ زکی الدین برزالی کے قلم سے تاریخ ابن عساکر میں تجرید سے لکھا دیکھا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۳۲۱)\n(2) اسد الغابۃ (۷۴/۱)"}],[1898,"§۱۸۹۹ ۔ حَیثمان(1)\nابن ایاس بن عبد اللہ بن ایاس بن ضبیعہ بن عمرو بن رمان بن عبدی بن عمرو بن ربیعہ خزاعی۔ ابن کلبی نے \"نسب\" میں اور ابن سعد نے \"طبقات\" میں ان کا ذکر کیا ہے۔ طبری کی کتاب میں حیثمان بن عبد اللہ بن ایاس تحریر ہے جو انہوں نے عبد اللہ کے اضافہ کے ساتھ ابن اسحاق سے نقل کیا ہے اور نسب بھی اسی اضافہ سمیت بیان کیا ہے اور واقدی سے حاسا کا اضافہ حیثمان اور عبد اللہ کے مابین ہے۔ یوں ابن کلبی کے نسب میں دو شخصیتوں کا اضافہ کیا جبکہ باقی ان کے موافق ہے۔ موسیٰ بن عقبہ واقعہ بدر میں لکھتے ہیں: بدر کے روز سب سے پہلے جس کی خوشخبری سنی گئی کہ مشرکین شکست کھا چکے ہیں، وہ حیثمان تھے جو حسن بن فیلان کے دادا ہیں۔ ابن شاہین فرماتے ہیں: اپنی قوم میں صاحب شرافت شخص تھے بعد میں اسلام لے آئے اور ان کا خوب سنورا۔ ابو عبیدہ بن سلام اور طبرانی فرماتے ہیں کہ وہ پہلے شخص ہیں جو قریش مکہ (مشرکین) کے بدر میں مارے جانے کی خبر لائے۔ ابن کلبی کا قول ہے صاحب شرافت انسان تھے۔(2)","",{"fn":"(1) اسد الغابۃ (۱۳۲۴) استیعاب (۵۹۶)\n(2) استیعاب (۱۹۵)"}],[1899,"§۱۹۰۰ ۔ (ز) حی بن ثعلبہ بن ھون\nبثینہ کے والد جس کے بارے میں جمیل غزلیں کہا کرتا تھا، ابوالفرج اصبہانی کا قول ہے انہیں شرف صحابیت حاصل ہے جسے میں نے مغلطائی کے قلم سے نقل کیا ہے۔"],[1900,"§۱۹۰۱ ۔ حیی بن حرام لیثی(1)\nابن یونس نے تاریخ مصر میں ذکر کیا ہے کہ یہ صحابی ہیں۔ ابن السکن فرماتے ہیں: شرف صحابیت رکھتے ہیں اور مصری صحابہ میں شمار ہوتے ہیں۔ جبکہ ان کی حدیث میں تامل ہے۔ پھر بطریق ابن لہیعہ، ابو تمیم حیثمانی سے نقل کیا ہے، فرماتے ہیں: \"حیی لیثی صحابی رسول صلی اللہ علیہ وسلم تھے۔ ان کی عادت تھی کہ جب سورج ڈھل جاتا تو اپنے گھر میں ظہر کی نماز پڑھ کر چل نکلتے مسجد میں آتے ظہر کی نماز مل جاتی تو ان کے ساتھ بیت نفل (پڑھ لیتے)\"۔ خطط میں قضاعی لکھتے ہیں: لوگوں کا کہنا ہے کہ شرف صحابیت رکھتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۳۲۴) استیعاب (۵۹۶)"}],[1901,"§۱۹۰۲ ۔ (ز) حارث بن ثابت\nبن ثعلبہ بن زید انصاری ابن الجذع ع (جو ثعلبہ کا لقب تھا اس) سے مشہور ہیں۔ بقول ابن سعد ثابت جنگ طائف میں شہید ہوئے۔ اور حارث، عبداللہ، ام ایاس اولادیں چھوڑیں۔"],[1902,"§۱۹۰۳ ۔ (ز) حارث بن حمیر\nان کا تذکرہ ان کی والدہ معاذہ کے حالات میں آئے گا۔"],[1903,"§۱۹۰۴ ۔ حارث بن عباس\nبن عبدالمطلب ہاشمی۔ نبی صلی اللہ علیہ وسلم کے چچا زاد بھائی۔ سیدنا عباس رضی اللہ عنہ کی اولاد میں شمار ہوتے ہیں۔ ابو عمر(1) فرماتے ہیں کہ عباس رضی اللہ عنہ کے تمام بیٹوں کو دیدار نصیب ہے۔ جن میں سے صحابی صرف فضل اور عبداللہ ہیں۔ ان کی والدہ بجیلہ بنت جندب بن ربیعہ ہلالیہ ہیں۔ بقول بعض ام ولد تھیں۔ یہ بھی کہا جاتا ہے کہ ان کے والد ان سے ناراض ہوئے تو انہیں گھر سے نکال دیا۔ یہ زبیر کے پاس چلے گئے۔ انہوں نے آ کر اپنے ماموں عباس سے سفارش کی۔ ہشام بن کلبی اور ہیثم بن عدی فرماتے ہیں: عباس نے انہیں شام کی جانب نکال دیا تو وہ مصر میں زبیر رضی اللہ عنہ کے پاس جا ٹھہرے۔ اور بعد میں جب زبیر انہیں لے کر عباس کے پاس پہنچے، کہنے لگے: تم میرے پاس ابو عقل کو لے آئے تمہیں رشتہ داری نصیب نہ ہو۔ کچھ لوگوں کا کہنا ہے کہ عباس رضی اللہ عنہ کی وفات کے بعد وہ نابینا ہو گئے تھے۔","",{"fn":"(1) استیعاب (۱۹۵)"}],[1904,"§۱۹۰۵ ۔ حارث بن طفیل(1)\nبن کثیرہ سیدہ عائشہ رضی اللہ عنہا کے رضاعی بھتیجے۔ ان کے والد کے تذکرہ میں ان کا حال بیان ہوگا۔ جمہور نے انہیں تابعین میں جبکہ ابن عبدالبر(2) نے صحابہ میں ذکر کیا ہے، انہیں دیدار حاصل ہے۔","",{"fn":"(1) اسد الغابۃ (۹۰۷) استیعاب (۴۱۶)\n(2) استیعاب (۲۵۴/۱)"}],[1905,"§۱۹۰۶ ۔ حارث بن عبیدہ\nبن حارث بن مطلب بن عبد مناف مطلبی، ان کے والد جنگ بدر میں شہید ہوئے۔ بلاذری نے ان حارث کا ذکر عبیدہ کی اولاد میں کیا ہے اور کہا ہے: ان کی پیچھے اولاد نہیں رہی۔"],[1906,"§۱۹۰۷ ۔ حارث بن عمر ھذلی(1)\nواقدی کا بیان ہے۔ عہد نبوی میں پیدا ہوئے۔ ابن حبان(2) کا قول ہے: حارث بن عمرو، ان کے متعلق کہا جاتا ہے کہ عہد نبوی میں پیدا ہوئے، اور ان کا ذکر تابعین میں کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۳۳) استیعاب (۴۴۲)\n(2) الثقات (۱۸۱/۸)"}],[1907,"§۱۹۰۸ ۔ (ز) حازم بن عیسیٰ\nعبدالرحمن بن عیسیٰ میں ذکر ہوگا۔"],[1908,"§۱۹۰۹ ۔ حجاج بن ایمن بن عبید\nام ایمن ان کی دادی ہیں جو نبی صلی اللہ علیہ وسلم کی خادمہ تھیں، ایمن جنگ حنین میں شہید ہوئے۔ یوں ان کے بیٹے حجاج کو دیدار نصیب ہوا ہوگا۔ ابن حبان(1) نے تابعین میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان سے اسامہ کے مولیٰ حرملہ روایت کرتے ہیں۔ بخاری میں بطریق حرملہ مروی ہے، فرمایا: حجاج بن ایمن مسجد میں آئے۔ جو اسامہ بن زید کے ماں شریک بھائی تھے۔ انہوں نے نماز پڑھی، سیدنا عمر رضی اللہ عنہ نے دیکھ لیا تو فرمایا: نماز دہراؤ۔","",{"fn":"(1) الثقات (۲۰۵/۶)"}],[1909,"§۱۹۱۰ ۔ حصین بن ام حصین احمسیہ(1)\nابن مندہ فرماتے ہیں: انہیں دیدار حاصل ہے۔ طبرانی(2) بطریق زہیر بن معاویہ، ابو اسحاق سے وہ یحییٰ بن حصین سے وہ اپنی دادی ام حصین سے روایت کرتے ہیں، فرماتی ہیں: میں نے نبی صلی اللہ علیہ وسلم کو حجۃ الوداع کے موقع پر سواری پر سوار دیکھا جبکہ حصین میری گود میں تھا۔ ابو نعیم فرماتے ہیں: اسے ایک جماعت نے ابو اسحاق سے روایت کیا ہے۔ کسی نے بھی یہ نہیں کہا: \"حصین میری گود میں تھا\"۔ صرف زہیر بن معاویہ ان کا نام لینے میں متفرد ہیں۔ ابو عمر کا گمان ہے کہ وہ حصین بن ربیعہ ابو ارطاۃ ہیں جبکہ یہ غلط ہے اس واسطے کہ حصین بن ربیعہ کو تو جریر رضی اللہ عنہ نے ذوالخلصہ کی فتح کا قاصد بنا کر نبی صلی اللہ علیہ وسلم کی خدمت میں بھیجا تھا۔ وہ بھلا حجۃ الوداع کے موقع پر اتنے چھوٹے کیسے ہو سکتے ہیں کہ اپنی والدہ کی گود میں ہوں۔ ابن الاثیر(3) نے ابن عبدالبر کے قول کو راجح قرار دیا ہے کہ \"یہ اضافہ زہیر بن معاویہ نقل کرنے میں متفرد ہے\"۔ درست دونوں میں فرق ہی ہے۔","",{"fn":"(1) اسد الغابۃ (۱۱۸۱)\n(2) المعجم الکبیر (۳۷۸/۲۵)\n(3) اسد الغابۃ (۲۷/۱)"}],[1910,"§۱۹۱۱ ۔ حکیم بن قیس(1)\nبن عاصم تمیمی۔ ابن مندہ نے ذکر کیا ہے کہ انہیں دیدار حاصل ہے۔ ابو نعیم فرماتے ہیں: بقول بعض وہ نبی صلی اللہ علیہ وسلم کے عہد میں پیدا ہوئے۔ میں کہتا ہوں: ان کی بحوالہ اپنے والد امام بخاری رحمہ اللہ کی کتاب الادب المفرد اور سنن نسائی میں ایک روایت، مطرف بن عبداللہ بن شیخیر کی روایت سے ان سے مروی ہے۔ ابن حبان(2) نے ثقات التابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۲۳۷)\n(2) الثقات (۱۶۰/۴)"}],[1911,"§۱۹۱۲ ۔ جماس بن عمرو(1)\nابو عمرو بن حماس لیثی کے والد واقدی کا بیان ہے کہ وہ عہد نبوی میں پیدا ہوئے۔ ہم نے حسن بن عفان کے جزو میں یحییٰ بن سعید کے طریق سے بحوالہ عبداللہ بن ابی سلمہ، ابو عمرو بن حماس سے روایت کی ہے، فرمایا: سیدنا عمر رضی اللہ عنہ نے حماس سے فرمایا: (اور وہ ترکش اور چڑا بیچا کرتے تھے) اپنے مال کی زکوٰۃ ادا کرو۔ یہ حدیث موقوف ہے۔ میں کہتا ہوں: یہ ان حماس دیلی کے علاوہ ہیں جن کا ذکر قسم اول میں گزر چکا ہے۔ ان کے متعلق واقدی کا قول ہے کہ وہ فتح مکہ میں شریک تھے۔","",{"fn":"(1) اسد الغابۃ (۱۲۴۴) استیعاب (۶۰۴)"}],[1912,"§۱۹۱۳ ۔ حمزہ بن ابی اسید ساعدی(1)\nعہد نبوی میں پیدا ہوئے، ان کی ایک مرسل روایت ہے اپنے والد سے حدیث نقل کرتے ہیں، ان سے زہری اور عبدالرحمن بن سلیمان بن غسیل وغیرہ روایت کرتے ہیں۔ ولید بن عبدالملک کے زمانے میں پیدا ہوئے۔ ان کی کنیت ابو مالک تھی۔ ابن حبان(2) نے ثقات التابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۱۳۹/۱)\n(2) الثقات (۱۶۸/۴)"}],[1913,"§۱۹۱۴ ۔ (ز) حمزہ انصاری (بے نسبت)\nان کا ذکر اس حدیث میں آیا ہے جسے ہم نے محمد بن مخلد کے جزو میں عمرو بن دینار کے طریق سے، انصار کے ایک شخص سے انہوں نے اپنے والد سے روایت کی ہے، فرمایا: میرے ہاں ایک لڑکے کی ولادت ہوئی، میں اسے نبی صلی اللہ علیہ وسلم کے پاس لایا، میں نے عرض کی: میں اس کا کیا نام رکھوں؟ فرمایا: اس شخص کے نام پر اس کا نام رکھو جو مجھے تمام لوگوں سے زیادہ محبوب ہے: حمزہ۔ حاکم(1) نے اسے \"اکلیل\" میں اور مستدرک میں دوسری سند سے عمرو بن دینار سے اسی مفہوم میں مروی ہے۔ ایک اور طریق سے روایت کر کے فرمایا: عمرو بن دینار، جابر سے روایت کرتے ہیں۔ جبکہ پہلا طریق درست ہے۔ حدیث جابر میں انصاری کے بیٹے کا نام عبدالرحمن بتایا گیا ہے جو اس قصہ کے علاوہ ہے۔","",{"fn":"(1) المستدرک (۱۹۶/۳) کنز العمال (۴۵۲۳۱) تاریخ بغداد (۷۳/۲)"}],[1914,"§۱۹۱۵ ۔ حمید بن عمرو\nبن سائق بن قیس بن بدم بن رواحہ بن حجر بن عبد بن معیص بن عامر بن لوی قرشی عامری یہی حمید ابن درہ ہیں۔ دراصل درہ ان کی والدہ کا نام ہے جو ہاشم بن عتبہ بن ربیعہ کی بیٹی ہیں۔ زبیر بن بکار نے ان کا نسب بیان کیا ہے۔ ایک مرتبہ یوں بیان کیا: حمید بن عمیر۔ یہ بھی ذکر کیا ہے کہ وہ امیر معاویہ کے ایام میں شام میں صاحب شرف آدمی تھے۔ میں کہتا ہوں: میں نے ان کے والد کا صحابہ میں کہیں بھی تذکرہ نہیں دیکھا، لگتا ہے وہ فتح مکہ سے پہلے حالت شرک میں ہی فوت ہو گئے تھے۔ البتہ ان کے اس بیٹے کو دیدار حاصل ہے۔"],[1915,"§۱۹۱۶ ۔ حنظلہ بن قیس\nبن عمرو بن حصین بن خلدہ انصاری زرقی۔ واقدی کا بیان ہے کہ وہ عہد نبوی میں پیدا ہوئے۔ سیدنا عمر، عثمان وغیرہ صحابہ سے روایت کرتے ہیں۔ جبکہ ان سے زہری، ربیعہ، یحییٰ بن سعید وغیرہ حضرات روایت کرتے ہیں۔ واقدی بحوالہ زہری روایت کرتے ہیں، فرمایا: مجھے انصار میں سے حنظلہ بن قیس سے بڑھ کر زیادہ محتاط اور درست رائے والا آدمی نظر نہیں آیا ہے۔ بحوالہ واقدی ابن سعد کا قول ہے: وہ ثقہ اور کم حدیث والے تھے۔ ابن حبان(1) نے ثقات التابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الثقات (۱۶۶/۴)"}],[1916,"§۱۹۱۷ ۔ (ز) حارث بن ازمع ہمدانی(1)\nابن عبدالبر(2) کا قول ہے کہ صحابہ میں ان کا ذکر ملتا ہے، امیر معاویہ کی خلافت کے آخری دور میں فوت ہوئے۔ یہی ان کے متعلق منقول ہے۔ ذیل میں ابو موسیٰ لکھتے ہیں: ابن شاہین اور عبدان نے ان کا صحابہ میں ذکر کیا ہے۔ البتہ ابن شاہین یہ بھی فرماتے ہیں: تابعی ہیں جنہوں نے دور جاہلیت پایا ہے۔ سیدنا عمر رضی اللہ عنہ سے روایت کرتے ہیں۔ میں کہتا ہوں: ابن سعد(3) نے ان کا یوں نسب بیان کیا ہے: حارث بن ازمع بن ابی بثینہ بن عبداللہ بن مر بن مالک بن حرب بن حارث بن سعد بن عبداللہ بن وداعہ۔ انہیں اہل کوفہ کے پہلے طبقہ کے تابعین میں ذکر کیا ہے۔ فرماتے ہیں: امیر معاویہ کے آخری دور میں فوت ہوئے۔ امام بخاری، ابن ابی حاتم(4)، مسلم(5)، ابن حبان(6) اور خلیفہ بن خیاط نے تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۴۱) استیعاب (۳۹۹)\n(2) استیعاب (۳۴۸/۱)\n(3) الطبقات (۸۱/۶)\n(4) التاریخ الکبیر (۲۶۴/۲)\n(5) الجرح والتعدیل (۶۹/۳)\n(6) الثقات (۱۲۶/۴)"}],[1917,"§۱۹۱۸ ۔ (ز) حارث بن زہیر\nبن عبدالشارق بن لغط بن مطر بن عامر بن کثیرہ بن دئل ازدی۔ بقول ابن کلبی: صاحب شرافت تھے، جنگ جمل میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ عمرو بن اشرف سے سامنا ہوا تو ہر ایک نے دوسرے کو قتل کر دیا۔"],[1918,"§۱۹۱۹ ۔ (ز) حارث بن ربیعہ\nبن زین بن عوف بن عامر بن ذبل بن ثعلبہ ذیلی۔ ایک بند کہنے کی وجہ سے ان کا نام ملح بطور لقب پڑ گیا۔ مرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے کہ وہ محضرمی ہیں، فتوحات میں شریک رہے۔"],[1919,"§۱۹۲۰ ۔ (ز) حارث بن سعد\nبن ابی ذباب دوسی۔ سیدنا ابو ہریرہ رضی اللہ عنہ کے چچا زاد بھائی۔ ابن حبان نے ثقات التابعین میں ان کا ذکر کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے انہیں زکوٰۃ کی وصولی کے لئے بھیجا تھا، ان سے یزید بن ہرمز روایت کرتے ہیں۔"],[1920,"§۱۹۲۱ ۔ (ز) حارث بن سلمیٰ\nبن رواس بن دالان بن صعب بن حارث بن مذہب ہمدانی ثم مرہبی۔ ابن کلبی کا بیان ہے کہ قادسیہ میں شریک ہوئے، وہی یہ اشعار کہتے ہیں: آگے بڑھ مجھے ان کے متعلق کنگنوں کے بارے میں خوف ہے کبھی کبھار دکھائی دینے والے سروں سے نہ گھبرا، تیری مدد تو میدان کی موت نے کر دی، جس کے بعد تو لوٹ جائے گا۔ اس مفہوم کے اشعار بنی قشیر کے کسی آدمی سے بھی منقول ہیں، ان میں ہے: \"اس کے بعد جب میں بوسیدہ ہڈیاں ہو جاؤں گا۔ میں قشیری (ہی رہوں گا) جو مہاجرین کا بھائی ہوں\"۔ اس میں ہے کہ وہ یرموک کا موقع تھا۔ اساورہ انہوں نے رومیوں کو کہا۔ ان کا وہم تھا کہ وہ فارسیوں کی طرح ہیں اس واسطے کہ رومیوں کو \"بطارقہ\" کہا جاتا ہے۔"],[1921,"§۱۹۲۲ ۔ حارث بن سوید تمیمی(1)\nابو عائشہ۔ بقول بعض: دور جاہلیت پایا ہے اور کوفہ فروکش ہوئے۔ سیدنا عمر، ابن مسعود اور سیدنا علی رضی اللہ عنہم سے روایت کرتے ہیں جبکہ ان سے ابراہیم تیمی اور اشعث بن ابی شعثاء روایت کرتے ہیں۔ ابن معین فرماتے ہیں: \"ابراہیم تیمی حارث سے وہ سیدنا علی سے\" یہ کوفہ میں ان کی سب سے اچھی سند ہے۔ عبداللہ بن احمد فرماتے ہیں: میرے والد نے ان کا بڑی تعظیم سے ذکر کیا۔ ابن عیینہ فرماتے ہیں: سیدنا ابن مسعود رضی اللہ عنہ کے شاگردوں میں اونچے درجہ کے لوگوں میں شمار ہوتے تھے۔ عبداللہ بن زبیر رضی اللہ عنہ کی خلافت کے آخری دور ۷۲ھ میں فوت ہوئے۔ ایک جماعت ان کی حدیث روایت کرتی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۹۸) استیعاب (۴۴۸)"}],[1922,"§۱۹۲۳ ۔ (ز) حارث بن عبد(1)\nبقول بعض: ابن عبدہ الازدی، ابو مخنف نے اپنی سند سے ذکر کیا ہے کہ وہ یرموک میں شریک ہوئے، فرماتے ہیں: میں لشکر میں تھا۔ ایک رومی مقابلے کے لئے للکارنے لگا: میں مقابلہ کے لیے باہر نکلا، سیدنا خالد بن ولید رضی اللہ عنہ مجھ سے فرمانے لگے، کیا پہلے کسی سے کھلم کھلا مقابلہ کیا ہے؟ میں نے کہا نہیں۔ فرمایا: واپس ہو جاؤ۔ ابن سعد اور خلیفہ نے صحابہ کے بعد پہلے طبقہ میں ان کا ذکر کیا ہے اور خلیفہ نے جنگ صفین میں سیدنا معاویہ رضی اللہ عنہ کے ساتھ شریک لوگوں میں ان کا ذکر کیا ہے۔ وہ فلسطین والوں کی پیادہ فوج کے سالار تھے۔ امیر معاویہ کی خلافت میں فوت ہوئے۔","",{"fn":"(1) اسد الغابۃ (۹۳۹) استیعاب (۴۳۹)"}],[1923,"§۱۹۲۴ ۔ (ز) حارث بن عبد عمرو\nبن معاذ بن یزید بن عمرو بن الضعیق بن نفیل بن عمرو بن کلاب بن ربیعہ بن عامر بن صعصعہ کلابی، زفر بن حارث کے والد، دور جاہلیت پایا ہے۔ نبی صلی اللہ علیہ وسلم کی وفات کے بعد مسلمان ہوئے۔"],[1924,"§۱۹۲۵ ۔ (ز) حارث بن عمیرہ\nحارثی زبیدی۔ نبی صلی اللہ علیہ وسلم کے عہد میں ہی اسلام لے آئے تھے۔ معاذ بن جبل رضی اللہ عنہ کے ساتھ رہنے کا موقع ملا اور انہی کے ساتھ نبی صلی اللہ علیہ وسلم کی وفات کے بعد یمن سے آئے۔ ابن سعد اور یعقوب بن شیبہ بطریق شہر بن حوشب، عبدالرحمن بن غنم ان کے حوالہ سے روایت کرتے ہیں کہ طاعون عمواس میں سیدنا معاذ بن جبل رضی اللہ عنہ کی وفات کے وقت وہ موجود تھے۔ یعقوب نے ان کی حدیث میں یہ اضافہ نقل کیا ہے کہ معاذ یمن سے تشریف لائے تھے۔ پھر لمبی حدیث ذکر کی۔ \"فتوح\" میں سیف بحوالہ داؤد بن ابی ہند سے وہ شہر سے روایت کرتے ہیں کہ جب معاذ بن جبل رضی اللہ عنہ طاعون میں مبتلا ہوئے تو حارث بن عمیرہ زبیدی یمن کے گاؤں \"رہید\" سے آئے، پھر وہ قصہ ذکر کیا۔ شریک، ابو خلف سے بحوالہ حارث بن عمیرہ روایت کرتے ہیں کہ انہوں نے سیدنا معاذ رضی اللہ عنہ کو یمن میں فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"اگر میں کسی کو سجدہ کرنے کا حکم دیتا کہ وہ سجدہ کرے تو عورت کو حکم دیتا کہ وہ اپنے خاوند کو سجدہ کرے\"۔ اسے ابو احمد حاکم(1) نے ذکر کیا ہے۔ ہیثم بن عدی کا قول ہے: انہوں نے یزید بن معاویہ کے دور میں رحلت فرمائی۔","",{"fn":"(1) المستدرک (۱۷۲/۴)"}],[1925,"§۱۹۲۶ ۔ (ز) حارث بن عوف عبدی\nعہد نبوت پایا ہے اور علاء بن حضرمی رضی اللہ عنہ کے ساتھ بحرین میں ربیعہ سے جنگ میں شریک رہے، جس میں ان کے نمایاں کارنامے ہیں بقول بعض: انہوں نے ہی حکم کو مارا تھا۔ ایک قول ہے نہیں بلکہ ان کے بھائی حبیب بن عوف نے اسے قتل کیا تھا، یہ بھی کہا جاتا ہے کہ شماخ نے اسے موت کے گھاٹ اتارا تھا۔"],[1926,"§۱۹۲۷ ۔ (ز) حارث بن قموم بہری\nدور نبوی حاصل ہے سعد بن ابی وقاص کے ساتھ جنگ قادسیہ میں شریک ہوئے۔ سیدنا سعد نے سیدنا عمر رضی اللہ عنہ کے سامنے ان کی شجاعت کی تعریف کرتے ہوئے کہا: میں نے حارث بن قموم جیسا سوار نہیں دیکھا۔ اس نے اپنے اونٹ پر پالان رکھا اور اسے سر تا پا کپڑا اوڑھا دیا، پھر انہیں جدا کر دیا، .... جب کسی سوار کو دیکھتا تو اس پر اتر کر اسے گردن سے دبوچ کر قتل کر دیتا پھر کھڑے کھڑے اپنے اونٹ پر بیٹھ جاتا۔"],[1927,"§۱۹۲۸ ۔ (ز) حارث بن قیس کندی\nدعبل بن علی نے طبقات الشعراء میں ان کا ذکر کیا ہے کہ مخضرمی ہیں اور ان کے قصیدہ نائیہ میں چند اشعار نقل کیے ہیں۔"],[1928,"§۱۹۲۹ ۔ (ز) حارث بن قیس\nابو محمد بن حزم نے طبقات القراء میں ان کا ذکر کیا ہے کہ انہوں نے دور نبوت تو پایا ہے لیکن نبی صلی اللہ علیہ وسلم سے ملاقات نصیب نہیں ہوئی۔"],[1929,"§۱۹۳۰ ۔ حارث بن کعب\nقسم رابع میں ذکر ہوگا۔"],[1930,"§۱۹۳۱ ۔ (ز) حارث بن لقیط نخعی\nحنش بن حارث کے والد، دور نبوت میسر ہے۔ ابن سعد فرماتے ہیں: جنگ قادسیہ میں شریک ہوئے۔ ابن ابی خیثمہ فرماتے ہیں: ہمیں ابو نعیم نے بحوالہ حنش بن حارث بیان کیا ہے کہ وہ فرماتے ہیں میں نے اپنے والد کو ذکر کرتے سنا: جب ہم یمن سے آئے تو ہم نے مدینہ میں پڑاؤ کیا۔ سیدنا عمر بن خطاب رضی اللہ عنہ ہمارے پاس تشریف لائے۔ قبیلہ مجمع میں گھوم پھر کر انہیں دیکھا بھالا۔ (حدیث) امام بخاری نے الادب المفرد میں ان کی ایک روایت نقل کی ہے۔"],[1931,"§۱۹۳۲ ۔ حارث بن مالک طائی(1)\nانہیں دور نبوت نصیب ہوا۔ وثیمہ نے ذکر کیا یہ ان لوگوں میں سے تھے جو فتنہ ارتداد میں دین اسلام پر ثابت قدم رہے۔ اور عدی بن حاتم کے ساتھ اپنی زکوٰۃ صدیق اکبر رضی اللہ عنہ کو ادا کی جس کے متعلق ان کے اشعار ہیں جن کا مطلع یہ ہے: \"ہم نے ایسی وفا کی اس جیسی وفا لوگ نہ کر سکے۔ اور عدی بن حاتم نے ہمیں بزرگی و شرافت کی پوشاک پہنائی\"۔ ابن فتحون اور ابن الامیر نے ان کا اپنے استدراک میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۵۵)"}],[1932,"§۱۹۳۳ ۔ حارث بن مرہ\nبن دوران نفیلی دور نبوت پایا ہے۔ کتاب \"الردۃ\" میں وثیمہ نے ان کا ذکر کیا ہے۔ اور ان کی وہ نصیحت ذکر کی ہے جو انہوں نے بنی عامر کو کی تھی: \"اے بنی عامر! اگر تم اللہ تعالیٰ کے دین کی مدد کرو گے تو تمہاری مدد ہوگی اور اگر تم اللہ تعالیٰ اور دین سے دشمنی رکھو گے تو بے یار و مددگار چھوڑ دیئے جاؤ گے۔ اور اگر تمہیں شکست ہوئی تو بھاگنے سے کچھ فائدہ نہیں ہوگا اور اگر اپنی قوم کے لیے تم ڈٹے رہے تو اللہ کی قسم مار دیئے جاؤ گے\"۔ ابن فتحون اور ابن الامین نے بھی اپنے استدراک میں ان کا ذکر کیا ہے۔"],[1933,"§۱۹۳۴ ۔ حارث بن معاویہ کندی\nقسم اول میں تذکرہ ہو چکا ہے۔"],[1934,"§۱۹۳۵ ۔ (ز) حارث بن میناء\nانہیں دور نبوی نصیب ہوا، ابن اسحاق، محمد بن ابراہیم تیمی سے بحوالہ حارث بن میناء روایت کرتے ہیں۔ فرمایا: سیدنا عمر رضی اللہ عنہ مسلسل مجھے بلاتے رہے، پھر ایک قصہ ذکر کیا جس سے پتہ چلتا ہے کہ وہ زمانہ نبوی میں پورے مرد تھے۔ اس قصہ کا امام بخاری(1) نے اپنی تاریخ میں ذکر کیا ہے اور ابن حبان(2) نے ثقات التابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۲۸۲/۲)\n(2) الثقات (۱۳۶/۴)"}],[1935,"§۱۹۳۶ ۔ (ز) حارث بن نظام\nبن جشم بن عمرو بن مالک بن جشم بن خیوان بن نوف بن ہمدان ہمدانی، دور نبوت پایا ہے، ان کے بیٹے عبدالرحمن وہی اشی ہمدانی ہیں جو عبدالملک بن مروان کے دور میں مشہور شاعر تھے۔ ابن کلبی نے ان کا ذکر کیا ہے۔"],[1936,"§۱۹۳۷ ۔ حارث بن نعمان بن قیس"],[1937,"§۱۹۳۸ ۔ حارث (بے نسبت)\nقسم اول میں حبیب بن حارث کے سوانح میں ان کا تذکرہ گزر چکا ہے۔"],[1938,"§۱۹۳۹ ۔ (ز) حارثہ بن بدر\nبن حصین بن قطن بن مالک بن غدانہ بن یربوع بن حنظلہ بن زید مناۃ بن تمیم تمیمی غدانی۔ ابو الفرج اصبہانی کا قول ہے کہ وہ احنف بن قیس کی ولادت میں موجود تھے۔ میں کہتا ہوں: اگر واقعہ ایسا ہی ہے تو انہوں نے دور نبوت پایا ہے۔ فتوحات میں ان کی بڑی کارکردگیاں ہیں۔ سیدنا عمر، سیدنا علی اور امیر معاویہ رضی اللہ عنہم اور ان کے بیٹے کی حکومت میں زیاد وغیرہ کے ساتھ کئی قصے پیش آئے۔ حاکم نے تاریخ نیسا پور میں سلیمان بن احمد نمی سے نقل کیا ہے کہ انہوں نے ان کا صحابہ میں ذکر کیا ہے۔ میں کہتا ہوں: نجی طبرانی ہیں۔ لیکن یہ بات مجھے ان کی مجم میں نہیں ملی۔ واللہ اعلم۔ \"کامل\" میں مہرذ ذکر کرتے ہیں کہ وہ عبد اللہ بن حارث بہتہ عراق کی حکومت کے دوران ۶۴ھ میں ڈوب کر فوت ہوئے جس کا قصہ یہ ہے کہ وہ خوارج سے جنگ کے امیر تھے۔ انہوں نے انہیں نہر تیزی پر شکست سے دوچار کیا۔ جب خوارج نے انہیں زخمی کر دیا تو یہ اپنے باقیماندہ ساتھیوں کے ساتھ کشتی میں بیٹھ رہے تھے کہ اتنے میں ان کے کسی ساتھی نے آواز دی: حارثہ! مجھ جیسا شخص ضائع نہیں ہونا چاہیے۔ انہوں نے کشتی بان سے کہا: اس کے قریب کرو۔ تو وہ شخص کشتی میں دھرے اسلحہ تک پہنچنے میں کامیاب ہو گیا۔ یوں حارثہ اور ان کے ساتھی غرقابی کا شکار ہو گئے۔"],[1939,"§۱۹۴۰ ۔ (ز) حارثہ بن سفیان بجلی\nدور نبوت میسر ہے اور سلمیٰ بنت جابر احمسیہ کے خاوند ہیں۔ عبداللہ بن مبارک نے کتاب \"البر والصلۃ\" میں ان کا ذکر کیا ہے کہ ابان بن عبداللہ بجلی نے بحوالہ فلاں بن ابی حازم ہمیں بتایا کہ سلمیٰ بنت جابر، عبداللہ بن مسعود رضی اللہ عنہ کے پاس آ کر کہنے لگیں: میرے خاوند حارثہ بن سفیان اللہ کو پیارے ہو گئے اور ظہیرستان میں شہید ہو گئے۔ اب کئی طرف سے پیامہائے نکاح آ رہے ہیں، میں نے اپنے آپ کو اپنے خاوند کے لیے روکے رکھا ہے تا کہ جنت میں اس کی بیوی بن سکوں کیا ایسا کرنا ٹھیک ہے؟ آپ نے فرمایا: ہاں۔ میں کہتا ہوں: فلاں شخص کا نام کریم ہے اس کا یہ نام احمد زبیری نے بحوالہ ابان بجلی اپنی روایت میں لیا ہے۔ انہوں نے اپنی روایت میں یہ اضافہ بھی نقل کیا ہے کہ ابن مسعود رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"میری امت میں سے سب سے پہلے مجھ سے ملنے والی عورت احمس کی ہوگی۔\"(1)","",{"fn":"(1) جمع الجوامع (۶۳۴۱)"}],[1940,"§۱۹۴۱ ۔ (ز) حارثہ بن عبید کلبی\nابو حاتم(1) السجستانی نے کتاب \"المعمرین\" میں ان کا ذکر کیا ہے۔ ہشام کلبی فرماتے ہیں: مجھے سلمہ بن معتب (جو ان کی اولاد سے ہیں) کہنے لگے: میرا جہاں تک اندازہ ہے وہ پانچ سو(۵۰۰) سال زندہ رہے اور ان کے یہ اشعار بھی درج کیے: \"کاش! میں اپنی عمر گزار چکا ہوتا، کیا زمانہ میری آرزو بر آری کرے گا۔ زمانے کی گردش نے مجھے موڑ کر رکھ دیا اور حالت یہ ہوگئی کہ میری حیثیت گھر میں پرانے کپڑے کی سی رہ گئی۔ میرے رشتہ دار جب مجھے دیکھتے ہیں تو انہیں اذیت ہوتی ہے کہ میں ابھی تک زندہ ہوں۔ آج میری موت کہاں ہے؟\" ابن ابی حاتم کا قول ہے: ان کی اولاد نے انہیں عرصہ دراز تک چھپائے رکھا۔","",{"fn":"(1) المعمرین (۹۴)"}],[1941,"§۱۹۴۲ ۔ حارثہ بن مضرب العبدی(1)\nانہیں دور نبوت حاصل ہے اور سیدنا عمر اور سیدنا علی رضی اللہ عنہما وغیرہ سے روایت بھی کرتے ہیں۔ ان سے ابن اسحاق سبیعی روایت لیتے ہیں۔ ابن معین وغیرہ ائمہ فن نے ان کی توثیق کی ہے چونکہ انہوں نے دور نبوت پایا ہے اس لیے ابو موسیٰ نے \"ذیل\" میں اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۰۰۲) تجرید (۱۴۱/۱)"}],[1942,"§۱۹۴۳ ۔ (ز) حارثہ بن نمر (ابو اثال)\nدور نبوی میسر ہوا۔ اور عہد صدیقی میں جنگ یرموک میں شرکت کی اور مختلف ان کا ذکر کرتے ہوئے لکھتے ہیں: مالک بن قسامہ نے مجھے بتایا کہ جنگ یرموک میں مسلمانوں کے شاعر نے کہا: \"قبیلہ جذام اور لحم کو ہر پڑے ڈیل ڈول کی عورت سلام دیتی ہے۔ اور ٹووں والوں کا قتل مضبوط ہو گیا\"۔ تو ابو اثال حارثہ بن نمر نے یہ اشعار کہے: \"یرموک میں وہ قوم کیا ہی خوب رہی جس نے روم کے سرکش کی خاندانی شرافت کو پاؤں سے روند ڈالا۔ ان سے وہ گرجے جو شام میں بڑے پتھروں اور سنگ مرمر سے مزین تھے، بے کار ہو کر رہ گئے\"۔"],[1943,"§۱۹۴۴ ۔ حازم بن ابی حازم احمسی (قیس کے بھائی)\nان کا نسب ان کے والد عوف بن حارث کے حالات میں آئے گا۔ ابو عمر فرماتے ہیں: قیس اور حازم دور نبوی میں مسلمان تھے۔ آپ کے بعد انہوں نے ہجرت کی، ان میں سے حازم جنگ صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیتے ہوئے شہید ہو گئے۔"],[1944,"§۱۹۴۵ ۔ (ز) حباب بن عمیر سلمی ذکوانی\nدور نبوی پایا ہے۔ وثیمہ نے کتاب \"الردۃ\" میں ان کی وہ وصیت ذکر کی ہے جو انہوں نے بنی حنیفہ کو اسلام نہ چھوڑنے کے بارے میں کی تھی۔ اس کے متعلق ان کا خطبہ اور کافی کلام بھی ذکر کیا ہے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[1945,"§۱۹۴۶ ۔ (ز) حبال\nابن طلیحہ بن خویلد، ان کے والد کا تذکرہ آنے والا ہے۔ رہے وہ، تو جب ان کے والد نے نبوت کا دعویٰ کیا تھا یہ موجود تھے۔ چنانچہ ابن درید کا بیان ہے کہ طلیحہ نے اپنے ساتھیوں سے کہا: (انہیں سخت پیاس لگی تھی) حبال کے راستہ پر چلو، مثالیں بیان کرو تمہیں پانی مل جائے گا، تو جیسا اس نے کہا تھا انہیں پانی مل گیا۔ \"بلال\" تھوڑے پانی کو کہتے ہیں۔ جس سے ان کا فتنہ مزید بڑھ گیا۔"],[1946,"§۱۹۴۷ ۔ جبان\nابن ابی جبلہ تابعی ہیں۔ دور نبوی دیکھا ہے۔ ابن یونس کا قول ہے: سیدنا عمر رضی اللہ عنہ نے انہیں اہل مصر کی جانب دینی سمجھ بوجھ دلانے کے لئے بھیجا تھا۔ ابن حبان(1) نے ثقات التابعین میں ان کا ذکر کیا ہے۔ انہیں عمرو بن العاص اور کئی اور حضرات سے روایت بھی حاصل ہے۔ ابو العرب نے طبقات اہل القیروان میں ان کا ذکر کیا کہ احمد بن یحییٰ بن وزیر نے کہا: وہ افریقہ میں فوت ہوئے۔","",{"fn":"(1) الثقات (۱۸۱/۴)"}],[1947,"§۱۹۴۸ ۔ حبہ(1)\nابن جوین بن علی بن عبد نہم بن مالک بن غانم بن مالک بجلی غامدی عرفی ابو قدامہ۔ بقول طبرانی: کہا جاتا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا تھا۔ ابن عقدہ نے کتاب \"الموالاۃ\" میں انتہائی ضعیف سند سے لکھا ہے کہ جبہ بن جوین سے مروی ہے کہ غدیر خم کے روز نبی صلی اللہ علیہ وسلم نے اعلان کیا: \"باجماعت نماز تیار ہے\"۔ پھر یہ حدیث ذکر کی \"جس کا میں دوست ہوں اس کا علی دوست ہے\"۔ آپ(2) صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کا ہاتھ پکڑ کر بلند فرمایا یہاں تک کہ مجھے دونوں کی بغلیں صاف دکھائی دیں (فرماتے ہیں): میں اس وقت تک مشرک تھا۔ ابن الاثیر(3) فرماتے ہیں: یہ حدیث نبی صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کے بارے میں حجۃ الوداع کے موقع پر بیان فرمائی تھی اور اس دن کوئی مشرک حج کرنے نہیں آیا تھا۔ اگر یہ واقعہ صحیح ہے تو وہ صحابی ہوئے لیکن اس پر اتفاق ہے کہ وہ صحابی نہیں۔ میں کہتا ہوں: اگر یہ واقعہ صحیح ہو جائے تو یہ احتمال ہے کہ جبہ نے بالاتفاق آپ کو دیکھا ہے لیکن حج کا ارادہ نہیں کیا تھا، چونکہ سند ضعیف ہے اس لیے صحیح کہاں ہو سکتا ہے۔ جبہ کے ضعیف ہونے پر اتفاق ہے۔ صرف عجلی نے ان کی توثیق کی ہے جسے امام احمد نے چلایا ہے۔ صالح جزرہ فرماتے ہیں: درمیانے ہیں۔ اور علامہ ساجی کا قول ہے کہ ان کے ضعیف ہونے کے لئے ان کی یہ بات ہی کافی ہے کہ صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ اسی(۸۰) بدری صحابہ نے دیا۔ حبہ کی سیدنا علی، ابن مسعود اور عمار رضی اللہ عنہم سے کئی ایک روایات ہیں۔ ان سے سلمہ بن کہیل روایت کرتے ہیں جو ان کی دینداری اور عبادت گزاری کے بڑے مداح تھے۔ حکم بن عیینہ اور بہت سے کوئی حضرات روایت لینے میں شامل ہیں۔ جبہ کا انتقال ۷۰ھ کے بعد، بقول بعض اسے یا اس سے زائد عرصہ بعد ہوا۔ پھر پہلی حدیث جیسی مجھے ان کی ایک اور حدیث مل گئی۔ چنانچہ ابن مردویہ تفسیر میں ابان بن ثعلبہ کے طریق بحوالہ نفیع بن حارث، ابو الحمراء، وہ ابو مسلم ملائی اور جبہ عرفی سے روایت کرتے ہیں، دونوں فرماتے ہیں: جب نبی صلی اللہ علیہ وسلم نے مسجد میں کھلنے والی تمام کھڑکیوں کو بند کرنے کا حکم دیا تو یہ بات بڑی گراں گزری۔ حبہ کہتے ہیں: میں نے حمزہ کو دیکھا کہ وہ سرخ چادر اوڑھے آنسو بہا رہے اور کہہ رہے تھے \"تم نے اپنے چچا کو نکال دیا۔\" (حدیث) ابان تک کی سند ضعیف ہے۔ مسلم ملائی بھی ضعیف ہے۔ جبہ کے متعلق جیسا پہلے گزر چکا ہے اگر یہ روایت صحیح ثابت ہو جاتی ہے تو وہ صحابی بن سکتے ہیں۔ لیکن یہ بھی احتمال ہے کہ یہ اس وقت وہاں موجود تو ہوں لیکن تھے مشرک، جیسا کہ پہلی حدیث میں ہے۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابۃ (۱۰۳۱)\n(2) جامع المسانید (۲۵۸/۳)\n(3) اسد الغابۃ (۴۱۷)"}],[1948,"§۱۹۴۹ ۔ حبیب بن عاصم محاربی\nانہیں دور نبوت نصیب ہوا۔ زبیر بن بکار ہشام بن اسحاق بن کنانہ کے طریق سے روایت کرتے ہیں کہ جب قحط ختم ہو گیا (جسے عام الرمادہ کہا جاتا تھا) اور خوب بارشیں ہو کر وادیاں بہہ پڑیں تو سیدنا عمر رضی اللہ عنہ اپنے عربی گھوڑے پر بیٹھ کر وادی عقیق کی طرف نکلے، وادی کے ایک کونے سے کسی اعرابی نے آپ کو آواز دی ابن خیثمہ اللہ تعالیٰ تمہیں جزائے خیر دے۔ آپ نے اس سے پوچھا: تم کون ہو؟ وہ کہنے لگا: میں حبیب بن عاصم محاربی ہوں، پھر قصہ ذکر کیا۔"],[1949,"§۱۹۵۰ ۔ (ز) حبیب بن عوف عبدی\nان کا ذکر ان کے بھائی حارث بن عوف کے ساتھ گزر چکا ہے۔"],[1950,"§۱۹۵۱ ۔ (ز) حبیش اسدی(1)\nوثیمہ نے کتاب الردۃ میں ذکر کیا ہے کہ جب بنی اسد میں طلیحہ ظاہر ہوا تو وہ انہیں اسلام پر ثابت قدم رہنے کی ترغیب دیتے، طلیحہ کی روبرو تکذیب کرتے۔ اس بارے میں ان کے اشعار نقل کیے ہیں، چند اشعار میں سے یہ ایک شعر ہے: \"طلیحہ! میں اس بات کی گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی رب نہیں اور دین صرف دین محمدی ہے\"۔ فرماتے ہیں: پھر حبیش اور ان کے دونوں بیٹے غسان اور عبدالرحمن اس قبیلہ سے الگ ہو گئے۔ ابن فتحون اور ابن الاثیر(2) نے اپنے استدراک میں ان کا ذکر تو کیا لیکن کوئی ایسی بات ذکر نہیں کی جس سے پتہ چلے کہ ان کی نبی صلی اللہ علیہ وسلم سے ملاقات ہوئی ہو۔","",{"fn":"(1) اسد الغابۃ (۱۰۷۴)\n(2) اسد الغابۃ (۴۲۷/۱)"}],[1951,"§۱۹۵۲ ۔ (ز) حتات بن وذیح\nبشر میں تذکرہ ہوا ہے۔ مرزبانی کا قول ہے کہ جسر ابی عبید میں شہید ہوئے تو ان کے والد نے ان کا مرثیہ کہا: \"میں حیات کو موت کی خبر دیتا ہوں۔ میں جب تک اللہ تعالیٰ کے سامنے سجدہ ریز ہوں کوئی بھی مجھے اس جیسا جوانمرد دکھائی نہیں دیتا۔ حتات کی زندگی تو شہاب ثاقب کی طرح تھی اور ہر شہاب ثاقب بجھنے والا ہے\"۔"],[1952,"§۱۹۵۳ ۔ حتیت بن شہاب شامی\nدور نبوت میسر ہوا، زبیر بکار کا قول ہے: بصرہ میں ان کی بڑی قدر و منزلت تھی۔ عبداللہ بن عامر نے انہیں بصرہ کی نہر بطور جاگیر دے دی تھی۔"],[1953,"§۱۹۵۴ ۔ (ز) حتیت بن مظہر\nبن رئاب بن اشتر بن جوان بن فقعس کندی ثم الفقعی، دور نبوی نصیب ہوا۔ اور اتنی عمر پائی یہاں تک کہ سیدنا حسین بن علی رضی اللہ عنہ کے ساتھ شہید ہوئے۔ ابن کلبی نے ان کا ذکر ان کے چچا زاد بھائی ربیعہ بن حوط بن رئاب کے ساتھ کیا ہے۔ ان شاء اللہ حرف راء میں تذکرہ ہوگا۔"],[1954,"§۱۹۵۵ ۔ حجاج بن عبد یغوث\nبن عمرو بن حجاج زبیدی۔ ابو حذیفہ اور امام بخاری نے ذکر کیا ہے کہ وہ یرموک میں شریک تھے، فرماتے ہیں: قبیلہ زبید جو میمنہ میں تھا اس کے پاؤں اکھڑنے لگے تو وہ ایک دوسرے کو پکارنے لگے، ان میں حجاج بن عبد یغوث تھے۔ انہوں نے یکبارگی حملہ کیا تو ان لوگوں کو روم کی جانب سے ہٹا دیا گیا۔ ابن کلبی نے اپنی کتاب \"فتوح الشام\" میں ان لوگوں میں ان کا ذکر کیا ہے جو یمن سے خلافت صدیقی میں جہاد کے لئے وفد کی صورت میں آئے تھے۔"],[1955,"§۱۹۵۶ ۔ (ز) حجاج بن عبید\nانہیں ابن علیک بھی کہا جاتا ہے۔ دور نبوت پایا ہے۔ ابن کلبی کا بیان ہے کہ وہ ام جمیل ہلالیہ کے خاوند تھے جس کی تہمت سیدنا مغیرہ بن شعبہ رضی اللہ عنہ پر لگی تھی۔"],[1956,"§۱۹۵۷ ۔ (ز) حجار بن ابجر\nبن جابر محلی۔ دور نبوت پایا ہے۔ ابن درید \"اخبار منثورہ\" میں ابو حاتم سے بحوالہ عبیدہ بنی عجل کے شیوخ سے روایت کرتے ہیں، انہوں نے فرمایا: حجار بن ابجر کے والد نصرانی تھے ان سے یہ کہنے لگے: ابا جان! میں نے کئی لوگوں کو دیکھا کہ وہ اسلام لانے کے بعد صاحب شرافت بن گئے۔ میں بھی اس دین میں داخل ہونا چاہتا ہوں۔ وہ کہنے لگے: بیٹا! ذرا صبر کرو! میں خود تمہارے ساتھ عمر کے پاس چلتا ہوں تا کہ وہ تمہیں مشرف با اسلام کرے۔ اس سے بچنا کہ انتہائی منزل سے پہلے کہیں تھک ہار نہ جانا۔ پھر قصہ ذکر کیا۔ اسی میں ہے کہ ابجر نے سیدنا عمر رضی اللہ عنہ سے کہا: میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور حجار محمد (صلی اللہ علیہ وسلم) کے رسول ہونے کی گواہی دیتا ہے۔ آپ نے فرمایا: تمہیں کون منع کر رہا ہے؟ انہوں نے جواب دیا: میری ٹانگیں قبر میں لٹک رہی ہیں۔ مرزبانی نے منجم الشعراء میں ذکر کیا ہے کہ ابجر سیدنا علی رضی اللہ عنہ کے زمانہ میں ان کی شہادت سے کچھ عرصہ پہلے نصرانیت پر ہی مرا تھا۔ طبرانی نے اسمعیل بن راشد کے طریق سے روایت کی ہے کہ ابجر کا جنازہ عبدالرحمن بن ملجم کے پاس سے گزرا جبکہ حجار بن ابجر ایک طرف مسلمانوں کے ساتھ چل رہے تھے، جنازہ کے ساتھ نصاریٰ تھے جو اسے لے جا رہے تھے، پھر قصہ ذکر کیا۔"],[1957,"§۱۹۵۸ ۔ حجر بن عدی بن ادبر(1)\nقسم اول میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۰۹۳)"}],[1958,"§۱۹۵۹ ۔ حجر بن عنبس\nانہیں ابن قیس بھی کہا جاتا ہے۔ کنیت ابوالسکن بقول بعض ابوالعنبس حضرمی کوفی ہے۔ طبرانی نے صحابہ میں اور ابن حبان نے ثقات التابعین میں ان کا ذکر کیا ہے۔ ابن معین فرماتے ہیں: کوفی شیخ ہیں جو ثقہ اور مشہور ہیں۔ انہیں سیدنا علی رضی اللہ عنہ وغیرہ سے روایت حاصل ہے۔ امام بخاری رحمہ اللہ نے جزء رفع یدین میں اور ابو داؤد اور ترمذی نے ان کی روایت نقل کی ہے۔ امام بخاری(1) نے اپنی تاریخ میں روایت کی ہے کہ انہوں نے جاہلیت میں خون پیا تھا۔ اور طبرانی(2) نے موسیٰ بن قیس کے طریق سے بحوالہ ان کے روایت کی ہے کہ سیدنا ابو بکر وعمر رضی اللہ عنہما نے نبی صلی اللہ علیہ وسلم کے ہاں پیام نکاح بھیجا۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا: علی کیا تمہیں کچھ رغبت ہے؟ میں کہتا ہوں: اس پر تو علماء کا اتفاق ہے کہ حجر بن عنبس نے نبی صلی اللہ علیہ وسلم کی زیارت نہیں کی، لگتا ہے انہوں نے یہ قول کسی صحابی سے سن کر روایت کیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۷۳/۳)\n(2) المعجم الکبیر (۶۵۷۱/۴)"}],[1959,"§۱۹۶۰ ۔ حجر بن مالک\nبن حذیفہ بن بدر فزاری عیینہ بن حصن کے چچا زاد بھائی۔ انہیں دور نبوت میسر آیا، مرزبانی نے اپنے منجم میں ان کا ذکر کیا ہے، ان کی والدہ وہی ام قرفہ ہیں جو نبی صلی اللہ علیہ وسلم کی حیات میں قتل ہوگئی تھیں۔"],[1960,"§۱۹۶۱ ۔ (ز) حجناء بن رمیلہ نہمی\nان کا ذکر ان کے بھائی اشہب کے سوانح میں گزر چکا ہے۔"],[1961,"§۱۹۶۲ ۔ (ز) حجیل بن قدامہ یربوعی\nمغازی میں اموی نے ذکر کیا ہے کہ مرتدوں سے جنگ کے دوران وہ خالد بن ولید رضی اللہ عنہ کے ساتھ تھے۔ مالک بن نویرہ کے قتل میں بھی شریک تھے، وہی صدیق اکبر رضی اللہ عنہ کے پاس اس کے قتل کی اطلاع لے کر آئے تھے۔"],[1962,"§۱۹۶۳ ۔ (ز) حدیر بن علقمہ\nبن ابی الجون خزاعی سلیمان بن صرد بن ابی الجون مشہور صحابی جن کا ذکر ہوگا، ان کے چچیرے بھائی ہیں۔ اور اکثم بن ابی الجون جن کا تذکرہ گزر چکا ہے ان کے بھتیجے۔ انہیں دور نبوت حاصل تھا ان کا ایک بیٹا تھا جس کا نام میسرہ تھا جس کا کثیر عزہ شاعر خزاعی کے ساتھ ایک واقعہ پیش آیا۔ اسے مخاطب کر کے کثیر کہتا ہے: \"اگر ہم نے قریش سے اپنی رشتہ داری کی شاخ کاٹ ڈالی، تو میسرہ! تو کونسے دراہم سے اس رشتہ داری کو حاصل کرے گا\"۔ ابن کلبی نے جمہرہ میں ان کا ذکر کیا ہے۔"],[1963,"§۱۹۶۴ ۔ حذیفہ بن عبید مرادی(1)\nانہوں نے دور جاہلیت پایا ہے اور فتح مصر میں شریک ہوئے۔ ان کی کوئی روایت مشہور نہیں۔ یہ ابن یونس کا قول ہے جو ابن مندہ نے نقل کیا ہے۔ مغلطائی فرماتے ہیں: مجھے ابن یونس کی تاریخ میں ان کا تذکرہ نہیں ملا۔ سیدنا عمر رضی اللہ عنہ کے فیصلے میں ان کا ذکر آتا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۱۱۱)"}],[1964,"§۱۹۶۵ ۔ (ز) حذیفہ بارقی ازدی(1)\nبقول ابن مندہ: دور نبوت پانے والوں میں ان کا ذکر ملتا ہے۔ واقدی نے ایک مقلوب (الٹی) حدیث ذکر کی ہے جس کی طرف میں نے جنادہ کے سوانح میں اشارہ کر دیا ہے۔ بغوی لکھتے ہیں: ان کی صحابیت مشکوک ہے۔","",{"fn":"(1) اسد الغابۃ (۱۱۰۷) تجرید (۱۲۴/۱)"}],[1965,"§۱۹۶۶ ۔ حذیم بن حارث\nبن ارقم۔ بنی عامر بن عبد مناۃ کے فرد۔ سیرت میں ان کا ذکر ملتا ہے۔"],[1966,"§۱۹۶۷ ۔ حرام بن خالد\nبن ربیعہ بن وحید بن کلاب بن ربیعہ عامری ثم وحیدی، انہیں دور نبوت حاصل ہوا، سیدنا علی رضی اللہ عنہ نے ان کی بیٹی ام البنین سے شادی کی جس سے آپ کی چار اولادیں: عباس عبداللہ عثمان اور جعفر ہوئیں۔ سارے کے سارے اپنے بھائی حسین رضی اللہ عنہ کے ساتھ کربلا میں شہید ہوئے۔ جس کا ذکر ہشام بن کلبی اور زبیر بن بکار نے کیا ہے۔"],[1967,"§۱۹۶۸ ۔ حرام بن ربیعہ\nبن عامر بن مالک بن جعفر بن کلاب عامری، ثم جعفری، لبید شاعر کے بھائی انہیں دور نبوت ملا ہے۔ ان کے والد اور دادا کا تذکرہ آئے گا۔ ان کا بیٹا مالک سرداران کوفہ میں سے تھا۔ جن لوگوں کو مختار بن ابی عبید نے سیدنا حسین کے خون کے مطالبہ پر قتل کیا تھا ان میں یہ بھی شامل تھے۔ اکثر ان سے حزام بن ربیعہ بن وحید بن کعب بن کلاب کا اشتباہ ہو جاتا ہے جو ام البنین زوجہ علی کے والد ہیں جن سے عباس اور جعفر وغیرہ پیدا ہوئے۔ اس کے والد بھی اسی قسم میں شامل ہیں۔"],[1968,"§۱۹۶۹ ۔ حر بن نعمان\nبن قیس بن تیم طائی ابن کلبی نے ان کا ذکر کیا ہے کہ اسلام میں اہل ارتداد سے جنگ میں انہوں نے خوب خوب جوہر دکھائے، یعنی دور صدیقی میں۔"],[1969,"§۱۹۷۰ ۔ حرب بن جنادب\nبقول ابن عساکر: دور نبوی پایا ہے اور سیدنا عمر رضی اللہ عنہ کے زمانہ میں فتح دمشق میں شریک ہوئے، وہیں ان کی جائیداد ہے۔"],[1970,"§۱۹۷۱ ۔ حرقوص العنبری\nدور نبوت میسر ہے، ابو موسیٰ اشعری رضی اللہ عنہ کے ساتھ فتح تستر میں شریک ہوئے یہ حرقوص بن زہیر سعدی کے علاوہ ہیں۔ ابن ابی داؤد نے ان کا قصہ نقل کرنے کے بعد اس پر یقین کیا ہے کہ وہ ذوالندیہ ہے جبکہ ذوالندیہ کے متعلق کہا جاتا ہے کہ وہ ذوالخویصرہ اور ذوالخویصرہ کے بارے مشہور ہے کہ وہی حرقوص ہے۔"],[1971,"§۱۹۷۲ ۔ (ز) حرملہ بن سلمی\nاز بنی قر، دور نبوت ملا ہے۔ ابو عمر کندی نے کتاب الخندق میں ان کا ذکر کیا ہے کہ وہ فتح مصر میں شریک تھے۔"],[1972,"§۱۹۷۳ ۔ حرملہ بن منذر\nبن معدیکرب کندی ابوزبید شاعر، کنیت سے ہی شہرت رکھتے ہیں۔ آغانی میں ان کے طویل سوانح ذکر ہوئے ہیں۔ مجھے اکثر روایات سے ان کے متعلق معلوم ہوا ہے کہ وہ نصرانی تھے۔ ابو عبید بکری \"شرح الامالی\" میں لکھتے ہیں: طبری کا گمان ہے کہ وہ اسلام لایا تھا، جس کی دلیل یہ پیش کی کہ اس نے سیدنا عمر اور علی رضی اللہ عنہما کی زیارت کی ہے اور ولید بن عقبہ نے وصیت کی تھی کہ اسے اس کے پہلو میں دفن کیا جائے۔ میں کہتا ہوں: اس میں ایسی کوئی بات نہیں جس سے پتہ چلے کہ وہ اسلام لے آیا تھا۔"],[1973,"§۱۹۷۴ ۔ حریث بن محفض مازنی\nوہی حریث بن سلمہ بن مرارہ از بنی مازن بن عمرو بن تمیم ہیں۔ مرزبانی لکھتے ہیں مخضرم ہیں۔ جاہلیت کے دور میں ان کے بہت سے اشعار ہیں اور حجاج کے دور تک زندہ رہے۔ اس کے ساتھ ان کا ایک واقعہ بھی پیش آیا۔ وہ یوں کہ انہوں نے حجاج کو منبر پر یہ اشعار پڑھتے سنا: \"بزرگی کے بیٹوں کو ان کی مائیں لے کر نہیں بیٹھی رہیں بلکہ ان کے آباء و اجداد ہی بچے تھے، اس لیے وہ شرافت والے ہو گئے\"۔ تو یہ کھڑے ہو کر کہنے لگے: امیر! ان کا قائل کون ہے؟ اس وقت بے حد بوڑھے تھے: حجاج نے کہا: حریث بن مخفض مازنی۔ بعد میں جب حجاج منبر سے اترا تو ان سے کہنے لگا: کیا ضرورت پڑ گئی تھی کہ آپ نے میاں میرا خطبہ رکوا کر یہ سوال کیا؟ تو یہ کہنے لگے: میں ہی حریث بن مخفض ہوں۔ آپ نے میرا شعر پڑھا تو میں سر دھننے لگا۔ راوی کا بیان ہے: پھر حجاج انہیں علیحدہ لے گیا۔ یہی اشعار امیر معاویہ نے پڑھے جب آپ نے بنی عبد مناف کے نوجوانوں کو دیکھا تھا۔ یہ اشعار بھی کہے گئے ہیں: \"کیا تو نے میری قوم نہیں دیکھی جب انہیں ان کا بھائی بلاتا ہے تو لبیک کہتے ہیں۔ اور اگر وہ تلوار اٹھائے تو یہ بھی اٹھا لیتے ہیں\"۔ لفظ مخفض میں نے ایک نسخہ میں تشدید سے لکھا دیکھا ہے۔ جبکہ رضی شاطبی نے حاشیہ میں حاء کے سکون اور فاء کے بعد ضاد سے قلمبند کیا ہے۔"],[1974,"§۱۹۷۵ ۔ (ز) حریث بن عبدالملک\nاکیدر دومہ کے بھائی۔ بلاذری بطریق کلبی روایت کرتے ہیں کہ جب نبی صلی اللہ علیہ وسلم کی وفات ہوئی تو اکیدر نے زکوۃ نہ دی اور جو عہد و پیمان کیا تھا توڑ ڈالا اور دومتہ الجندل سے نکل کر حیرہ جا ٹھہرا تھا۔ جبکہ حریث اپنی تمام تر ملکیت سمیت مسلمان ہوئے جو بعد میں ان کے پاس سلامت رہی۔ راوی کا بیان ہے کہ انہی حریث کی بیٹی سے یزید بن معاویہ نے شادی کر لی تھی، جمہرہ میں یونہی لکھا ہے۔"],[1975,"§۱۹۷۶ ۔ (ز) حزن بن نصر عدوی\nعدی تمیم۔ ان کا ذکر ان کے بھائی شرط کے حالات میں ہوگا۔"],[1976,"§۱۹۷۷ ۔ (ز) حسان بن فائد عبسی\nسیدنا عمر رضی اللہ عنہ سے حدیث سنی، انہیں دور نبوی حاصل ہوا ہے ان سے روایت کرنے والے راوی مجھے صرف ابو اسحاق سبیعی ملے ہیں۔ ابو حاتم(1) فرماتے ہیں: بزرگ تھے۔ ابن حبان(2) نے ثقات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۲۳۶/۳)\n(2) الثقات (۱۶۳/۴)"}],[1977,"§۱۹۷۸ ۔ (ز) حسان بن کریب\nبن یشرح ابن عبد کلال بن عریب بن شرحبیل رعینی۔ کنیت ابوکریب تھی۔ دور نبوی نصیب رہا۔ ابو سعید بن یونس لکھتے ہیں: سیدنا عمر رضی اللہ عنہ کی خلافت میں ہجرت کی اور فتح مصر میں شریک ہوئے۔ سیدنا عمر رضی اللہ عنہ سے روایت کرتے ہیں۔ جبکہ ان سے ابوالخیر یزنی واہب معافری، اور کعب بن علقمہ وغیرہ روایت لیتے ہیں۔ پھر بطریق واہب بن عبداللہ بحوالہ ان کے روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ نے ان سے پوچھا: کیا تم لوگ اپنے اخراجات کا حساب رکھتے ہو؟ پھر ایک حدیث ذکر کی۔ ابن عساکر ان کے حالات میں عیاش بن عباس کے طریق سے ان کے حوالہ سے روایت کرتے ہیں، فرمایا: ہم لوگ امیر معاویہ کے دروازے پر تھے، ہمارے ساتھ صحابی رسول صلی اللہ علیہ وسلم ابو مسعود بھی تھے۔ پھر ان کا قصہ نقل کیا۔ انہیں سیدنا علی، ابوذر اور معاویہ رضی اللہ عنہم سے روایت حدیث کا شرف بھی حاصل ہے۔"],[1978,"§۱۹۷۹ ۔ حسین بن خارجہ(1)\nعبدان نے صحابہ میں ان کا ذکر کیا ہے۔ احمد بن سیار فرماتے ہیں: لوگوں نے ان کے صحابی ہونے کا ذکر نہیں کیا اگر چہ وہ بڑی عمر کے تھے۔ ابن خزیمہ اور یعقوب بن شیبہ وغیرہ حضرات بطریق نعیم بن ابی ہند، ابو حازم سے بحوالہ حسین بن خارجہ روایت کرتے ہیں، انہوں نے فرمایا کہ سیدنا عثمان رضی اللہ عنہ کی شہادت سے پہلے جو یورش و فتنہ برپا ہوا مجھے اس کے متعلق بڑی الجھن ہوئی کہ کیا کیا جائے، میں نے اللہ تعالیٰ سے دعا کی: یا اللہ! کوئی ایسی راہ سمجھا جسے اختیار کر سکوں۔ پھر ایک لمبا قصہ ذکر کیا جس میں انہوں نے اپنا وہ خواب بیان کیا جو سیدنا سعد بن ابی وقاص کو سنایا تھا۔ جس سے پتہ چلتا ہے کہ انہیں دور نبوت ملا تھا۔ یہ جہاں تک مجھے معلوم ہوتا ہے ان حسیل بن خارجہ کے علاوہ کوئی صاحب ہیں جن کا ذکر قسم اول میں ہوا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۱۶۹)"}],[1979,"§۱۹۸۰ ۔ حشرج بن اشہب\nبن ورد بن عمرو بن ربیعہ بن جعدہ المجعدی، دور نبوی حاصل ہوا ہے۔ ان کا بیٹا عبداللہ جو بڑا بہادر اور قابل تعریف شخص تھا۔ سیدنا عبداللہ بن زبیر رضی اللہ عنہ کے دور گورنری میں فارس پر غالب ہوا۔ اس کے متعلق زیاد انجم کا یہ شعر ہے: \"بزرگی مردانگی اور سخاوت اس خیمہ میں ہے جو ابن حشرج پر لگایا ہے\"۔ اور فرزدق اپنے شعر میں انہی کو مراد لیتے ہیں۔ انہوں نے جو اٹا میں مضر کے سرداروں میں لوٹ مار مچائی، ابن کلبی نے ان کا ذکر کیا تو ان کے وہ اشعار نقل کیے جو سخاوت پر فخریہ انداز میں انہوں نے کہے ہیں۔ زیاد بن اشہب میں اس کا تذکرہ ہوگا۔"],[1980,"§۱۹۸۱ ۔ (ز) حصین بن وبرہ\nبن عدی بن جابر بن حیق بن عمرو بن سلسلہ بن تمیم طائی۔ دور نبوت نصیب ہوا، ان کے بیٹے نویرہ کا ذکر نجدہ حروری کے زمانہ میں ملتا ہے جس نے یزید بن معاویہ کی موت کے بعد یمامہ میں خروج کیا تھا۔ ابن کلبی نے ان کا ذکر کیا ہے۔"],[1981,"§۱۹۸۲ ۔ (ز) حصین جذامی\nحصین میں تذکرہ ہوا ہے۔"],[1982,"§۱۹۸۳ ۔ (ز) حصین بن حارث\nبن مسلم بن قیس بن معاویہ بھی۔ دور نبوی ملا ہے، ان کا بیٹا جراح، عبداللہ بن زبیر رضی اللہ عنہ کے پیرو کاروں میں سے تھا جسے انہوں نے وادی القری کا والی بنا دیا تھا۔ یہ ابن کلبی کا بیان ہے۔ ابن زبیر کے وہاں کثیر تعداد میں کھجوروں کے درخت تھے، جراح نے لوگوں کو لوٹ مار کی کھلی چھوٹ دے دی۔ ابن زبیر کو پتہ چلا تو آپ نے اسے معزول کر دیا۔ جب وہ آپ کے پاس آیا تو آپ نے اسے کوڑے لگائے اور فرمایا: \"میری کھجوریں ہڑپ کر کے میری نافرمانی پر اتر آئے ہو؟\" یہ بات ضرب المثل کی صورت اختیار کر گئی۔ سیدنا ابن زبیر رضی اللہ عنہ کے مخالفین اسے بخیل کہا کرتے تھے، اس واقعہ سے انہیں مزید تقویت مل گئی۔"],[1983,"§۱۹۸۴ ۔ (ز) حصین بن حسان\nبن شریک بن حذیفہ بن بدر فزاری۔ مرزبانی نے ان کے بیٹے جلہمہ کے حالات میں لکھا ہے کہ یہ مخضرمی ہیں۔"],[1984,"§۱۹۸۵ ۔ حصین بن حدیر\nدور نبوی میسر ہوا اور سیدنا عمر رضی اللہ عنہ سے سماع حدیث کیا۔ بصرہ فروکش ہوئے، ان سے حسان بن زاہر روایت کرتے ہیں۔ امام بخاری(1) رحمہ اللہ نے اپنی تاریخ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۴/۳)"}],[1985,"§۱۹۸۶ ۔ حصین بن سبرہ\nدور نبوی نصیب ہوا۔ سیدنا عمر رضی اللہ عنہ سے سماع کیا اور کوفہ فروکش ہوئے۔ ان سے ابراہیم تیمی روایت کرتے ہیں ان کا بھی امام بخاری نے ذکر کیا ہے۔ ابن سعد فرماتے ہیں، حصین بن سبرہ نے فرمایا: \"ہمیں سیدنا عمر رضی اللہ عنہ نے نماز فجر پڑھائی جس میں سورۃ یوسف پڑھی تھی۔\""],[1986,"§۱۹۸۷ ۔ (ز) حصین بن مالک\nبن ابی عوف بن عریف بن مالک بن دینار بن ثعلبہ بن عمرو بن یشگر بن علی بن مالک بن سعد بن بدر بن قسر بجلی قسری۔ انہیں دور نبوت ملا ہے اور جنگ قادسیہ میں شرکت کی۔ اس دن وہ بجیلہ کے امیر تھے یہ ابن کلبی کا بیان تھا۔ یہ عبد شمس بن ابی عوف کے بھتیجے ہوتے ہیں جن کا نام نبی صلی اللہ علیہ وسلم نے عبداللہ رکھ دیا تھا۔ انہیں قسم اول میں شمار کر لینا چاہیے کیونکہ فتوحات میں صرف صحابہ امیر بنائے جاتے تھے۔"],[1987,"§۱۹۸۸ ۔ حصین بن ہریم تمیمی\nوثیمہ نے کتاب الردۃ میں ان کا ذکر کیا ہے کہ زبرقان بن بدر نے انہیں محکم بن طفیل کی جانب اسے ارتداد سے باز رہنے کے لیے بھیجا تھا اور اسے اسلام کی طرف لوٹ آنے کی دعوت دینے کے لیے روانہ کیا تھا۔ اور پھر ان کا قصہ ذکر کیا ہے۔"],[1988,"§۱۹۸۹ ۔ (ز) حصین ہمدانی\nان کا بھی وثیمہ نے ذکر کیا ہے۔ لکھتے ہیں کہ ان سے اپنی قوم میں کوئی قتل ہو گیا تھا تو یہ بنی سلیم سے جا ملے جب فجاءۃ ان لوگوں کو مرتد ہونے کی دعوت دینے آیا تو حصین نے ان کے ہاں رہنا پسند نہ کیا۔ انہوں نے انہیں نصیحت بھی کی اور مرتد ہونے سے منع بھی کیا لیکن انہوں نے ایک نہ مانی، ان میں سے کسی بدبخت نے ان کے طمانچہ بھی مارا تھا، بہر کیف یہ انہیں چھوڑ کر آگئے۔ وثیمہ اس سلسلہ میں ان کے اشعار بھی نقل کرتے ہیں۔"],[1989,"§۱۹۹۰ ۔ (ز) حصین جذامی\nدور نبوت نصیب ہوا۔ وثیمہ کا بیان ہے کہ وہ بنی حنیفہ میں ٹھہرے ہوئے تھے۔ جب یہ لوگ مرتد ہو گئے تو یہ خفیہ طور پر اپنے رب کی عبادت کرتے تھے۔ بالآخر سیدنا خالد بن ولید رضی اللہ عنہ نے ان پر دسترس حاصل کر لی۔ آپ نے انہیں قتل کرنا چاہا تو کہنے لگے: اگر آپ اپنے دینی مخالف یا آپ سے مقابلہ کرنے والے کو قتل کرتے ہیں تو میں ان دونوں سے بری ہوں اور اگر آپ مجھے بنی حنیفہ کے کفر کی وجہ سے پکڑیں گے تو اللہ تعالیٰ نے مجھے اس سے میرا اقرار دیا ہے \"کوئی بوجھ اٹھانے والا دوسرے کا بوجھ نہیں اٹھائے گا۔\"(1) وثیمہ فرماتے ہیں: آپ نے انہیں بری قرار دے کر انہیں چھوڑ دیا، پھر وہ مدینہ چلے گئے۔ اس کے متعلق ان کا بھائی حصن جذامی کہتا ہے: \"میرا، حصین اور ابن ابو بجرہ سفیان کا دین اسلام ہے\"۔ سفیان ان کے تیسرے بھائی ہیں۔ وثیمہ نے تینوں بھائیوں کے وہ اشعار نقل کیے ہیں جن میں خالد بن ولید رضی اللہ عنہ کو مخاطب کر کے یہ بتاتے ہیں کہ وہ مسلمان ہی رہے۔ اور یہ بھی ذکر کیا ہے کہ اس کے بعد انہوں نے انصار سے معاہدہ کر لیا تو ان میں شمار ہونے لگے۔","",{"fn":"(1) سورۃ فاطر: ۳۵"}],[1990,"§۱۹۹۱ ۔ حطان بن حفص\nبن مجدع بن وابش بن عمیر بن عبد شمس بن سعد سعدی، انہیں دور نبوت حاصل رہا اور وہ ان کی رہائش دیہات میں تھی۔ ان کا ایک بیٹا ہیر دان نامی تھا جو عبد الملک بن مروان کے زمانہ میں چور ہونے کی مشقت اٹھاتا تھا۔ ان کا مہلب کے ساتھ ایک واقعہ بھی پیش آیا جس کو مرزبانی نے منجم الشعراء میں ذکر کیا ہے۔"],[1991,"§۱۹۹۲ ۔ حطان بن عوف\nدور نبوت میسر ہوا اور جابیہ میں سیدنا عمر رضی اللہ عنہ کے خطبہ میں شریک ہوئے۔ سیدنا بلال رضی اللہ عنہ سے سماع حدیث کیا۔ ابن عائذ نے مغازی میں ان کا ذکر کیا ہے کہ یزید بن ابی حبیب انصاری نے ان سے سماع حدیث کیا ہے۔"],[1992,"§۱۹۹۳ ۔ الحطیئہ شاعر\nنام جرول بن اوس بن مالک بن جویہ بن مخزوم بن مالک بن غالب بن قطیعہ بن عبس عبسی ہے۔ مشہور شاعر ہے۔ کنیت ابو ملیکہ تھی۔ ابو الفرج اصبہانی(1) لکھتے ہیں: وہ نامور، پیشرو اور فصیح شاعر تھا۔ اور شعر کی تمام اصناف مدح، ہجو، فخر، غزل میں اپنا کلام پیش کرتا۔ اور سب میں عمدہ انداز سے اشعار کہتا۔ بڑا شریر اور بے وقوف ثابت ہوا۔ اس کی عادت تھی جب ایک قبیلہ سے ناراض ہوتا تو دوسرے کی طرف منسوب ہو جاتا۔ ایک بار اسے گمان ہوا کہ اس کا تعلق بنی حارث بن سروس سے ہے اور وہ عمرو بن علقمہ کا بیٹا ہے اور ایک دفعہ ذیل بن ثعلبہ کی جانب اور دوسری بار بنی عوف بن عمرو کی طرف نسبت کر لی۔ اس کے متعلق اس کی کئی باتیں ہیں جو ہر قبیلہ کے ساتھ پیش آئیں اور جو اشعار اس نے کہے وہ اس کے دیوان میں مذکور ہیں۔ وہ اتنا ہجو گو تھا کہ اس نے اپنے والد، والدہ، بھائی، بیوی اور اپنی جو تک کی ہے۔ مخضرمی: جاہلیت اور اسلام کا زمانہ پایا ہے۔ عہد نبوی میں ہی اسلام لایا تھا لیکن پھر مرتد ہو گیا۔ جب قید و بند کے مراحل سے گزرا تو دوبارہ مسلمان ہو گیا۔ ٹھگنے پن کی وجہ سے اس کا لقب \"حطیئہ\" تھا۔ اشعار کے راوی حماد کا قول ہے: حطیئہ کا لقب اس وجہ سے پڑا کہ ایک دفعہ لوگوں میں بیٹھے اس نے زور سے گوز مارا تو کسی نے کہا: یہ کیا کیا؟ اس نے کہا: بوجھ ہلکا کیا ہے۔ تو بس اس کا لقب حطیئہ پڑ گیا۔ امام اصمعی فرماتے ہیں: وہ (سوال پر) بڑا اصرار کرتا اور بے حد بخیل تھا۔ کسی شاعر کے شعر میں تمہیں عیب تو مل جائے گا لیکن حطیئہ کے اشعار میں کم ہی تمہیں یہ چیز ملے گی۔ اس سے ملتے جلتے الفاظ ابو عبیدہ کے ہیں۔ زبرقان بن بدر کے ساتھ بغیض بن عامر بن شماس کے سوانح میں اس کا قصہ پہلے گزر چکا ہے۔ زبیر بن بکار کا قول ہے کہ میرے چچا نے فرمایا: حطیئہ مدینہ آیا تو قریش نے اسے ہدیے، تحفے پیش کیے تا کہ اس کے شر سے بچا جا سکے۔ تو وہ مسجد میں کھڑے ہو کر اعلان کرنے لگا: مجھے جوتے کون پہنائے گا؟ اسحاق موصلی فرماتے ہیں: میرے خیال میں زہیر کے بعد حطیئہ سے بڑھ کر کوئی شاعر نہیں گزرا۔ زبیر کی روایت ہے کہ ایک دیہاتی سیدنا حسان کے پاس کھڑے ہو کر کہنے لگا: شعر سنئے۔ سیدنا حسان نے اس سے فرمایا: تم کیسے سنتے ہو؟ کہنے لگا: میں سن کر بوجھ محسوس کرتا ہوں۔ سیدنا حسان غصہ ہو کر فرمانے لگے: تو کون ہے؟ وہ کہنے لگا: ابو ملیکہ۔ فرمایا: میرے نزدیک تجھ سے زیادہ ذلیل و کمزور شخص نہیں آیا۔ کیا تمہیں صرف عورت کی کنیت ملی تھی۔ تیرا نام کیا ہے؟ کہنے لگا: حطیئہ۔ سیدنا حسان نے سر جھکا لیا۔ پھر فرمانے لگے: بھئی اپنا راستہ لو۔ ابو عمر بن علاء فرماتے ہیں: عرب شعراء نے حطیئہ کے شعر سے بڑھ کر کوئی سچا شعر نہیں کہا: جو نیکی کرے گا اس کے بدلے سے محروم نہیں رہے گا۔ اللہ تعالیٰ اور لوگوں کے ہاں نیکی رائیگاں نہیں جاتی۔ ابن ابی الدنیا نے \"اصطناع المعروف\" میں بحوالہ شعبی روایت کیا ہے کہ حطیئہ سیدنا عمر رضی اللہ عنہ کے پاس تھا اور یہی شعر پڑھا جس پر کعب احبار کہنے لگے: یہی بات اللہ کی قسم! تورات میں ہے کہ نیکی اللہ تعالیٰ اور مخلوق میں ضائع نہیں ہوتی۔ محمد بن سلام \"طبقات الشعراء\" میں لکھتے ہیں: کعب بن زہیر نے اپنی موت کے وقت یہ اشعار پڑھے: اب جب کہ کعب قبر کے دھانے پہنچ چکا اور جرول (حطیئہ) نے اپنا معاملہ سونپ دیا، ہمارے بعد اشعار کو اوزان پر کون کہے گا۔ ابو حاتم سجستانی بحوالہ اصمعی روایت کرتے ہیں: جب حطیئہ نے زبرقان کی ہجو کی تو انہوں نے سیدنا عمر رضی اللہ عنہ سے استدعا کی، تو آپ رضی اللہ عنہ نے حسان بن ثابت کو بلا بھیجا، ان سے پوچھا: کیا یہ ہجو ہے؟ انہوں نے فرمایا: ہاں۔ اس نے اس پر حملہ کیا ہے۔ سیدنا عمر رضی اللہ عنہ نے اسے قید میں ڈال دیا۔ قید خانہ میں اس نے یہ اشعار کہے: \"ذی مرخ میں جو چوزے ہیں ان کے بارے تم کیا کہو گے جن کے پوٹے خالی ہیں نہ ان کے پاس پانی ہے اور نہ کوئی درخت، ان کے لیے دوڑ دھوپ کرنے والے کو تم نے اندھیری کوٹھڑی میں لا ڈالا۔ عمر تم پر اللہ کی رحمت و سلامتی ہو اب اسے معاف کر دے\"۔ سیدنا عمر رضی اللہ عنہ آبدیدہ ہو گئے۔ سیدنا عمرو بن العاص نے اس کی سفارش بھی کی۔ چنانچہ آپ نے اسے رہا کر دیا۔ حطیئہ امیر معاویہ کی خلافت تک زندہ رہا۔ سعید بن العاص وغیرہ کے ساتھ اس کے کئی واقعات پیش آئے۔ پھر مجھے کوئی ایسی روایت مل گئی جس سے پتہ چلتا ہے اس کی وفات تاخیر سے ہوئی۔ چنانچہ ابو الفرج عبداللہ بن عیاش منتوف کے طریق سے روایت کرتے ہیں: ایک دفعہ ابن عباس (جب وہ نابینا ہو چکے تھے) تشریف فرما تھے آپ کے آس پاس سرداران قریش کا ہجوم تھا، اتنے میں ایک دیہاتی نے آکر سلام کیا۔ پھر ایک لمبا واقعہ ذکر کیا جس میں ہے کہ وہ دیہاتی حطیئہ شاعر ہی تھا۔","",{"fn":"(1) الأغانی (۱۵۷/۲)"}],[1993,"§۱۹۹۴ ۔ حکم بن عبدالرحمن\nبن ابی العصماء شعمی ثم فرعی۔ تمیم بن ورقاء کے سوانح میں ان کا ذکر ہو چکا ہے۔"],[1994,"§۱۹۹۵ ۔ حکم بن مغفل\nبن عوف بن عمیر بن کلیب بن ذہل بن سیار بن والبہ بن دول بن سعد بن مناۃ بن غامد غامدی۔ دور نبوت حاصل ہے۔ یہ سفیان بن عوف بن مغفل بن عوف (جن کا تذکرہ ہوگا) کے چچا ہیں۔ سفیان امیر معاویہ کے ساتھ جبکہ حکم سیدنا علی رضی اللہ عنہ کے ساتھ تھے۔ جو خوارج کے ساتھ جنگ میں شہید ہو گئے۔ ابن کلبی نے ان کا ذکر کیا ہے۔"],[1995,"§۱۹۹۶ ۔ حکیم(1)\nابن جبلہ بن حصن بن اسود بن کعب بن عامر بن حارث عبدی۔ بقول ابو عمر(2) انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے۔ لیکن مجھے نہ ان کی کوئی روایت معلوم ہے اور نہ کوئی ایسی حدیث جس سے پتہ چلے کہ یہ صحابی ہیں۔ سیدنا عثمان رضی اللہ عنہ نے انہیں سندھ بھیجا تھا۔ پھر یہ بصرہ فروکش ہوئے اور وہیں جنگ جمل میں شہید ہو گئے۔(3)","",{"fn":"(1) اسد الغابۃ (۱۲۳۳) استیعاب (۵۵۸)\n(2) استیعاب (۴۲۱/۱)\n(3) اسد الغابۃ (۴۳/۱)"}],[1996,"§۱۹۹۷ ۔ حکیم\nبن قبیصہ بن ضرار بن عمرو خثعمی بشر کے والد۔ مرزبانی نے اپنی معجم میں ان کا ذکر کیا کہ مخضرمی ہیں۔ ابن قتیبہ کا کہنا ہے: زیادی، اصمعی سے وہ بحوالہ حارث بن مصرف روایت کرتے ہیں کہ سلتی اور ساحر کے روز شقیق بن جزء بن ریاح باہلی نے حکیم بن قبیصہ بن ضرار خثعمی اپنے ہاں سے نکال دیا۔ پھر ایک واقعہ ذکر کیا۔ فرماتے ہیں: مجھے اپنے ساتھیوں میں سے کئی لوگوں نے بتایا کہ شقیق نے اسلام کا زمانہ پایا تو اسلام لے آیا اور جنگ یرموک میں شہادت پائی۔ فرماتے ہیں کسی اور نے مجھ سے بیان کیا کہ حکیم نے اسلام کا دور پایا تو اسلام لے آئے اور امیر معاویہ کے دور تک زندہ رہے۔ سیدنا معاویہ رضی اللہ عنہ نے ان سے پوچھا: تم کس دن کو سخت ترین سمجھتے ہو؟ انہوں نے کہا: جس دن شقیق نے مجھے نکال دیا تھا۔ پوچھا: اور کون سا پسندیدہ دن تھا؟ فرمایا: جس دن اللہ تعالیٰ نے مجھے اسلام کی ہدایت عطا فرمائی۔"],[1997,"§۱۹۹۸ ۔ حلبس بن زیاد\nبن غطیف الطائی۔ عدی بن حاتم کے ماں شریک بھائی۔ ملحان میں ان کا تذکرہ ہوگا۔ اور ہم ابو بکر خرائطی کی \"مکارم الاخلاق\" میں پیشم بن عدی کے طریق سے بحوالہ ملحان بن عتکی سے وہ اپنے والد وہ اپنے دادا حلبس بن زیاد طائی سے روایت کرتے ہیں (زیاد نے حاتم طائی کی بیوی نوار سے شادی کر لی تھی)۔ ملحان کہتے ہیں: میں نے نوار سے کہا (یعنی اس کی والدہ سے کہا): مجھے حاتم طائی کی کوئی عجیب بات سناؤ، وہ کہنے لگیں: ان کے سارے کام عجیب تھے۔ ایک دفعہ قحط سالی تھی، ہمیں مرنے کا یقین ہو چکا تھا۔ پھر حاتم کی قربانی و ایثار کا قصہ ذکر کیا کہ انہوں نے سب کچھ قربان کر دیا حتیٰ کہ اپنا گھوڑا بھی ذبح کر ڈالا اور اپنی ایک پڑوسن سے کہا: بچوں کو جگاؤ اور گوشت سنبھالو۔ وہ لوگ دوڑے آئے اور گھوڑے کا گوشت بھون کر کھانے لگے۔ حاتم نے حسرت بھری آہ نکال کر کہا: افسوس! تم لوگ تو کھا رہے ہو اور محلہ والے بھوکے ہیں۔ ان کے ہاں گئے، انہیں جگایا، وہ لوگ بھی دھڑا دھڑ آپہنچے اور حاتم خود ایک چادر اوڑھے کونے میں بیٹھ گئے یہاں تک کہ وہ لوگ خوب سیر ہو گئے۔ حاتم نے ان کے ساتھ ایک تکا بھی نہ چکھا۔"],[1998,"§۱۹۹۹ ۔ حمامی\nابن جرو بن واسع بن سلمہ بن حاضر ازدی ابو بکر بن درید بغوی کے دادا۔ ابن درید کہتے ہیں: جو خطیب نے اپنی سند کے ذریعہ ان سے روایت کی ہے: میرے دادا، ہمارے اجداد میں سے پہلے مسلمان ہونے والے شخص ہیں۔ اصل میں یہ ان ستر سواروں میں سے تھے جو سیدنا عمرو بن العاص رضی اللہ عنہ کے ساتھ عمان سے مدینہ کے لیے اس وقت نکلے جب انہیں رسول اللہ صلی اللہ علیہ وسلم کی بیوی کی وفات کی اطلاع ملی۔ بالآخر وہ مدینہ پہنچ گئے۔ اسی کے متعلق ان کا شاعر کہتا ہے: \"ہم عمرو کے ساتھ پہنچ گئے جس پر عمرو ایسا لگ رہا تھا جیسے تیز روی اور عاجزی نے پھینک دیا ہو۔\""],[1999,"§۲۰۰۰ ۔ (ز) حمران بن ابان\nسیدنا عثمان رضی اللہ عنہ کے آزاد کردہ غلام، اصلاً نمیر بن قاسط سے تعلق رکھتے ہیں: \"عین تمر\" سے گرفتار ہوئے۔ سیدنا عثمان رضی اللہ عنہ نے انہیں مسیب بن نجبہ سے خرید کر آزاد کر دیا۔ انہیں سیدنا عمر اور عثمان رضی اللہ عنہما وغیرہ سے سماع حاصل ہے۔ ان سے روایت کرنے والے ابو وائل وغیرہ ہیں۔ ابن سعد(1) فرماتے ہیں: وہ بصرہ فروکش ہوئے، ان کے بیٹے نے تمر بن قاسط میں (ہونے کا) دعویٰ کیا۔ میں کہتا ہوں: ابو عمر نے \"تمہید\" میں \"ہشام بن عروہ\" کے حالات میں ان کا نسب لکھا ہے۔ فرماتے ہیں: حمران جلیل القدر، رائے اور شرافت والے عالم تھے۔ قتادہ کا بیان ہے کہ وہ سیدنا عثمان رضی اللہ عنہ کے پیچھے نماز پڑھا کرتے تھے۔ آپ کو جب اٹکن ہوتی تو وہی لقمہ دیا کرتے تھے۔ بقول ابن معین: اہل مدینہ کے تابعی اور محدث ہو گزرے ہیں۔ خلیفہ نے سیدنا عثمان رضی اللہ عنہ کے گورنروں میں ان کا شمار کیا ہے، جبکہ ابن حبان(2) نے ثقات التابعین میں ان کا ذکر کیا ہے۔ ۷۰ھ کے بعد بصرہ میں بقول بعض ۸۵ھ، ۷۵ھ یا ۷۶ھ میں فوت ہوئے۔","",{"fn":"(1) الطبقات (۲۰۹/۵)\n(2) الثقات (۱۷۹/۴)"}],[2000,"§۲۰۰۱ ۔ حمرہ بن ایفع\nبن ربیب بن شراحیل بن ربیعہ بن یزید بن جشم بن حاشد بن جشم بن خیوان بن نوف بن ہمدان ہمدانی۔ ابن کلبی کا بیان ہے کہ انہوں نے دور فاروقی میں شام کی طرف ہجرت کی۔ ان کے ساتھ چار ہزار غلام تھے۔ ان سب کو آزاد کر دیا جنہوں نے ہمدان میں ہی نسبتیں قائم کر لیں۔"],[2001,"§۲۰۰۲ ۔ (ز) حمرہ\nابن عبد کلال بن عریب ریمینی، دور جاہلیت دیکھا ہے۔ سیدنا عمر رضی اللہ عنہ سے سماع حدیث کیا اور اس وقت ان کے ساتھ تھے جب وہ شام کے لیے پا برکاب ہوئے۔ امام بخاری(1) رحمہ اللہ نے ان کا ذکر کیا ہے اور ابو زرعہ نے صحابہ سے قریبی پہلے طبقہ میں ان کا تذکرہ کیا ہے۔ سیدنا عمر رضی اللہ عنہ کے صحبت یافتہ تھے۔ ابن یونس نے ان کا ذکر کیا کہ فتح مصر میں شریک تھے۔","",{"fn":"(1) التاریخ الکبیر (۱۲۸/۱)"}],[2002,"§۲۰۰۳ ۔ حملہ بن ابی معاویہ کنانی\nان پانچ افراد میں سے ایک ہیں جنہیں سیدنا سعد بن ابی وقاص نے یزدجرد کو اسلام کی دعوت دینے کے لیے اپنے لشکر سے روانہ کیا تھا۔ سیف نے ان کا ذکر کیا ہے۔"],[2003,"§۲۰۰۴ ۔ حملہ بن عبدالرحمن عکی\nانہیں دور نبوی نصیب ہوا۔ اور سیدنا عمر رضی اللہ عنہ کا یہ ارشاد سنا ہے کہ تشہد کے بغیر نماز نہیں ہوتی۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں ان کا ذکر کیا ہے۔"],[2004,"§۲۰۰۵ ۔ حمل بن معاویہ\nبن مرداس بن صباح شخصی۔ اشتر نخعی کے خاندان سے ہیں۔ اس وقت اشتر کے ساتھ تھے جب وہ سیدنا عمر رضی اللہ عنہ کے پاس آئے، فتوحات میں شریک رہے۔ اشتر کا ایک گھوڑا \"جنتریہ\" نامی تھا جس سے آگے کوئی نہیں نکل سکتا تھا۔ چنانچہ وہ اس کے اور اپنے چچا زاد کے بارے کہتے ہیں: \"حنتویہ مجھے لے کر لوگوں کی جس جگہ بھی پہنچا تو حمل اس کے لیے تلوار ثابت ہوا۔ وہ بنی صباح کا ایسا نوجوان ہے جو سخاوت سے خوش ہوتا ہے، خوبصورت چہرے والا ہے، کمینہ اور عاجز نہیں۔\" ابن کلبی نے اپنی کتاب \"فتوح الشام\" میں ان کا ذکر کیا ہے۔"],[2005,"§۲۰۰۶ ۔ (ز) حمید بن اعور\nبن ابی قرہ عقیلی، از بنی عامر بن عقیل مخضرمی ہیں: مرزبانی نے ان کا ذکر کیا ہے۔"],[2006,"§۲۰۰۷ ۔ حمید بن حوراء زبیدی\nحوراء ان کی والدہ ہیں، بحضرمی ہیں۔ ان کا بھی مرزبانی نے ذکر کیا ہے اور ان کے وہ اشعار نقل کیے ہیں جن میں سیدنا عمر رضی اللہ عنہ سے مخاطب ہیں: \"معد کی عورتوں میں سنت کو قائم رکھیے اس واسطے کہ اللہ تعالیٰ کے بعد آپ ہی ان کے والی اور امیر ہیں۔\""],[2007,"§۲۰۰۸ ۔ حنبص\nابن الاحوص بن ربیعہ بن سلامان بن کعب بن حارث بن سعد بن عمرو بن ذبل بن مروان بن جعفی بن سعد العشیرہ بھی۔ ابن کلبی فرماتے ہیں: شہسوار تھے، جاہلیت میں جنگیں لڑیں، اسلام کا دور پایا اور مسلمان ہو کر جنگ قادسیہ میں شرکت کی جس کے متعلق ان کی اہلیہ کہتی ہے: \"کاش! میری ساری قوم حنبص کی طرح ہوتی۔\""],[2008,"§۲۰۰۹ ۔ حنظل\nانہیں حنظلہ بن ضرار(1) بن حصین بھی کہا جاتا ہے۔ ابن مندہ حمید بن عبدالرحمن حمیری کے طریق سے بحوالہ حنظل بن ضرار روایت کرتے ہیں جو جاہلیت کے دور کے تھے پھر اسلام لے آئے۔ پھر ان کا قصہ ذکر کیا۔ بقول جاحظ: ان کی عمر اتنی ہو گئی تھی کہ انہوں نے جنگ جمل کا زمانہ دیکھا ہے جبکہ دولابی فرماتے ہیں: وہ جنگ جمل کے روز سو(۱۰۰) سال کی عمر میں شہید ہوئے۔ ایسا ہی عمر بن شبہ نے بحوالہ مدائنی نقل کیا ہے۔ فرماتے ہیں: سیدہ عائشہ رضی اللہ عنہا کا ارشاد ہے: جب تک حنظلہ(2) کی آواز آتی رہی میرا اونٹ اعتدال سے چلتا رہا۔","",{"fn":"(1) اسد الغابۃ (۱۲۷۶)\n(2) التاریخ الکبیر (۶۱۸/۱)"}],[2009,"§۲۰۱۰ ۔ (ز) حنظلہ بن اوس\nبن بدر تمیمی، مخضرمی ہیں۔ مرزبانی نے بحوالہ ابن ابی طاہر ان کا ذکر کیا ہے۔"],[2010,"§۲۰۱۱ ۔ حنظلہ بن جویہ کنانی\nحافظ ابن عساکر کا بیان ہے کہ نبی صلی اللہ علیہ وسلم کا دور پایا ہے اور جنگ یرموک میں شریک ہوئے۔ جبکہ ابو مخنف اپنے والد سے بحوالہ مکلبہ بن حنظلہ بن جویہ وہ اپنے والد سے روایت کرتے ہیں کہ وہ میسرہ (فوجی دستے کی بائیں جانب) میں تھے، ہمارے پاس سے عربوں کا ایک لشکر گزرا۔ پھر اپنا وہ قصہ ذکر کیا جس میں انہوں نے ایک عیسائی عربی سے مبارزت کر کے اسے قتل کر دیا تھا۔ اسی روایت کو دوسری سند سے ہانی بن عروہ کنانی کے طریق سے بحوالہ ملیکہ بن حنظلہ اسی مفہوم کی روایت درج کی ہے۔"],[2011,"§۲۰۱۲ ۔ (ز) حنظلہ بن ربیعہ\nبن عبد قیس بن ربیعہ بن کعب بن عبداللہ بن ابی بکر بن کلاب کلابی، انہیں دور نبوت نصیب ہوا۔ ان کا بیٹا \"حجاج\" کے ساتھ سیدنا عبداللہ بن زبیر رضی اللہ عنہ کے محاصرہ میں شریک تھا۔ پھر جرجان کا والی بن گیا اور مروان الحمار کے زمانہ میں قتل ہو گیا۔ ابن کلبی نے ان کا ذکر کیا ہے۔"],[2012,"§۲۰۱۳ ۔ (ز) حنظلہ بن شرقی\nابو لمحان قینی شاعر ابو عبیدہ بکری(1) نے \"شرح الامالی\" میں ذکر کیا ہے کہ وہ زمانہ جاہلیت میں زبیر بن عبدالمطلب کے (شراب نوشی میں) ہم مجلس تھے۔ پھر اسلام کا دور پایا۔ مرزبانی نے ان کا ذکر یوں کیا ہے: طویل عمر پانے والوں میں سے ایک ہیں۔ انہی کے یہ اشعار ہیں: وانی من القوم الذین ہم ہم اذا مات فیہم سید قام صاحبہ۔ \"میں اس قوم کا فرد ہوں کہ جس کا اتفاق کی یہ شان ہے کہ جب ان کا کوئی سردار داعی اجل کو لبیک کہتا ہے تو دوسرا اس کی جانشینی کر لیتا ہے\"۔ اضاءت لہم احسابہم و وجوہم دجی اللیل حتی نظم الجزع ثاقبہ۔ \"ان کے حسب اور چہروں نے انہیں اتنا روشن کر دیا کہ رات کی تاریکی میں اگر کوئی مہروں میں سوراخ کرنا چاہے تو آسانی سے کرلے۔\" بقول بعض: دور جاہلیت کی مدح سرائی میں یہ سب سے عمدہ نظم ہے۔ جمہرہ میں ابو عبید قاسم بن سلام لکھتے ہیں: جاہلی شاعر ہیں۔ ابو محمد بن قتیبہ اپنی کتاب \"کتاب الشعراء\" میں لکھتے ہیں: وہ زبیر بن عبدالمطلب کے ہاں قیام کرتے، پھر ان کے وہ اشعار نقل کرتے ہیں جن میں گناہوں مثلاً زنا، شراب خوری، خنزیر کا گوشت کھانے اور چوری چکاری سے براءت کا اظہار کرتے ہیں۔ ابن حمدون کی کتاب \"تذکرہ\" میں لکھا ہے کہ وہ دوسو(۲۰۰) سال تک زندہ رہے۔ یہی بات میں نے ابو مخنف کی کتاب \"المعمرین\" میں دیکھی ہے اور ان کے یہ اشعار نقل کیے ہیں: جنتني حادثات الدهر حتی کانی خاتل یدنو لصید۔ \"مجھے حوادث زمانہ نے ایسا توڑ مروڑ دیا، لگتا ہے میں کوئی تاک والا شکاری ہوں جو شکار کے قریب ہو رہا ہو\"۔ قریب الخطو یحسب من رانی ولست مقیدا انی بقید۔ \"جب میں چلتا ہوں تو قریب قریب قدم رکھنے کی وجہ سے دیکھنے والا مجھے بیڑی لگا سمجھتا ہے حالانکہ میں قید نہیں ہوں\"۔","",{"fn":"(1) سمط اللآلی (۳۳۲)"}],[2013,"§۲۰۱۴ ۔ (ز) حنظلہ بن طفیل\nبن مالک بن جعفر بن کلاب انہیں دور نبوی نصیب ہوا۔ حضرت عمر بن عبد العزیز کی اہلیہ ام البنین بنت ولید کی والدہ لیلیٰ بنت سہیل بن طفیل کے دادا ہوتے ہیں یہ زبیر بن بکار کا بیان ہے۔"],[2014,"§۲۰۱۵ ۔ (ز) حنظلہ بن فاتک اسدی\nخریم کے بھائی۔ مرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے کہ مخضرمی ہیں۔ ان کے گھوڑے کے متعلق ان کے اشعار بھی نقل کیے ہیں۔"],[2015,"§۲۰۱۶ ۔ (ز) حنظلہ بن نعیم غنوی\nدور نبوت ملا ہے۔ کنی میں دولابی لکھتے ہیں: ابو موسیٰ عنزی، محمد بن حسن عنزی، ابو عاصم وہ اپنے چچا غضبان بن حنظلہ بن نعیم سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: میں ان لوگوں میں تھا جو سیدنا عمر رضی اللہ عنہ کے پاس آئے تو وہ ہم میں سے ہر ایک ایک سے حال دریافت کرنے لگے۔ فرماتے ہیں: پھر ایک قصہ ذکر کیا۔ اس میں وہ حدیث ہے کہ یہاں ایک قبیلہ ہے یعنی عنزہ رہتا ہے جن کے خلاف بغاوت کی جائے گی مگر ان کی جائے گی۔"],[2016,"§۲۰۱۷ ۔ (ز) حنظلہ\nعلی کے والد۔ انہیں دور نبوت نصیب ہوا۔ عبدالواحد بن زیاد، شیبانی سے وہ جبلہ بن سعید سے وہ علی بن حنظلہ سے روایت کرتے ہیں، فرمایا: ایک دفعہ رمضان کے مہینہ میں ہم مدینہ میں تھے، ہم نے سمجھا شاید سورج غروب ہو چکا ہے جس کی بنا پر کچھ لوگوں نے روزہ افطار کر لیا۔ تھوڑی دیر بعد پتہ چلا کہ سورج ابھی غروب نہیں ہوا، جس پر سیدنا عمر رضی اللہ عنہ نے فرمایا: جس نے روزہ افطار کیا ہے وہ اس کی جگہ ایک روزہ رکھے۔"],[2017,"§۲۰۱۸ ۔ (ز) حنیف بن عمیر یشکری\nمرزبانی نے ان کا ذکر کیا ہے کہ مخضرمی ہیں۔ عمر بن شبہ نے ایک روایت کی ہے کہ جنگ یمامہ میں جب محکم بن طفیل قتل ہوئے تو انہوں نے یہ اشعار کہے: \"اے بنت اعمال! دل کے نکتے! میری ران نے مردوں کے فتنہ کو بڑھا دیا۔ اے سعاد! زمانے کی گردش تمہارے لیے دجال کے فتنہ جیسی ہے۔ یہ تم سے کس نے کہہ دیا۔ میرا دین، دین رسول صلی اللہ علیہ وسلم ہی ہے اور قوم میں مجھ جیسے لوگ ہدایت پر قائم ہیں۔ قوم نے محکم بن طفیل کو ہلاک کر دیا اور ان لوگوں نے جو ہمارے شمار میں مرد نہیں ہیں، کئی دفعہ ایسا ہوا کہ دل کی بات سے ڈرتا رہا کہ کیا ہو گا لیکن اس کا حل یوں ہو جاتا ہے جیسے گرہ کا کھلنا\"۔"],[2018,"§۲۰۱۹ ۔ حنیف بن یزید\nبن جعونہ عنبری۔ دور نبوت نصیب ہوا۔ جاحظ نے ذکر کیا ہے کہ وہ دعبل ختابہ کے ہم عمر تھے۔ دونوں عبداللہ بن عامر کے پاس اکٹھے بیٹھے تھے۔ دعبل نے ان سے کہا: حنیف تم کیسے سجاح کے دام میں پھنس گئے؟ (یعنی جس نے صدیق اکبر رضی اللہ عنہ کے دور میں دعویٰ نبوت کیا تھا، حنیف بھی اس کے متبعین میں شامل ہوئے تھے)۔ کہنے لگے: مجھے اس کا علم نہیں۔ پھر قصہ ذکر کیا۔"],[2019,"§۲۰۲۰ ۔ (ز) حوشب ذو ظلیم(1)\nابن طفیہ، بقول بعض: ابن کلثم۔ ابن الساعی بن عتبان بن ظلیم بن ذی استار وغیرہ بھی ان کے نسب کے متعلق کہا جاتا ہے۔ سیف نے فتوح میں روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جریر بن عبداللہ کو ذی الکلاع اور ذو ظلیم کی طرف بھیجا تھا۔ حوشب نے نبی صلی اللہ علیہ وسلم کے بعد ہجرت کی اور جنگ یرموک میں شرکت کی۔ ابن السکن، محمد بن عثمان بن حوشب سے وہ اپنے والد سے بحوالہ اپنے دادا روایت کرتے ہیں، فرمایا: جب اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کو رسول بنا کر ظاہر کیا تو میں نے آپ کی طرف عبد شتر کے ساتھ چالیس گھڑ سوار کو بھیجا، یہ لوگ میرا خط لے کر آپ کے پاس آئے۔ آپ نے اس سے پوچھا: تمہارا نام؟ وہ کہنے لگے: عبد شتر آپ نے فرمایا: \"نہیں تم عبد خیر ہو۔\" پھر ان سے اسلام کی بیعت لی۔ اور انہیں جواب لکھ کر دیا جو حوشب ذو ظلیم(2) کے پاس پہنچا، حوشب اسلام لے آئے۔ ابو عمر(3) فرماتے ہیں: اہل سیر کا اس پر اتفاق ہے کہ نبی صلی اللہ علیہ وسلم نے ان کی طرف جریر بن عبداللہ کو بھیجا تھا تا کہ وہ ذوالکلاع اور فیروز اسود کذاب کے مقابلہ میں باہمی مدد کریں۔ حوشب شام فروکش ہو گئے تھے اور جنگ صفین میں سیدنا معاویہ رضی اللہ عنہ کا ساتھ دیا۔ یعقوب بن شیبہ اور خلیفہ نے اس بارے میں ان کے کئی واقعات نقل کیے ہیں۔ علماء کا اس پر اتفاق ہے کہ وہ صفین میں شہید ہوئے۔ چنانچہ یعقوب بن سفیان اور ابراہیم بن دیزیل نے کتاب صفین میں اور بیہقی وغیرہ نے دلائل میں صحیح سند سے بحوالہ ابو وائل روایت کی ہے کہ عمرو بن شرحبیل نے خواب میں دیکھا کہ وہ جنت میں داخل ہوئے وہاں کچھ قبے بنے دیکھے، کہتے ہیں: میں نے پوچھا: یہ کس کے ہیں۔ بتانے والوں نے کہا: ذوالکلاع اور حوشب کے۔ میں نے کہا: عمار کہاں ہیں؟ وہ کہنے لگے: تمہارے سامنے۔ میں نے کہا: کیسے؟ جبکہ ان لوگوں نے ایک دوسرے کے مقابلہ میں جنگ کی ہے؟ کہنے لگے: جب ان کی اللہ تعالیٰ سے ملاقات ہوئی تو اللہ تعالیٰ کو وسیع مغفرت والا پایا۔","",{"fn":"(1) اسد الغابۃ (۱۲۹۸) استیعاب (۵۹۹) تجرید (۱۴۴/۱)\n(2) الجامع الکبیر (۳۸۷/۲)\n(3) استیعاب (۴۵۷/۱)"}],[2020,"§۲۰۲۱ ۔ (ز) حوط بن رئاب اسدی (شاعر)\nابو عبید بکری نے \"شرح الامالی\" میں لکھا ہے کہ مخضرمی ہیں جو ان اشعار کے قائل ہیں: دببت للمجد والساعون قد بلغوا جہد النفوس والقوا دونہ الازرا۔ \"مرتبہ حاصل کرنے کے لیے تو رینگتی چال چلا جبکہ پوری قوت سے دوڑنے والے پہنچ چکے اور اتنی تیزی سے دوڑے کہ اس سے پہلے ہی اپنے ازار پھینک آئے\"۔ مرزبانی نے ان کا یہ شعر نقل کیا ہے: یعیش الفتی بالفقر یوما وبالغنی وکل کان لم یلق حین یزابلہ۔ \"نوجوان کبھی فقر و فاقہ سے تو کبھی مالداری سے جیتا ہے لیکن جب ان سے جدائی ہوتی ہے تو یوں لگتا ہے اسے کچھ پہنچا ہی نہیں\"۔"],[2021,"§۲۰۲۲ ۔ حویرث بن رئاب\nانہیں دور نبوی حاصل ہوا۔ ان کا سیدنا عمر رضی اللہ عنہ کے ساتھ ایک واقعہ پیش آیا جس کا تقاضا ہے کہ وہ سیدنا عمر رضی اللہ عنہ کے زمانہ میں قابل اعتماد آدمی تھے۔ ابن ابی الدنیا نے اپنی کتاب \"مرنے کے بعد جو زندہ رہے\" میں لکھا ہے کہ ابو بکر مدائنی، احمد بن منصور، ابن عفیر، یحییٰ بن ایوب، ابن الہادی، محمد بن ابراہیم ان کے سلسلہ سند میں حویرث بن رہاب سے مروی ہے، فرمایا: ایک دفعہ میں گھنی جھاڑیوں میں تھا کہ اچانک قبر میں سے ایک انسان ہمارے پاس آ گیا جس کے چہرے پر آگ لگی تھی اور اس کا سر لوہے کی زنجیر سے بندھا ہوا تھا۔ آتے ہی وہ کہنے لگا: چھا گل سے مجھے پانی دینا! پانی دینا! اس کے پیچھے ایک اور آدمی نکلا، وہ فوراً بولا: کافر کو پانی نہ پلانا! کافر کو پانی نہ پلانا! اور آ کر اسے زنجیر سے پکڑا، اپنی طرف کھینچا اور بیڑی ڈال کر گھسیٹا، بالآخر دونوں اس قبر میں داخل ہو گئے۔ حویرث فرماتے ہیں: میں سواری سے اترا، مغرب اور عشاء کی نماز پڑھی اور سواری کا رخ مدینہ کی طرف کر دیا۔ سیدنا عمر رضی اللہ عنہ سے صبح ملاقات ہوئی، ان سے سارا قصہ بیان کیا، فرمانے لگے: مجھے تمہارے متعلق اطمینان ہے لیکن جو بات تم نے بتائی ہے انتہائی سخت ہے۔ پھر آپ نے اہل صفراء کے ان بوڑھوں کی طرف پیام بھیجا جنہوں نے جاہلیت کا دور دیکھا ہوا تھا، کہ اس نے مجھے یہ واقعہ سنایا ہے مجھے اس پر کوئی شک نہیں۔ حویرث! جو کچھ تم نے مجھے بتایا ہے، انہیں بھی بتانا۔ میں نے ان سے یہ واقعہ بیان کیا۔ انہوں نے کہا: امیر المومنین! ہم اسے (مرنے والے کو) جانتے ہیں۔ یہ بنی غفار کا ایک شخص تھا جو جاہلیت میں مرا تھا۔ سیدنا عمر رضی اللہ عنہ نے اللہ تعالیٰ کا شکر ادا کیا جب انہوں نے یہ کہا کہ جاہلیت میں مرا ہے، جس سے آپ کو خوشی ہوئی۔ پھر ان سے اس کے متعلق پوچھا، وہ کہنے لگے: وہ جاہلیت کے اچھے لوگوں میں سے تھا، البتہ مہمان کی کما حقہ مہمان نوازی نہیں کرتا تھا۔"],[2022,"§۲۰۲۳ ۔ حیاض بن قیس\nبن اعور بن تشیر بن کعب تشیری۔ ہشام بن کلبی کا قول ہے: جنگ یرموک میں شریک ہوئے۔ ان کے ہاتھوں کافروں کی خوب درگت بنی۔ بعض لوگوں کا کہنا ہے کہ انہوں نے ہزار کافر تہ تیغ کیے اور ایسے انہماک سے لڑ رہے تھے کہ خود ان کا پاؤں کٹ گیا، لیکن انہیں خبر تک نہ ہوئی۔ (جب ٹانگ نیچے نہ تھی) تو اسے تلاش کرنے لگے کہ کہاں گرا ہے۔ جس کے متعلق سوار بن ابی اوفی کہتے ہیں: \"ہمیں سے ابن عتاب اور اپنے پاؤں کو تلاش کرنے والا ہے اور ہمیں سے وہ شخص ہے جس نے قبیلہ کو حاجب دیا\"۔ مرزبانی نے ان کے وہ اشعار نقل کیے ہیں جن میں اپنا پاؤں کٹ جانے کے بعد اپنے گھوڑے سے مخاطب ہو کر کہتے ہیں: \"حذام! آگے بڑھ وہ تو عجم ہیں۔ نہ ملنے والے پاؤں سے دھوکا نہ کھانا۔ میں قشیری مہاجرین کا بھائی ہوں جو تلوار سے کافروں کی گردن قلم کرتا ہے\"۔ میں کہتا ہوں: اسی جیسے اشعار حارث بن سمی ہمدانی کے حالات میں گزر چکے ہیں۔"],[2023,"§۲۰۲۴ ۔ (ز) حیان بن وبرہ\nابو عتان مزنی۔ انہیں دور نبوی ملا ہے۔ ابو الحسن بن سمیع فرماتے ہیں: انہیں صدیق اکبر رضی اللہ عنہ کی معیت حاصل ہے، لیکن ان سے کوئی روایت منقول نہیں۔ ابو زرعہ دمشقی اپنی تاریخ میں عمرو بن شراحیل عبسی کے طریق سے روایت کرتے ہیں: میں اور عمرو بن شراحیل عبسی بیروت آئے۔ جس کے پراگندہ کپڑے ہیں وہ کیا تھے کھردرے کپڑے کی قمیص جو ان کی آدھی پنڈلی تک لمبی تھی۔ انہیں حیان بن وبرہ کہا جاتا تھا۔ میں نے عمیر سے پوچھا: کیا یہ صحابی رسول صلی اللہ علیہ وسلم ہیں؟ وہ کہنے لگے نہیں۔ البتہ صدیق اکبر رضی اللہ عنہ کا ساتھ نصیب ہوا ہے۔ ابن البرقی نے اسی روایت کو اپنی تاریخ میں اسی سند سے نقل کیا ہے، جس پر ان الفاظ کا اضافہ ہے: عمرو فرماتے ہیں: میں نے سنا کہ وہ ابو ہریرہ رضی اللہ عنہ کے حوالہ سے حدیث کرتا ہے، ابو ہریرہ رضی اللہ عنہ سے بھی ضرور سنا ہوگا۔ (عامر تقی ندوی) جبکہ دولابی نے یہ روایت اسی سند سے کنی میں معنی نقل کی ہے۔ امام بخاری رحمہ اللہ نے ان کا تذکرہ حسان نامی حضرات میں کیا ہے۔ حافظ ابن عساکر نے ان کا تعاقب کرتے ہوئے لکھا ہے: وہ حیان ہی ہیں، فرماتے ہیں: امام مسلم نے اس سلسلہ میں امام بخاری رحمہ اللہ کا اتباع کر کے غلطی کی ہے۔ انہیں اہل شام دوسروں کی بنسبت اچھی طرح جانتے ہیں۔ ابن ابی حاتم(1) بحوالہ اپنے والد روایت کرتے ہیں: عبداللہ بن سنان، حیان بن وبرہ سے یہ روایت کرتے ہیں کہ ایک دیہاتی نبی صلی اللہ علیہ وسلم کی خدمت میں آکر عرض کرنے لگا: مجھے کوئی دعا سکھائیں۔ (حدیث) ابو حاتم فرماتے ہیں: یہ مرسل روایت ہے۔","",{"fn":"(1) الجرح والتعدیل (۲۴۸/۳)"}],[2024,"§۲۰۲۵ ۔ حیویل بن ناشرہ\nبن عبد عامر بن ایم بن حارث کنعھی، ابو ناشرہ، انہیں دور نبوی نصیب ہوا، وہ قرہ بن عبدالرحمن بن حیویل کے دادا ہوتے ہیں۔ آپ صلی اللہ علیہ وسلم کا زمانہ با سعادت تو دیکھا ہے لیکن آپ صلی اللہ علیہ وسلم کی زیارت سے مشرف نہیں ہو سکے۔ فتح مصر میں شریک ہوئے اور جنگ صفین میں امیر معاویہ کا ساتھ دیا۔ انہیں عمرو بن عاص رضی اللہ عنہ سے روایت حاصل ہے۔ یک چشم گل تھے۔ ابن ابی سرح کے ساتھ ۳۱ھ میں دنقلہ کے روز ان کی آنکھ شہید ہوگئی۔"],[2025,"§۲۰۲۶ ۔ حیوہ بن جرول\nیا جندل بن احنف بن سمط بن امرئ القیس بن عمرو بن معاویہ بن حارث اکبر کندی، رجاء بن حیوہ کے والد، دور نبوی نصیب ہوا ہے۔ چنانچہ حافظ ابن عساکر رجاء بن حیوہ کے طریق سے وہ اپنے والد سے روایت کرتے ہیں کہ وہ معاذ بن جبل رضی اللہ عنہ کے پاس اپنے بیٹے سمیت آئے اور ان سے عرض کی: اس بچہ کو قرآن سکھائے۔ سیدنا ابو درداء رضی اللہ عنہ سے رجاء و ایمیہ کا سماع صحیح ہے۔ امرئ القیس بن عابس کے سوانح میں ان کا تذکرہ گزر چکا ہے۔"],[2026,"§۲۰۲۷ ۔ (ز) حیوہ بن مرثد تجیبی\nثم الاندائی از اولاد اندی بن عدی بن حجیب۔ انہیں دور نبوی نصیب ہوا۔ ابن یونس لکھتے ہیں: فتح مصر میں شریک تھے لیکن مجھے ان کی کسی روایت کا علم نہیں ہے۔"],[2027,"§۲۰۲۸ ۔ حاتم(1)\n(بے نسبت) کسی جھوٹے نے ان کا نام بنا لیا ہے۔ ابو اسحاق مستملی اور ابو موسیٰ اپنے طریق سے روایت کرتے ہیں کہ انہوں نے نصر بن سفیان بن احمد بن نصر سے سنا، میں نے حاتم کو فرماتے سنا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے اٹھارہ(۱۸) دینار میں خرید کر آزاد کر دیا پھر چالیس سال تک میں آپ کے ساتھ رہا۔ مستملی فرماتے ہیں: نصر فرماتے تھے کہ ان کی عمر ایک سو پینسٹھ(۱۶۵) سال ہے۔(2) میں کہتا ہوں: ان کے گمان کے مطابق حاتم مذکور دوسو(۲۰۰) سال کے آغاز تک زندہ رہے ہوں گے جو بذات خود محال ہے۔","",{"fn":"(1) اسد الغابۃ (۳۵۹)\n(2) جامع المسانید (۱۷۸/۳)"}],[2028,"§۲۰۲۹ ۔ حاتم بن عدی(1)\nیا عدی بن حاتم حمصی۔ تابعی ہیں جو مرسل حدیث بیان کرتے ہیں۔ عبدان نے ان کا صحابہ میں ذکر کیا ہے اور سالم بن غیلان کے طریق سے بحوالہ سالم بن ابی عثمان، حاتم بن عدی یا عدی بن حاتم سے روایت کرتے ہیں فرمایا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تک میری امت جلد افطاری اور تاخیر سے سحری کھائے گی اس وقت تک بھلائی میں رہے گی\"۔ یہ روایت انہوں نے ایسے ہی نقل کی ہے جس سے صحابی کا نام رہ گیا ہے۔ مسند احمد(2) میں یہ حدیث اسی سند سے منقول ہے جو حاتم بن عدی سیدنا ابو ذر رضی اللہ عنہ سے مروی ہے۔ ابن ابی حاتم(3) نے اس حدیث سے بحوالہ اپنے والد ان کا عنوان قائم کیا ہے۔ فرماتے ہیں: سیدنا ابو ذر رضی اللہ عنہ سے مروی ہے ان سے سلیمان بن ابی عثمان روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۸۳۸) تجرید (۹۵/۱)\n(2) مسند احمد (۱۷۴/۵)\n(3) الجرح والتعدیل (۲۵۸/۳)"}],[2029,"§۲۰۳۰ ۔ حارث بن اوس(1)\nبن نعمان انصاری۔ ابن مندہ نے ان میں اور حارث بن اوس بن معاذ بن نعمان میں جو سیدنا سعد بن معاذ کے بھتیجے ہوتے ہیں فرق کیا ہے، حالانکہ وہ وہی ہیں، ان کے نسب سے \"معاذ\" رہ گیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۵۰) تجرید (۹۵/۱)"}],[2030,"§۲۰۳۱ ۔ حارث بن بدل(1)\nانہیں حارث بن سلیم بن بدل اور عبد اللہ بن حارث بن بدل بھی کہا جاتا ہے۔ تابعی ہیں، صحابی نہیں۔ ان سے ایک روایت مروی ہے جو وہم پر مبنی ہے۔ ایک جماعت جیسے بغوی، مطین، باوردی اور ابن شاہین نے انہیں صحابہ میں ذکر کیا ہے۔ چنانچہ یہ سب حضرات بطریق معاذ، محمد بن عبداللہ شعثی سے بحوالہ حارث بن بدل روایت کرتے ہیں۔ فرمایا: میں حنین میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا، آپ صلی اللہ علیہ وسلم کے ساتھیوں کو شکست سے دوچار ہونا پڑا۔(2) (حدیث) اس روایت کو بکر بن بکار نے محمد بن عبداللہ سے روایت کیا ہے لیکن انہوں نے کہا: حارث بن سلیم بن بدل اور ایک بار یوں کہا: عبد اللہ بن حارث بن بدل۔ ولید بن مسلم بحوالہ شعثی، حارث بن بدل سے وہ اپنی قوم کے کسی شخص سے روایت کرتے ہیں۔ صدقہ بن خالد نے ان کی متابعت کی ہے۔ قاسم بن یزید جرمی بحوالہ شعثی، حارث بن بدل سے وہ سہیل ثقفی سے بحوالہ نبی صلی اللہ علیہ وسلم کہ علامہ ابن عبدالبر(3) فرماتے ہیں: شعثی کے زیادہ اضطراب کی وجہ سے یہ حدیث سنداً صحیح نہیں۔ امام بخاری(4) رحمہ اللہ اور ابن ابی حاتم نے انہیں تابعین میں شمار کیا ہے۔ ابو حاتم(5) فرماتے ہیں: حارث مجہول ہیں۔ امام شعثی کی کسی صحابی سے ملاقات نہیں ہوئی۔ ابن ابی حاتم فرماتے ہیں: اس میں بکر بن بکار نے خلط ملط کر دیا ہے۔ ابن سمیع اور ابو زرعہ دمشقی نے اہل شام کے تابعین کے تیسرے طبقہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۵۵)\n(2) المعجم الکبیر (۳۳۶۸/۳) الآحاد والمثانی (۱۶۱/۵) مجمع الزوائد (۱۸۱/۶) مختصر تاریخ دمشق (۱۴۷/۶) جامع المسانید (۱۹۵/۳) التاریخ الکبیر (۲۶۵/۱)\n(3) الاستیعاب (۲۸۳/۱)\n(4) ایضاً\n(5) الجرح والتعدیل (۶۹/۳)"}],[2031,"§۲۰۳۲ ۔ حارث بن بلال مزنی(1)\nایک تبدیل شدہ سند میں ان کا نام آتا ہے۔ درست بلال بن حارث ہے۔ بغوی، نعیم بن حماد کے طریق سے بحوالہ دراوردی، ربیعہ سے وہ بلال بن حارث بن بلال سے وہ اپنے والد سے حج کی عمرہ(2) میں مسخ کی وجہ سے تبدیلی کے بارے میں روایت کرتے ہیں۔ فرماتے ہیں: اس میں نعیم کو وہم ہوا ہے جبکہ روایت دراوردی سے بحوالہ ربیعہ، حارثہ بن بلال سے، ان کے والد بلال بن حارث سے مروی ہے۔ اسی طرح ایک جماعت نے ان سے نقل کیا ہے، یہی درست ہے۔ میں کہتا ہوں: اس روایت کو دراوردی نے اپنی مسند میں نعیم سے درست نقل کیا ہے۔ اس لئے ہوسکتا ہے کہ انہوں نے دو مرتبہ اسے بیان کیا ہو یا بغوی کے شیخ کو وہم ہوا ہو۔ سنن اربعہ میں حدیث دراوردی سے درست منقول ہے۔ اور ابو نعیم یعقوب بن محمد زہری، دراوردی سے، اسی سند کے ذریعہ ایک دوسری حدیث روایت کرتے ہیں۔ وہ بھی تبدیل شدہ ہے جسے طبرانی نے دوسری سند کے ذریعہ درست روایت کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۵۵)\n(2) جامع المسانید (۱۹۹/۳)"}],[2032,"§۲۰۳۳ ۔ (ز) حارث بن ثولاء\nعلامہ ابن عبدالبر نے، ابن السکن کی کتاب کے حاشیہ میں اپنے استدراک میں ان کا ذکر کیا ہے۔ جو وہم پر مبنی ہے جسے عبید اللہ بن معاذ کے طریق سے روایت کیا جاتا ہے۔ فرماتے ہیں: مجھے میرے والد نے بحوالہ محمد بن عبید اللہ بن مہاجر، حارث بن ثولاء سے روایت نقل کی ہے۔ فرمایا: میں حنین میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا۔ (حدیث) میں کہتا ہوں: درست حارث بن بدل ہے۔ ان کے حالات کی تفصیل اس قسم کی ابتداء میں گزر چکی ہے۔ لگتا ہے ابن عبدالبر اسے بھانپ گئے، اسی بنا پر انہوں نے استیعاب میں ان کا ذکر نہیں کیا۔"],[2033,"§۲۰۳۴ ۔ (ز) حارث بن حارث شامی\nمرسل حدیث روایت کرتے ہیں، جس کی وجہ سے بعض حضرات نے انہیں صحابہ میں ذکر کر دیا ہے۔ وہ حدیث بروایت شریح بن عبید ان سے قریش میں سے امراء کے متعلق مروی ہے۔ جیسا کہ قسم اول میں گزر چکا ہے انہیں غامدی بھی کہا جاتا ہے۔"],[2034,"§۲۰۳۵ ۔ حارث بن حکم سلمی(1)\nان کے نام میں تبدیلی بعض راویوں کی کارستانی ہے۔ ابن مندہ نے ان کا ذکر کیا ہے کہ درست حکم بن حارث ہے۔ میں کہتا ہوں: درست نام پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۷۰)"}],[2035,"§۲۰۳۶ ۔ حارث بن حکیم ضبی(1)\nابن شاہین نے ان کا ذکر کیا ہے۔ ابو موسیٰ نے ان کے طریق سے اور اپنی سند کے ذریعہ بحوالہ ان کے روایت کی ہے کہ ان کا نام عبد الحارث تھا، نبی صلی اللہ علیہ وسلم نے ان کا نام عبد اللہ رکھ دیا۔ ابن الاثیر(2) فرماتے ہیں: حارث میں انہیں ذکر کرنے کی کوئی وجہ نہیں بنتی۔ میں کہتا ہوں: ان کے کہنے کا یہ مقصد ہے کہ ان کا تذکرہ عبد اللہ میں کرنا چاہیے اور وہیں عبد الحارث کے بارے میں متنبہ کرنا چاہیے۔","",{"fn":"(1) اسد الغابۃ (۸۷۱) تجرید (۹۸/۱)\n(2) اسد الغابۃ (۳۷۱)"}],[2036,"§۲۰۳۷ ۔ حارث بن رافع(1)\nابن مکیث جہنی ان کی ایک مرسل حدیث ہے جس کی وجہ سے بعض لوگوں نے انہیں صحابہ میں ذکر کر دیا ہے۔ ابو موسیٰ ذیل میں بقیہ کے طریق سے بحوالہ عثمان بن زفر محمد بن خالد بن رافع بن مکیث وہ اپنے چچا حارث بن رافع سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"خوش اخلاقی بڑھوتری اور بد خلقی بے برکتی کا ذریعہ ہے۔\" اس حدیث کو ابو داؤد(2) نے حدیث بقیہ سے نقل کیا ہے۔ اور یہ بھی بیان کیا ہے کہ یہ حارث بن رافع، بحوالہ رافع کی روایت ہے۔ جبکہ حدیث رافع بن مکیث کے نام سے مشہور ہے جسے معمر نے عثمان بن زفر سے بحوالہ بنی رافع بن مکیث کے کسی فرد، رافع بن مکیث سے نقل کیا ہے۔ وہ حدیبیہ میں شریک ہوئے تھے۔ ابن حبان(3) نے ثقات التابعین میں ان کا ذکر کیا ہے کہ انہیں سیدنا جابر رضی اللہ عنہ سے بھی روایت حاصل ہے۔","",{"fn":"(1) اسد الغابۃ (۸۷۷) تجرید (۹۹/۱)\n(2) ابو داؤد کتاب الادب باب فی حق المملوک (۵۱۶۲) (۵۱۶۳)\n(3) الثقات (۱۳۰/۴)"}],[2037,"§۲۰۳۸ ۔ حارث بن زیاد شامی(1)\nبغوی نے صحابہ میں ان کا ذکر کیا ہے۔ اور حسن بن عرفہ نے قتیبہ سے بحوالہ لیث معاویہ بن صالح، یونس بن سیف بحوالہ حارث بن زیاد صحابی رسول صلی اللہ علیہ وسلم روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا امیر معاویہ رضی اللہ عنہ کو یہ دعا دی: اللھم علمہ الکتاب والحساب وقہ العذاب۔(2) \"اے اللہ! معاویہ کو کتاب (قرآن مجید) اور حساب سکھا اور اسے عذاب سے بچا۔\" یہ روایت ابن شاہین نے بغوی سے اسی طرح نقل کی ہے اور ہم نے بھی حسن بن عرفہ کے جزء میں عالی سند سے سنی ہے۔ ابن مندہ فرماتے ہیں: یہ قتیبہ یا حسن بن عرفہ سے وہم ہوا ہے، پھر اس روایت کو موسیٰ بن ہارون، بحوالہ قتیبہ بیان کیا لیکن اس میں \"صحابی رسول\" نہیں کہا۔ میں کہتا ہوں: اسی طرح اس روایت کو حسن بن سفیان نے قتیبہ سے نقل کیا ہے۔ ابن مندہ فرماتے ہیں: اسے آدم اور ابو صالح وغیرہ نے بھی روایت کیا ہے۔ جویریہ سے، معاویہ، یونس، بحوالہ حارث، ابو رہم، عرباض بن ساریہ سے مروی ہے۔ ایسے ہی یہ روایت عبد الرحمن بن مہدی نے ابن وہب، زید بن حباب اور معن بن عیسیٰ وغیرہ نے معاویہ سے نقل کی ہے۔ میں کہتا ہوں: ابن مہدی کی حدیث جو صحیح ابن حبان میں ہے وہی درست ہے۔ نیز ابن حبان(3) نے حارث بن زیاد کو ثقات التابعین میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۸۸۴) تجرید (۹۹/۱)\n(2) المعجم الکبیر (۶۲۸/۱۸) الصحیح لابن حبان مناقب الصحابہ (۷۲۱۰)\n(3) الثقات (۱۳۳/۴)"}],[2038,"§۲۰۳۹ ۔ حارث بن سعد(1)\nبغوی اور ابن شاہین نے ان کا ذکر کیا ہے اور دونوں نے بطریق عثمان بن عمر بحوالہ زہری، ابو خزامہ سے انہوں نے حارث بن سعد سے روایت کی ہے کہ انہوں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! جس دوا سے ہم لوگ علاج معالجہ کرتے ہیں اس کے متعلق آپ کی کیا رائے ہے؟... (حدیث) ابن معین فرماتے ہیں: اس میں عثمان بن عمر سے غلطی ہوئی ہے۔ یہ روایت زہری سے بحوالہ ابو خزاعہ جو بنی حارث بن سعد کے ایک فرد ہیں وہ اپنے والد سے روایت کرتے ہیں۔ میں کہتا ہوں: یہی درست ہے۔ ابو خزامہ کے والد کا نام یعمر ہے جیسا کہ یاء میں آئے گا۔ اس میں ابن شاہین سے ایک اور وہم ہوا ہے جسے میں نے سعد نامی حضرات کے سوانح میں حرف سین کے تحت ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۱۹۱)"}],[2039,"§۲۰۴۰ ۔ حارث بن سوید تیمی(1)\nابو عائشہ کوفی ابن مندہ نے ان کا ذکر صحابہ میں کیا ہے اور حمید اعرج کے طریق سے بحوالہ مجاہد حارث بن سوید کی ایک روایت نقل کی ہے کہ وہ نبی صلی اللہ علیہ وسلم کے ساتھ مسلمان تھے پھر اپنی قوم کے ساتھ مرتد ہو کر جا ملے لیکن پھر مسلمان ہو گئے۔ یہ حدیث حارث بن سوید انصاری کی ہے جیسا کہ درست گزر چکی ہے۔","",{"fn":"(1) اسد الغابۃ (۸۹۸)"}],[2040,"§۲۰۴۱ ۔ (ز) حارث بن سرار خزاعی\nطبرانی کے ہاں یونہی لکھا ہے۔ درست ابن ابی ضرار ہے۔"],[2041,"§۲۰۴۲ ۔ حارث بن ضرار(1)\nابن ابی ضرار خزاعی بھی کہا جاتا ہے۔ ابن عبدالبر(2) نے ان میں اور جویریہ کے والد میں فرق کیا ہے جبکہ ابن فتحون وغیرہ کا اعتماد اس پر ہے کہ جویریہ کے والد صاحب واقعہ کے علاوہ ہیں۔ سب نے کوئی تحقیقی کام نہیں کیا۔ درست یہ ہے کہ وہ ایک شخص ہی ہیں۔","",{"fn":"(1) اسد الغابۃ (۹۰۵) استیعاب (۴۲۴)\n(2) استیعاب (۴۲۴)"}],[2042,"§۲۰۴۳ ۔ حارث بن عاصم\nنووی نے اذکار میں حدیث ابو مالک اشعری \"طہارت ایمان کا حصہ ہے\" کے دوران ذکر کیا ہے کہ ان کا نام حارث بن عاصم ہے، جو وہم پر مبنی ہے حالانکہ وہ تو کعب بن عاصم یا حارث بن حارث ہیں۔"],[2043,"§۲۰۴۴ ۔ حارث بن عبد اللہ بجلی(1)\nابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے اور عبدان کے طریق سے ان کی سند کے ذریعہ معبد بن خالد جہنی سے روایت کی ہے۔ فرماتے ہیں: مجھے ضحاک بن قیس نے حارث بن عبد اللہ کی طرف بھیجا پھر ان کا وہ قصہ ذکر کیا جس میں یمن جانے کا ذکر ہے۔ وہ قصہ حارث بن عبد اللہ کے سوانح میں گزر چکا ہے۔ پھر جہنی کا قصہ ذکر کیا۔ ابن مندہ نے ان کا تذکرہ درست نقل کیا ہے لہذا ان کے بارے میں استدراک کی کوئی وجہ نہیں۔","",{"fn":"(1) اسد الغابۃ (۹۱۱)"}],[2044,"§۲۰۴۵ ۔ حارث بن عبد اللہ(1)\nبن ابی ربیعہ بن مغیرہ بن عبد اللہ بن عمر بن مخزوم، مخزومی۔ ایک مرسل حدیث روایت کرتے ہیں۔ بغوی نے ان کا ذکر کیا ہے اور عبد الکریم نے ابو امیہ کے طریق سے بحوالہ ان کے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا۔ کسی نے کہا: یا رسول اللہ!(2) یہ انصار کے کسی گھرانے کا نوکر ہے، ان کے پاس اس کے علاوہ اور کوئی خادم نہیں۔ چنانچہ آپ صلی اللہ علیہ وسلم نے اسے چھوڑ دیا۔ (حدیث) بغوی فرماتے ہیں کہ ہارون جمال نے صحابہ میں ان کا ذکر کیا ہے۔ جبکہ مجھے ان کے صحابی ہونے کا علم نہیں۔ میں کہتا ہوں: انہیں دیدار بھی نصیب نہیں ہوا اس واسطے کہ ان کے والد حبشہ میں پیدا ہوئے۔ ابن ابی حاتم(3) فرماتے ہیں: ان کی روایت کردہ حدیث مرسل ہے۔ قباع سے مشہور تھے۔ ابن زبیر رضی اللہ عنہ نے انہیں بصرہ کا گورنر بنایا تھا۔ مسلم نے بطریق ابن جریج، عبد اللہ بن عبید بن عمیر ان سے بحوالہ سیدہ عائشہ رضی اللہ عنہا ایک حدیث کعبہ کی تعمیر کے متعلق نقل کی ہے۔ امام بخاری(4)، ابن سعد اور ابن حبان(5) نے تابعین میں ان کا ذکر کیا ہے۔ حاکم(6) مستدرک کے حصہ کتاب الجہاد میں ابو اسحاق فزاری کے طریق، ابن جریج سے بحوالہ عبد اللہ بن ابی امیہ ان سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کسی غزوے میں مزینہ کے کچھ لوگوں کے ہاں سے گزرے تو وہاں کی کسی خاتون کے غلام نے آپ کے ساتھ چلنا شروع کر دیا۔ (حدیث) جس میں آپ نے غلام کو اپنی مالکن سے اجازت مانگ کر آنے کا حکم دیا تھا۔ فرماتے ہیں: اس کی سند صحیح ہے۔ ان سے یہ بات مخفی رہی کہ حارث صحابی نہیں ہیں۔ اسے بہتی نے بحوالہ حاکم نقل کیا لیکن اس کے مرسل ہونے پر متنبہ نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۹۱۲)\n(2) المصنف لعبد الرزاق (۱۹۸۹۳) المصنف لابن ابی شیبہ (۱۶۷/۱۲) کنز العمال (۳۳۸۴۶)\n(3) الجرح والتعدیل (۷۷/۳)\n(4) التاریخ الکبیر (۲۷۳/۱)\n(5) الثقات (۱۲۹/۴)\n(6) المستدرک (۱۰۴/۲)"}],[2045,"§۲۰۴۶ ۔ (ز) حارث بن عبدالمطلب\nابن ابی حاتم نے ان کا ذکر ان لوگوں میں کیا ہے جن کے والد کا نام عین سے شروع ہوتا ہے۔ فرماتے ہیں: کہ صحبت نبوی سے مشرف ہوئے آپ صلی اللہ علیہ وسلم نے انہیں مکہ کے کسی کام کی ذمہ داری بھی سونپی تھی۔ سیدنا ابو بکر و عمر اور عثمان رضی اللہ عنہم نے انہیں مکہ کا والی بنایا تھا۔ پھر وہ بصرہ منتقل ہو گئے۔ میں کہتا ہوں: انہیں اس میں بہت سخت وہم ہوا ہے۔ اس واسطے کہ یہ عنوان تو ان کے پوتے حارث بن نوفل بن حارث بن عبد المطلب بن ہاشم کا ہے جبکہ حارث بن عبدالمطلب تو دور جاہلیت میں وفات پا چکے تھے۔"],[2046,"§۲۰۴۷ ۔ حارث بن عتبہ(1)\nابن قانع نے ان کا ذکر کیا ہے اور سوید بن سعید کے طریق سے بحوالہ اسحاق بن ابی فروہ، عبید اللہ بن ابی رافع سے ان سے روایت کی ہے، فرمایا: میں نے نبی صلی اللہ علیہ وسلم کو ارشاد فرماتے سنا: \"فتح مکہ کے بعد (یہاں کے لوگوں کے لیے) ہجرت (لازم) نہیں رہی\"... (حدیث) ابن فتحون(2) نے ان کی پیروی کی ہے جو غلطی پر مبنی ہے۔ درست حارث بن غزیہ ہے۔ ابن قانع نے اس کا ذکر بیتی بن حمزہ کی روایت میں بحوالہ اسحاق درست ذکر کرنے کے بعد کیا ہے۔ متن کا سیاق، سوید کے سیاق سے زیادہ مکمل ہے۔","",{"fn":"(1) المعجم الکبیر (۲۶۲/۱۸) مجمع الزوائد (۲۵۰/۵) کنز العمال (۱۵۰۵۴)\n(2) اسد الغابۃ (۹۲۵)"}],[2047,"§۲۰۴۸ ۔ حارث بن عتیق(1)\nبن قیس انصاری۔ ابن شاہین نے ان کا ذکر کیا ہے کہ وہ ان کے والد اور ان کے چچا احد میں شریک ہوئے تھے۔ میں کہتا ہوں: درست نام حارث بن عتیک، پہلے درست نام گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۴۶)"}],[2048,"§۲۰۴۹ ۔ حارث بن قیس(1)\nبن حصن بن حذیفہ بن بدر فزاری۔ عسکری نے ان کا ذکر کیا ہے کہ وہ بنی فزارہ کے وفد میں تھے، اور فرماتے ہیں: انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے روایت کی ہے کہ وہ اور ان کے چچا عیینہ بن حصن کے پاس ٹھہرے تھے۔ اور اس گروہ سے ان کا تعلق تھا جنہیں عمر فاروق رضی اللہ عنہ نے اپنے قریب رکھتے تھے۔ میں کہتا ہوں: یہ قصہ صحیحین میں حر بن قیس کا ہے البتہ اس میں ہے کہ عیینہ اپنے بھتیجے حرب کے پاس ٹھہرے۔ یہی درست ہے۔ ادھر حر بن قیس کے حالات میں روایت کا سیاق اور ان کا بنی فزارہ کے وفد میں آنا گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۹۵۲)"}],[2049,"§۲۰۵۰ ۔ حارث بن کعب\nجاہلی دور کے ہیں۔ عبدان(1) نے ان کا ذکر کیا کہ میں نے احمد بن سیار کو فرماتے سنا: وہ جاہلی دور کے ہیں۔ وہ اپنے بارے میں بتاتے ہیں: وہ ایک سو ساٹھ(۱۶۰) سال زندہ رہے۔ انہوں نے اپنی اولاد کو جن اچھی باتوں کی وصیت کی ان سے پتہ چلتا ہے کہ وہ مسلمان تھے۔ میں کہتا ہوں: اس سے ان کا صحابی ہونا لازم نہیں ہوتا۔ کیونکہ اگرچہ وہ بعثت نبوی سے پہلے اور بعد کے ہیں لیکن صحابیت سے محروم ہیں۔ لہذا انہیں مخضرمین میں ذکر کرنا چاہیے۔","",{"fn":"(1) اسد الغابۃ (۹۶۰)"}],[2050,"§۲۰۵۱ ۔ حارث بن مخلد انصاری زرقی(1)\nتابعی ہیں جو مرسل حدیث نقل کرتے ہیں جس کی وجہ سے ابن شاہین نے انہیں صحابہ میں ذکر کر دیا۔ اور سہیل بن ابی صالح سے وہ اپنے والد سے وہ حارث بن مخلد سے روایت کرتے ہیں، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے عورتوں سے مقعد کے مقام سے صحبت کی اللہ تعالیٰ اس کی طرف (نظر رحمت سے) نہیں دیکھے گا۔\" اس حدیث کو اصحاب السنن وغیرہ نے کئی طرق سے بحوالہ سہیل، حارث بن مخلد(2) انہوں نے ابو ہریرہ رضی اللہ عنہ سے نقل کیا ہے۔ حدیث تو ابو ہریرہ رضی اللہ عنہ سے مشہور ہے اور حارث ابو ہریرہ رضی اللہ عنہ کے شاگردوں میں سے ہیں۔ تابعین میں انہیں امام بخاری اور ابن حبان وغیرہ نے ذکر کیا ہے۔ یہ مشہور نہیں۔ عبدان سعید بن معان کے طریق سے روایت کرتے ہیں کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو فرماتے سنا ہے، آپ نے حارث بن مخلد سے فرمایا: \"حارث! اگر مر سکتے ہو تو مر جاؤ۔\" پھر ایک قصہ ذکر کیا۔ اس وجہ سے انہیں صحابہ میں ذکر کر دیا، جو روایت انہوں نے نقل کی ہے اس میں تو ان کے صحابی ہونے کے بارے میں کوئی بات نہیں پائی جا رہی۔","",{"fn":"(1) جامع المسانید (۲۳۵/۳)\n(2) المعجم الکبیر (۳۲۵۱/۳)"}],[2051,"§۲۰۵۲ ۔ حارث بن وہب\nطبرانی نے ان کا ذکر کیا اور اشعث، ابو اسحاق، حارث بن وہب یا وہب بن حارث سے نقل کیا، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مکہ اور منیٰ میں دو رکعتیں پڑھیں۔ (حدیث) اشعث(1) نے ان کا نام یاد نہیں رکھا، وہ حارثہ بن وہب ہیں۔ کئی طرق سے صحیح روایت میں بحوالہ ابن ابی اسحاق یہ نام مروی ہے۔","",{"fn":"(1) اسد الغابۃ (۹۹۶)"}],[2052,"§۲۰۵۳ ۔ حارث بن وہب (دوسرے)\nالصنابحی سے روایت کرنے والے مشہور تابعی ہیں۔ مرسل حدیث نقل کرتے ہیں جس کی وجہ سے طبرانی نے ان کا ذکر صحابہ میں کر دیا اور ان کی وہ حدیث کی نقل کی جو کسی اور نے ان کے طریق سے بحوالہ صنابحی نقل کی ہے، وہی درست ہے۔"],[2053,"§۲۰۵۴ ۔ حارثہ بن حرام\nعبدان نے ان کا ذکر کیا اور ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور ان کے طریق سے اپنی سند سے روایت کی ہے کہ ان کی نبی صلی اللہ علیہ وسلم سے ملاقات ہوئی۔ آپ نے نبی صلی اللہ علیہ وسلم کو ایک شکار ہدیہ میں دیا جسے آپ صلی اللہ علیہ وسلم نے قبول فرمایا۔ (حدیث) درست حازم بن حرام ہے اس قصہ کو ابن مندہ نے بالکل درست نقل کیا ہے، لہذا وہم کی وجہ سے استدراک کی کوئی ضرورت نہیں۔"],[2054,"§۲۰۵۵ ۔ حارثہ بن ظفر(1)\nابن شاہین نے اسی حرف کے تحت ان کا ذکر کیا، جس میں ابو موسیٰ ان کے نقش قدم پر چلے۔ جبکہ ان دونوں کے علاوہ لوگوں نے حرف جیم میں عورتوں کے حالات میں ان کا تذکرہ کیا ہے، جو درست ہے۔","",{"fn":"(1) اسد الغابۃ (۱۰۰۰) استیعاب (۴۶۳)"}],[2055,"§۲۰۵۶ ۔ حارثہ بن عمرو\nبن موئل خواتین کے حصہ میں جیم میں ذکر ہو گا۔"],[2056,"§۲۰۵۷ ۔ حارثہ بن مالک(1)\nبن غضب بن حشم بن خرزج۔ پھر از بنی مخلد بن عامر بن زریق انصاری زرقی۔ واقدی نے شرکاء بدر میں ان کا ذکر کیا ہے اور ابن عبدالبر(2) کا بھی یہی قول ہے۔ ابو احمد حاکم کنی میں ابو عبد اللہ حارثہ بن نعمان کے حالات میں رقمطراز ہیں: انصار میں سے حارثہ نامی تین آدمی بدر میں شریک ہوئے۔ حارثہ بن سراقہ جو شہادت سے سرفراز ہوئے، حارثہ بن نعمان جو خلافت معاویہ تک بقید حیات رہے اور حارثہ بن مالک بن غضب۔ پھر واقدی تک اپنی سند سے بدر میں شہید ہونے والوں کا ذکر کیا ہے۔ بنی زریق بن عامر بن عبد سے حارثہ بن مالک بن غضب بن جشم بن خزرج پھر بنی مخلد بن عامر بن زریق، یہ ابو احمد کی آخری بات ہے۔ انہی کو سب سے پہلے اس میں وہم ہوا جس کی وجہ یہ بنی کہ انہوں نے واقدی کی کچھ بات نقل کی اور کچھ چھوڑ دی۔ اور یہ سمجھا کہ نسب عبد تک ختم ہو گیا ہے اور بدر میں ان کی حاضری کے بارے میں بتانے والے حارثہ ہیں، حالانکہ ایسا نہیں۔ اس واسطے کہ عبد حارثہ بن مالک، بدر میں شریک ہونے والے جد امجد ہیں۔ اصل میں یہ نام دو لفظوں سے مرکب ہے عبد اور حارثہ۔ اسی طرح کا وہم ابن مندہ کو پیش آیا ہے۔ وہ لکھتے ہیں: حارثہ بن مالک بن غضب بن جشم انصاری کا تعلق بنی بیاضہ سے ہے جو بیعت عقبہ میں شریک ہوئے تھے۔ یہی قول ابوالاسود کا بحوالہ عروہ ہے۔ چند تراجم و عنوانات کے بعد وہ لکھتے ہیں: حارثہ بن مالک انصاری کا تعلق بنی حبیب بن عبد سے ہے۔ وہ بدر میں شریک تھے۔ یہی ابن اسحاق کا قول ہے۔ پھر یونس بن بکیر تک اپنی سند سے بحوالہ ابن اسحاق شرکاء بدر کا ذکر کرتے ہیں: بنی حبیب بن عبد سے حارثہ بن مالک شریک ہوئے۔ انہیں بھی حاکم جیسا شبہ ہوا۔ کیونکہ ان کا گمان ہے کہ ان کے متعلق بدر میں شرکت کی اطلاع دینے والے حارثہ ہیں، حالانکہ ایسا نہیں۔ ابن اسحاق کی کتاب میں بدر میں شہید ہونے والے انصاری مسلمانوں کے نام کے متعلق ہے کہ بنی حبیب بن عبد حارثہ بن مالک بن غضب بن جشم سے رافع بن معلی، رافع بن معلیٰ ہی ان کے متعلق بتانے والے ہیں۔ وہ حبیب بن عبد حارثہ بن مالک بن غضب کی اولاد سے ہیں۔ عبد حارثہ ایک مرکب نام ہے جیسا کہ پہلے بھی گزر چکا۔ اور جو بات ابوالاسود کی طرف بحوالہ عروہ منسوب ہے اس کے متعلق بھی وہی قول ہے جو ابن اسحاق کی طرف منسوب بات کے متعلق ہے۔ ابن مندہ کو اس میں تردد ہوا کہ انہیں دو شخص قرار دیں۔ اس تقدیر کی بنا پر وہ واحد شخص ہیں جو اس نام میں غلطی سے سلامت رہے۔ ابن عبدالبر نے جو کچھ واقدی سے یہ نقل کیا ہے کہ حارثہ بن مالک بن غضب کو شریک بدر قرار دیا ہے، اس پر دمیاطی(3) نے انتہائی تنقید کی ہے اور کہا: وہ عبد حارثہ ہیں جو کسی صحابی کے آباء و اجداد میں شمار ہوتے ہیں جن کے درمیان کئی پشتوں کا فاصلہ ہے۔ اس میں ابن مندہ کے وہم پر ابو نعیم نے متنبہ کیا ہے۔ اور یہ گمان کیا کہ اس میں پہلے پہل مبتلا وہم ابن لہیعہ ہے۔ ابن الاثیر(4) نے بحوالہ ابن عبد البر نقل کیا ہے کہ واقدی کو بھی اس میں وہم ہوا ہے۔ ابن الاثیر لکھتے ہیں: واقدی کی \"مغازی\" میں ان کا ذکر نہیں۔ لگتا ہے انہوں نے \"انساب\" میں ان کا ذکر کیا ہے۔ اس میں ابن عبدالبر سے جو وہم ہوا وہ یہ ہے کہ ان کا نسب خزرج تک بیان کیا۔ پھر فرماتے ہیں: از بنی مخلد اور مخلد وہی ابن عامر بن زریق بن عبد حارثہ بن مالک بن غضب بن جشم بن خزرج ہیں جیسا کہ پہلے ذکر ہوا ہے۔ بھلا جد اعلیٰ اپنے بیٹوں کی اولاد میں سے کیسے ہو سکتا ہے؟ واللہ الموفق","",{"fn":"(1) استیعاب (۳۷۱/۱)\n(2) السیرۃ النبویۃ (۲۶۵/۲)\n(3) اسد الغابۃ (۴۰۶/۱)\n(4) استیعاب (۳۷۱/۱)"}],[2057,"§۲۰۵۸ ۔ حباب ابو عقیل\nطبرانی کے ہاں اسی طرح لکھا ہے۔ درست حجاب ہے، قسم اول میں صحیح طور پر گزر چکا ہے۔"],[2058,"§۲۰۵۹ ۔ حبان بن زید ابو خداش\nکنیوں میں ذکر ہو گا۔"],[2059,"§۲۰۶۰ ۔ حبہ بن حابس تمیمی(1)\nابن ابی عاصم(2) نے ان کا ذکر کیا ہے اور یحییٰ بن ابی کثیر کے طریق سے ان کی ایک روایت نقل کی ہے کہ مجھ سے حبہ بن حابس نے بیان کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"کھوپڑی میں کوئی چیز نہیں ہوتی، البتہ آنکھ کا لگنا برحق ہے۔\" اس میں دو جگہ غلطی ہوئی ہے۔ اول تو یہ نام حیہ یا سے ہے نہ کہ ہا سے۔ دوم یہ کہ انہوں نے یہ حدیث اپنے والد کے واسطہ سے نقل کی ہے اسی طرح یہ روایت امام احمد(3)، ترمذی(4) اور ابن خزیمہ نے کئی طرق سے بحوالہ یحییٰ بن ابی کثیر نقل کی ہے، جو درست ہے۔","",{"fn":"(1) اسد الغابۃ (۱۰۳۲)\n(2) الاحاد والمثانی (۳۹۰/۲)\n(3) مسند احمد (۶۷/۴) مجمع الزوائد (۱۰۶/۵)\n(4) ترمذی کتاب الطب باب ما جاء ان العین حق (۲۰۶۱)"}],[2060,"§۲۰۶۱ ۔ حبہ بن مسلم(1)\nعبدان نے صحابہ میں ان کا تذکرہ کیا ہے جبکہ وہ تابعی ہیں جو مرسل حدیث روایت کرتے ہیں جسے عبدان نے عبدالمجید بن ابی رواد کے طریق سے نقل کیا ہے اس کا ذکر عبدالملک بن حبیب نے بھی کیا ہے۔ دونوں بحوالہ اسد بن موسیٰ، ابن جریج سے فرمایا: حبہ بن مسلم نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"جو شخص شطرنج کھیلے اس پر لعنت ہے۔\" اسے ابن حزم(2) نے نقل کیا، فرمایا: حبہ مجہول شخص ہیں۔ اور سند منقطع ہے۔ ابن حبان فرماتے ہیں: حبہ نا معلوم فرد ہیں۔ فرماتے ہیں، بعض کا کہنا ہے: ان کا نسب یوں ہے: حبہ بن سلمہ، شقیق بن سلمہ کے بھائی، وہ بھی غیر معروف شخصیت ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۰۳۴) تجرید (۱۱۶/۱)\n(2) کنز العمال (۴۰۶۳۶) جامع المسانید (۲۶۰/۳)"}],[2061,"§۲۰۶۲ ۔ حبیب بن اساف انصاری خزرجی(1)\nطبرانی(2) اور ابن عبدالبر نے حرف حاء میں ان کا ذکر کیا ہے جو لفظی غلطی ہے۔ یہ نام تو خاء سے تصغیر کے ساتھ خیب ہے۔ خاء میں عبدان نے بھی ذکر کیا ہے کہ خبیب بن اساف قدیم بدری صحابی ہیں۔","",{"fn":"(1) اسد الغابۃ (۱۰۳۵) تجرید (۱۶۶/۱)\n(2) المعجم الکبیر (۲۴/۴)"}],[2062,"§۲۰۶۳ ۔ حبیب بن تیم\nاحد میں شہید ہوئے۔ یہ ابن ابی حاتم(1) کا قول ہے۔ اسی طرح ذہبی نے اپنے سے پیشرو لوگوں کی کتابوں سے اپنے استدراک میں ان کا ذکر کیا ہے۔ استدراک میں ذکر کرنے کی کوئی وجہ بنتی تو نہیں، کیونکہ یہی حبیب بن زید بن تیم ہیں جو اپنے دادا کی جانب نسبت کر کے بلائے جاتے ہیں۔ اپنے مقام پر ان کا صحیح ذکر ہوا ہے۔","",{"fn":"(1) الجرح والتعدیل (۹۷/۳)"}],[2063,"§۲۰۶۴ ۔ حبیب بن حمار اسدی(1)\nتابعی ہیں جنہوں نے ایک مرسل حدیث روایت کی ہے جس کی وجہ سے انہیں بھی عبدان نے صحابہ میں ذکر کر دیا۔ لکھتے ہیں: صحابی رسول صلی اللہ علیہ وسلم ہیں جو آپ صلی اللہ علیہ وسلم کے ساتھ سفر میں شریک رہتے۔ پھر بطریق زائدہ، اعمش سے، بحوالہ عبد اللہ بن حارث، عمرو بن مرہ سے حبیب بن حماز یہ روایت بیان کی ہے۔ فرمایا: ہم نبی صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے، لوگوں نے جلدی کی۔ (حدیث)(2) زائدہ کے علاوہ دیگر لوگوں نے اسی سند کے ذریعہ بحوالہ اعمش اس روایت کو نقل کیا ہے تو اس میں حبیب سے بحوالہ ابو ذر مروی ہے، فرمایا: ہم سفر میں تھے پھر وہ حدیث ذکر کی۔ امام بخاری(3)، ابن ابی حاتم(4)، ابن حبان اور دار قطنی وغیرہ نے حبیب کو تابعین میں ذکر کیا ہے۔","",{"fn":"(1) التجرید (۳۴)\n(2) اسد الغابۃ (۱۰۴۱) تجرید (۱۱۷/۱)\n(3) مسند احمد (۱۴۴/۵)\n(4) مستدرک (۴۲۶/۴)"}]])